INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('02b08cc6-e979-4629-a954-4453ef69bff4', 'c8174c42-363c-4fbd-8204-a8a0db5da2e4', 'nsclc', 'Isabel R. Preeshagul is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center with 13 years of career experience. The strongest signal is publication growth. Output increased from 8 papers (2016–2020) to 14 papers (2021–2025), while her collaborator network expanded substantially, from 77 collaborators to 176 across the same windows. Authorship has not yet included senior-authored output, and citation volume has not grown in parallel with publication count. A transition into senior authorship would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:56.025876+00', 'Collaborator network more than doubled, from 77 to 176, signaling rapid expansion of scientific connections.', 'Engage now around her expanding collaborator network and monitor closely for first senior-authored publication.', 'early', '{"No senior-authored output yet, and citation volume declined by 130, suggesting limited downstream impact of recent publications."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('044a564d-3b51-48bc-b939-40f6a70147e3', 'cf9d02be-332c-4cb3-9bfe-4ab155aea3c0', 'nsclc', 'Kerry L. Reynolds is an Emerging Leader in NSCLC based at Massachusetts General Hospital, now eight years into an independent career. Publication output grew from 6 papers (2016–2020) to 7 papers (2021–2025), a modest but steady increase, while the collaborator network expanded from 29 to 60 individuals across the same windows — more than doubling in raw count. The strongest signal is network growth. That expansion from 29 to 60 collaborators reflects a meaningful broadening of scientific relationships that often precedes increased research output. First evidence of a sustained increase in senior-authored publications would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:01.463195+00', 'Collaborator network more than doubled, from 29 to 60, signaling rapid expansion of scientific relationships.', 'Engage now around the expanding collaborator network to establish presence before external partnerships solidify.', 'early', '{"Citation volume declined by 471 in the recent window, suggesting existing work has not yet gained broad field traction."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('05b0656e-7f31-41fe-ba1b-1fc43b27ad1c', '687ca005-f6c3-4743-a632-f7b1405271d9', 'nsclc', 'Erica L. Carpenter is an Emerging Leader in NSCLC research at the University of Pennsylvania, now 15 years into her career. The strongest signal is network expansion. Her active collaborator count grew from 38 individuals in 2016–2020 to 83 in 2021–2025, a more than twofold increase in raw count. Publication output also increased, from 8 papers in 2016–2020 to 13 in 2021–2025, though senior-author share has been receding across the same period. A transition back into a sustained senior-authorship pattern would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:56.614375+00', 'Collaborator network more than doubled, from 38 to 83, signaling rapid expansion of scientific connectivity.', 'Engage now around the expanding collaborator network while monitoring for a return to senior-authored publications.', 'early', '{"Senior-author share is receding and citation volume declined by 478, raising questions about independent scientific ownership of output."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('06799847-e1e9-4c1e-a604-ed2e05e20885', '6cb1872f-0338-4784-9c49-66671becbed1', 'nsclc', 'Taher Abu Hejleh is a rising Lung Cancer investigator at the University of Iowa Hospitals and Clinics with 14 years of clinical and research experience. The defining feature of this profile is network expansion. His collaborator count grew more than fivefold, from 26 (Aug 2016–Jul 2021) to 140 (Aug 2021–Jul 2026), signaling meaningful integration into broader research communities. Publication output increased from 6 (Aug 2016–Jul 2021) to 9 (Aug 2021–Jul 2026), and his senior-author share rose between the two windows, reflecting a shift toward independent scientific contribution. A transition into first- or last-authored publications on multicenter Lung Cancer studies would represent the next meaningful milestone.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:40.856655+00', 'Collaborator count expanded fivefold, from 26 to 140, between the two most recent five-year windows.', 'Engage now around his expanding collaborator network to establish presence before external industry relationships solidify.', 'early', '{"Citation volume declined by 268 between the two windows, suggesting output growth has not yet translated into downstream scientific impact."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('08594c7c-b3d2-43df-aeb1-d67af1fca362', '13d15487-c38b-438e-b56e-5fac2dbafbe5', 'nsclc', 'Andrew J. Plodkowski is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center with 12 years of career experience. The strongest signal is authorship evolution. Between Aug 2021 – Jul 2026, senior-authored output appears in his record, a pattern absent in the Aug 2016 – Jul 2021 window, marking a meaningful shift in scientific independence. His publication output moved from 30 papers (Aug 2016 – Jul 2021) to 18 papers (Aug 2021 – Jul 2026), while his collaborator network shifted from 276 to 189 across the same windows. First evidence of a senior-authored publication in a high-impact Lung Cancer journal would mark a meaningful inflection in his profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:00.856776+00', 'Senior-authored output has emerged in Aug 2021 – Jul 2026, absent entirely from the prior five-year window.', 'Engage now around senior-authored work to establish early relationship before independent research agenda fully solidifies.', 'early', '{"Publication volume declined from 30 (Aug 2016 – Jul 2021) to 18 (Aug 2021 – Jul 2026), and collaborator count contracted by 87 across the same windows."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('0a6cbda8-3dad-4823-a2b5-ccdf6eadf38f', '9749ef49-d894-431c-adb1-569e3e9fd0e4', 'nsclc', 'Antonio Calles is an Emerging Leader in NSCLC based at Hospital General Universitario Gregorio Marañón, with 15 years of career experience and a Rising Star composite percentile of 72.4 (global rank 455). Publication output grew from 13 papers (2016–2020) to 21 papers (2021–2025), a 62% increase, supporting a Scientific Momentum percentile of 73. The strongest signal is network expansion. Collaborator count grew from 160 to 409 across the two periods, more than doubling, driving a Network Visibility percentile of 80. Senior-author share remains at zero across both periods, indicating Calles is still operating in a collaborative contributor role. A first senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:48:40.484265+00', 'Collaborator network more than doubled, from 160 to 409, driving a Network Visibility percentile of 80.', 'Monitor for transition into senior authorship as the natural next milestone to deepen engagement timing.', 'early', '{"Senior-author share is zero across both periods; independent scientific leadership has not yet been demonstrated in the publication record."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('0ad64a63-003c-4ab9-8f65-252d9cc353a8', '6cc72971-1a6d-4b5a-a6c6-817d3265e0c5', 'nsclc', 'Nikolaj Frost is an Emerging Leader in NSCLC based at Humboldt-Universität zu Berlin with 10 years of career experience, ranking 42nd globally with a Rising Star composite percentile of 97.5. Publication output increased nearly five-fold, from 7 papers (2016–2020) to 33 papers (2021–2025), accompanied by a citation volume growth of +516. The strongest signal is network momentum, which sits at the 92nd percentile. His collaborator base expanded from 42 to 229 individuals across the two periods, a more than five-fold increase. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:54:23.603854+00', 'Collaborator network expanded more than five-fold, from 42 to 229, driving 92nd-percentile network momentum.', 'Engage now around his expanding collaborator network while monitoring closely for first senior-authored NSCLC publications.', 'high', '{"Senior-author share remains at zero across both periods, indicating Frost has not yet assumed independent scientific leadership on publications."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('0bd58481-a93c-41fe-841b-8794d4bafba4', '848b93c1-d1d7-47f2-b19e-b5e7b1d6b1f7', 'nsclc', 'Alice Avancini is an Emerging Leader in NSCLC at the University of Verona, eight years into her career. Her publication output increased more than four-fold, from 5 papers (2016–2020) to 21 papers (2021–2025), driving a Scientific Momentum percentile of 83. The strongest signal is network expansion. Her collaborator count grew from 29 to 63 across the two periods, placing her at the 79th percentile for Network Momentum. Senior-author share remains at zero across both periods, which tempers the overall profile. First evidence of a senior-authored publication in NSCLC would mark a meaningful inflection in her independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:10:08.906242+00', 'Publication output quadrupled to 21 papers (2021–2025), pushing Scientific Momentum to the 83rd percentile.', 'Monitor for transition into senior authorship as the primary trigger for deeper scientific engagement.', 'early', '{"Senior-author share is zero across both periods, indicating no independent first-or-last authorship to date."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('0cc2a10e-707c-485f-b433-cf2bc445d568', '7353b33e-96cb-4dd2-be0c-9542a59224db', 'nsclc', 'Siddhartha Devarakonda is a rising Lung Cancer investigator at Washington University in St. Louis, now 13 years into his career. Publication output grew from 10 papers (Aug 2016–Jul 2021) to 13 papers (Aug 2021–Jul 2026), accompanied by a publication velocity delta of +1. The strongest signal is network expansion. His collaborator count grew from 43 (Aug 2016–Jul 2021) to 63 (Aug 2021–Jul 2026), a gain of 20 colleagues reflecting broadening scientific engagement. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021). A sustained pattern of senior-authored publications across multiple journals would represent the next meaningful milestone in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:00.650643+00', 'Collaborator network expanded from 43 to 63 alongside first emergence of senior-authored output.', 'Engage now around his expanding collaborator network to establish early relationship before senior authorship solidifies.', 'early', '{"Citation volume declined by 478 between windows, tempering the impact signal despite growing output and network."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('0d88b80d-f6e8-4bc3-854e-337635b0bc08', '5cf1c2ea-b02d-4e98-a8f1-ef66b3c01a0c', 'nsclc', 'Min Peng is a Balanced Rising Star in NSCLC at Wuhan University, now in year 10 of their career and ranked 36th globally with a composite percentile of 97.8. Publication output grew from 7 papers (2016–2020) to 12 (2021–2025), while citation volume increased by 103, reflecting deepening scientific engagement. The strongest signal is network momentum, which sits at the 98th percentile. Collaborator count expanded more than seven-fold, from 25 to 176 individuals across the two periods. This profile is characteristic of a Balanced Rising Star building broad scientific reach; a transition into senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:05:35.485349+00', 'Collaborator network expanded seven-fold, from 25 to 176, placing network momentum at the 98th percentile.', 'Engage now around the expanding collaborator network; monitor closely for first senior-author publication as a key inflection point.', 'high', '{"Senior-author share remains at zero across both periods, meaning scientific output is entirely as a non-senior contributor to date."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('0daf3a86-79c4-422d-839e-f5f9e4accc8d', '0ae5152e-fb98-41cf-9fce-e9f487a02382', 'nsclc', 'Collin M. Blakely is a rising Lung Cancer investigator at the University of California, San Francisco with 15 years of experience. The strongest signal is publication growth. Output increased from 15 papers (Aug 2016 – Jul 2021) to 26 papers (Aug 2021 – Jul 2026), while his collaborator network expanded more than fourfold, from 124 to 496 individuals across the same windows. Senior-author share held steady between the two windows, indicating sustained independent scientific contribution rather than a shift toward supporting roles. First evidence of Blakely anchoring a multicenter trial or consensus guideline effort would mark a meaningful inflection in his broader field presence.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:25.279847+00', 'Collaborator network grew fourfold to 496 individuals (Aug 2021 – Jul 2026), signaling rapid network expansion.', 'Engage around the rapidly expanding collaborator network to identify emerging multicenter research partnerships and consortium opportunities.', 'early', '{"Citation volume declined by 698 between the two windows, suggesting output growth has not yet translated into increased downstream scientific impact."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('0ebb9979-c5b8-459f-b355-8c866693fc47', 'bcccedbe-b017-44ce-9327-3540be278736', 'nsclc', 'Rebecca Pharaon is an Emerging Leader in NSCLC based at City Of Hope National Medical Center, with 8 years in the field. The strongest signal is citation growth. Her 8 publications from 2021–2025 have accumulated 134 additional citations compared to the prior window, reflecting meaningful uptake of her work by the broader research community. Her collaborator network has shifted from 31 partners in 2016–2020 to 23 in 2021–2025, suggesting a move toward more focused, selective research relationships. No senior-authored output has appeared to date; a first senior-authored publication would represent the next meaningful milestone in her development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:19:06.593463+00', 'Citation volume grew by 134 while publication output held steady at 8 papers in 2021–2025.', 'Early relationship-building now, with close monitoring for a first senior-authored NSCLC publication as the key inflection point.', 'early', '{"No senior-authored output has been recorded yet, limiting evidence of independent scientific leadership in NSCLC."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1033b02e-889a-4bd9-aa88-18d4e09397df', '807a941b-eeb3-4cb1-b8a8-8b18c05e3112', 'nsclc', 'Jiajia Zhang is an Emerging Leader in NSCLC based at Bloomberg (United States), with 9 years of career activity. Publication output grew from 5 papers (2016–2020) to 8 papers (2021–2025), reflecting a steady increase in research productivity. The collaborator network expanded from 74 to 80 individuals across the same windows, indicating broadening scientific connections. The strongest signal is authorship positioning. No senior-authored output has appeared yet, meaning the profile remains in a contributor rather than directing role. A transition into senior or last authorship would represent the next meaningful milestone in this researcher''s development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:53.517592+00', 'Publication output grew from 5 to 8 papers, alongside a collaborator network expanding to 80.', 'Early relationship-building now, with active monitoring for a first senior-authored NSCLC publication as the key trigger.', 'early', '{"No senior-authored output yet; Zhang remains in a contributor role, limiting independent scientific influence at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('109a5da5-7528-4c78-985b-98dbbec47146', 'a5ea2f0e-d151-4bdd-b003-21834bfb8da5', 'nsclc', 'Mark T.A. Donoghue at Memorial Sloan Kettering Cancer Center is an Emerging Leader in NSCLC with a composite Rising Star percentile of 62.8 (rank 85 in the US). Publication output grew modestly from 5 to 7 papers across the two periods, while the strongest signal is network expansion. His collaborator count grew nearly threefold, from 66 to 190 unique collaborators, lifting Network Momentum to the 65th percentile and Network Visibility to the 73rd. Senior-author share remains at zero across both periods, making authorship role evolution the key variable to monitor. A first appearance as senior author on an NSCLC-focused manuscript would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:13:56.746013+00', 'Collaborator network nearly tripled from 66 to 190, driving Network Visibility to the 73rd percentile.', 'Engage around his expanding collaborator network now; monitor closely for first senior-author publication as a relationship-deepening trigger.', 'early', '{"Senior-author share is zero across both periods; contributions may reflect collaborative or junior roles rather than independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('10a219d7-a5e9-45ae-9c8a-b39bb83cad43', '11a226e4-f635-4772-825d-79e144e81e32', 'nsclc', 'Christina S. Baik is a rising Lung Cancer investigator at the University of Washington whose research output has grown substantially across successive five-year windows. The strongest signal is publication volume. From Aug 2021 – Jul 2026 she authored 26 papers, up from 15 in Aug 2016 – Jul 2021, nearly doubling output across the two periods. Her collaborator network expanded from 121 individuals (Aug 2016 – Jul 2021) to 255 (Aug 2021 – Jul 2026), more than doubling in raw count, while senior-author share held steady across both windows. A transition into consistently first- or last-authored high-impact journal publications would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:25.421779+00', 'Publication output nearly doubled and collaborator network more than doubled across the two most recent five-year windows.', 'Engage around her expanding 255-person collaborator network to explore potential investigator-initiated research partnerships.', 'early', '{"Citation volume declined by 827 across the two windows, tempering the otherwise strong publication and network growth signals."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1234283f-3300-4c24-873e-cb078201af5f', '6c2196cf-30d3-46df-971b-822a428a46e2', 'nsclc', 'Meghan J. Mooradian is a rising Lung Cancer investigator at Massachusetts General Hospital whose profile is defined by a sharp expansion of her collaborative network. Her collaborator count nearly doubled, growing from 74 (Aug 2016–Jul 2021) to 133 (Aug 2021–Jul 2026). The strongest signal is authorship evolution: senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), indicating a meaningful shift in scientific responsibility. Publication volume moved from 12 (Aug 2016–Jul 2021) to 7 (Aug 2021–Jul 2026), with a publication velocity delta of +2. First evidence of senior-authored work in a high-impact Lung Cancer journal would mark a meaningful inflection in her independent scientific voice.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:09:16.534263+00', 'Her collaborator network nearly doubled, from 74 to 133, while senior authorship emerged for the first time.', 'Engage now around her expanding collaborator network and emerging senior authorship to build an early relationship.', 'early', '{"Publication volume declined from 12 to 7 across the two windows, and citation volume growth is negative, warranting close monitoring."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('128f0819-6a73-45b8-a2e8-eecda069f0ec', '7e61af52-a979-4b2f-b758-f0a45a1eeaa0', 'nsclc', 'Jin Shi is a Balanced Rising Star in NSCLC, ranked 100th globally with a composite Rising Star percentile of 94.0. Scientific momentum is the dominant driver, reaching the 95th percentile: publication output grew from 5 to 7 papers across periods while citation volume expanded by 123 citations. The strongest signal is network momentum, which sits at the 96th percentile. Collaborator count grew more than five-fold, from 24 to 124 individuals, in a single period transition. First evidence of a senior-author credit in an upcoming publication would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:11:21.918395+00', 'Collaborator network expanded more than five-fold, from 24 to 124, driving a 96th-percentile network momentum score.', 'Engage now around the expanding collaborator network while monitoring closely for first senior-author publication.', 'moderate', '{"Senior-author share remains at zero across both periods, meaning independent scientific ownership is not yet established."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('12cedcf1-75ea-45e0-944b-b7ef553d3e73', '75bad9ff-9965-4fef-990b-ac9a2702735f', 'nsclc', 'Qiuxiang Ou is an Emerging Leader in NSCLC with 10 years of career activity based at Genesee Community College. The strongest signal is publication output. Output doubled from 17 papers (2016–2020) to 34 papers (2021–2025), reflecting a sustained increase in research productivity. Alongside this, the collaborator network expanded from 113 to 224 individuals across the same windows, indicating broadening scientific connectivity. No senior-authored output has appeared to date. A first senior-authored publication in NSCLC would represent the next meaningful milestone in this profile''s development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:50.401808+00', 'Publication output doubled to 34 papers (2021–2025) alongside a collaborator network that reached 224.', 'Monitor for first senior-authored NSCLC publication as the trigger for deeper MSL relationship-building.', 'early', '{"No senior-authored output has been recorded yet, and citation volume has declined, limiting evidence of downstream scientific impact."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1314c5f8-fb6c-4fdd-a4be-2fe6dce23244', '5817d556-8f00-4849-9eee-e02b8316bcac', 'nsclc', 'Robert J. Cardnell is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, now 11 years into his career. Publication output more than doubled, from 5 papers (2016–2020) to 11 papers (2021–2025), accompanied by a citation volume growth of 228 additional citations. The strongest signal is network expansion. His collaborator base grew nearly threefold, from 46 collaborators (2016–2020) to 136 collaborators (2021–2025), indicating deepening integration across the research community. Senior-authored output has not yet appeared in the record; a first senior-authored publication would mark a meaningful inflection in independent scientific standing.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:30.861707+00', 'Collaborator network nearly tripled to 136, alongside doubled publication output and 228 additional citations.', 'Engage now around his expanding collaborator network and monitor for first senior-authored publication as a relationship milestone.', 'early', '{"No senior-authored output has been recorded yet, limiting evidence of independent scientific leadership at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('14ea1c55-edc7-4fee-b38e-009aa34db3d4', 'fbf486b9-353d-4194-8530-7702fdf70364', 'nsclc', 'Emanuele Vita is an Emerging Leader in NSCLC based at Università Cattolica del Sacro Cuore with 8 years of career experience. Publication output nearly tripled, from 9 papers (2016–2020) to 25 papers (2021–2025), reflecting sustained scientific productivity. The strongest signal is network expansion. Collaborator count grew from 77 to 214 between the two periods, a nearly threefold increase, placing network momentum at the 76th percentile globally. Scientific momentum sits at the 50th percentile, anchored by publication volume growth but tempered by a 42% decline in citation volume. First evidence of senior authorship would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:44:37.139421+00', 'Collaborator network nearly tripled, from 77 to 214, driving network momentum to the 76th percentile.', 'Engage around the expanding collaborator network and monitor closely for a first transition into senior authorship.', 'early', '{"Senior-author share remains 0 across both periods, suggesting limited independent scientific ownership to date."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('159f3a28-2fb0-421d-84e0-38f0d7f73d52', 'deb5cf69-8fa0-43a6-9916-0bb0498a09b2', 'nsclc', 'Liyun Miao is an Emerging Leader in NSCLC based at Nanjing Drum Tower Hospital, with 15 years of career experience and a Rising Star composite percentile of 96.7, ranking 56th globally. Publication output increased more than 2.6-fold, from 13 papers (2016–2020) to 34 papers (2021–2025), accompanied by a citation volume growth of +808. The strongest signal is network expansion. Collaborator count grew more than five-fold, from 90 to 466 individuals, placing network visibility at the 99th percentile globally. Senior-author share remains at zero across both periods, which contextualizes the breadth of collaboration. First evidence of a senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:58:29.417256+00', 'Collaborator network expanded five-fold to 466, driving a 99th-percentile network visibility score.', 'Engage now around the expanding collaborator network; monitor closely for first senior-authored NSCLC publication as a relationship-deepening trigger.', 'high', '{"Senior-author share is zero across both periods; output growth may reflect collaborative participation rather than independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('165226ac-32b3-47f9-b369-b0a4bdc173ca', '272f5194-9380-411c-bac1-dbb64830e197', 'nsclc', 'Jose M. Pacheco is an Emerging Leader in NSCLC based at the University of Colorado Cancer Center, now 13 years into his career. The strongest signal is network expansion. His active collaborator base grew from 66 individuals in 2016–2020 to 114 in 2021–2025, a near-doubling in raw count that reflects broadening scientific engagement across the field. Citation volume has grown by 2,001 over the same span, indicating that his published work is accumulating meaningful downstream use. He has maintained 10 publications in 2021–2025 following 13 in 2016–2020, with no senior-authored output yet recorded; a first senior-authored publication would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:37.006986+00', 'Collaborator network nearly doubled from 66 to 114, alongside citation volume growth of 2,001.', 'Engage now around his expanding collaborator network and monitor for first senior-authored publication.', 'early', '{"No senior-authored output has been recorded to date, limiting evidence of independent scientific direction."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('181db383-6e67-4c8f-b5f6-03231d88786a', 'd3b3c6a2-446d-4913-be99-403900bbd801', 'nsclc', 'Pamela Samson is an Emerging Leader in NSCLC based at Washington University in St. Louis, now 12 years into her career. The strongest signal is her collaborator network expansion. Her active collaborators grew from 48 in 2016–2020 to 91 in 2021–2025, nearly doubling in raw count and reflecting a broadening scientific footprint. Publication output also increased, from 13 papers in 2016–2020 to 16 in 2021–2025, though citation volume has not yet grown in step with that output. A transition into senior-authored publications would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:02.564853+00', 'Collaborator network nearly doubled, from 48 to 91, signaling rapidly expanding scientific connectivity in NSCLC.', 'Engage now around her expanding collaborator network and monitor closely for first senior-authored NSCLC publication.', 'early', '{"No senior-authored output yet, and citation volume has declined by 275, suggesting limited downstream impact of recent publications."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1b92ef5f-ee98-4264-b092-39f1657f9e7d', '96c62709-b540-454d-b71f-d80bb8176072', 'nsclc', 'Joshua E. Reuss is a rising Lung Cancer investigator at Georgetown University whose research output has grown more than four-fold, from 6 publications in Aug 2016–Jul 2021 to 25 publications in Aug 2021–Jul 2026. The strongest signal is publication velocity. That output accelerated by a delta of +2 papers per year between the two windows, accompanied by a citation volume increase of +430 across the same period. His collaborator network expanded from 71 to 221 individuals, a more than three-fold increase from Aug 2016–Jul 2021 to Aug 2021–Jul 2026. Notably, senior-authored work appears in the recent window but was absent in the earlier one. A sustained pattern of senior-authored publications in high-impact Lung Cancer journals would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:41.69629+00', 'Publication output more than quadrupled, from 6 to 25 papers, with citations rising by 430 in the recent window.', 'Engage now around emerging senior authorship and expanding collaborator network to build an early peer relationship.', 'moderate', '{"Senior authorship is newly emerging in the recent window only; consistency across multiple senior-authored outputs is not yet established."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1c1db27b-d40e-4106-ad2d-605c63816bfa', '6413db7b-0293-45a2-8fcd-9a5169e31fb7', 'nsclc', 'Tran C. Thai is an Emerging Leader in NSCLC based at Dana-Farber Cancer Institute, now 12 years into an active research career. Publication output grew from 5 papers (2016–2020) to 7 papers (2021–2025), a modest but consistent increase in productivity. The strongest signal is network expansion. Collaborator count rose from 66 (2016–2020) to 73 (2021–2025), suggesting broadening scientific relationships even as authorship has not yet extended to senior-authored work. A transition into senior or last authorship would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:09.387373+00', 'Collaborator network expanded from 66 to 73 peers alongside steady publication growth across both windows.', 'Early relationship-building now, with close monitoring for a first senior-authored publication as the key inflection point.', 'early', '{"No senior-authored output has emerged yet, and citation volume declined, limiting evidence of independent scientific influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1d1708f0-a569-4088-913d-cdef5454b987', 'c437ea46-643b-4065-a708-e3c2e1d90e7b', 'nsclc', 'Sara Elena Rebuzzi is an Emerging Leader in NSCLC with a Rising Star composite percentile of 84.9 (global rank 250), driven overwhelmingly by momentum rather than current visibility. Publication output grew from 5 papers (2016–2020) to 8 (2021–2025), while citation volume expanded by 222 citations, signaling increasing uptake of her work. The strongest signal is network momentum, ranked at the 83rd percentile. Her collaborator base more than doubled, growing from 40 to 103 unique collaborators across the two periods. A transition into senior authorship, currently at zero across both periods, would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:13:20.637986+00', 'Citation volume surged by 222 and collaborators grew from 40 to 103 in five years.', 'Monitor for first senior-authored publication as the primary trigger for proactive relationship-building.', 'early', '{"Senior-author share remains zero across both periods, limiting independent scientific ownership signals despite strong momentum."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1d1cf71c-d7ce-4575-bec7-15f06a9fde4d', '5e4f7bbe-071f-4234-a77a-a6519882e1b5', 'nsclc', 'Roxana Reyes is an Emerging Leader in NSCLC based at Hospital Clínic de Barcelona with 7 years of career experience and a Rising Star composite percentile of 85.2 (global rank 244). Her publication output nearly tripled, from 5 papers (2016–2020) to 14 papers (2021–2025), while her collaborator network expanded more than six-fold, from 20 to 123 individuals over the same periods. The strongest signal is network momentum, which sits at the 89th percentile. Scientific momentum supports this at the 83rd percentile, though citation volume growth is currently negative at -5. First evidence of a senior-author credit on a peer-reviewed NSCLC publication would mark a meaningful inflection in her independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:04:57.781704+00', 'Collaborator network grew six-fold, from 20 to 123, driving a 89th-percentile network momentum score.', 'Engage now around her expanding collaborator network; monitor closely for first senior-authorship credit as a trigger for deeper scientific dialogue.', 'moderate', '{"Senior-author share remains zero across both periods, and citation volume growth is negative (-5), limiting independent scientific attribution."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1d3d06be-3b36-45cf-89ca-4692fd9b4e61', 'fb831bca-1f2d-4add-998b-eeb6a969e32e', 'nsclc', 'Emily S. Chambers is an Emerging Leader in NSCLC based at Dana-Farber Cancer Institute, with 10 years of career activity. She has maintained a consistent publication presence, producing 6 papers from 2016–2020 and 5 papers from 2021–2025, while her collaborator network has held steady at 52 to 53 individuals across the same windows. The defining feature of the profile is network stability. Collaborator count grew by just one, from 52 to 53, signaling a consolidated rather than expanding peer base. No senior-authored output has appeared to date. A first senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:22.550475+00', 'Sustained publication output across both five-year windows at a well-regarded institution signals consistent NSCLC engagement.', 'Early relationship-building now, with close monitoring for a first senior-authored NSCLC publication as the key activation trigger.', 'early', '{"No senior-authored output yet, and citation volume declined by 133, suggesting limited downstream impact on the field so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1f929c92-64a4-402d-ae90-ffbe2dbb3f60', 'f4024aa0-218c-4863-88d6-08a6182f96dd', 'nsclc', 'Jacqulyne Robichaux is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center, now a decade into her career. Her publication output grew from 8 papers (Aug 2016–Jul 2021) to 11 papers (Aug 2021–Jul 2026), accompanied by an increase in publication velocity of one additional paper per year. The strongest signal is her authorship evolution: senior-authored work appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window, indicating a meaningful shift in scientific independence. Her collaborator network expanded from 110 (Aug 2016–Jul 2021) to 137 (Aug 2021–Jul 2026), reflecting broadening professional reach. First evidence of a sustained senior-authored publication series would mark a meaningful inflection in her scientific profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:59.147804+00', 'Senior-authored output emerging in Aug 2021–Jul 2026 signals a clear shift toward independent scientific leadership.', 'Engage now around her emerging senior authorship to build an early relationship before her network expands further.', 'early', '{"Citation volume declined by 476 across the two windows, suggesting limited downstream uptake of recent work so far."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1f9f5638-26ec-49b7-9ce6-53097b8eb947', '9a703b64-68f9-4faa-9b03-7858cbfdf0c2', 'nsclc', 'Zhihuang Hu is an Emerging Leader in NSCLC based at Shanghai Medical College of Fudan University, with 14 years of career experience and a Rising Star composite percentile of 94.5 (global rank 92). Publication output nearly tripled, from 6 papers (2016–2020) to 17 papers (2021–2025), accompanied by a citation volume growth of +34. The strongest signal is network momentum, which sits at the 97th percentile globally. Collaborator count expanded from 34 to 95 across the two periods, nearly a threefold increase in active scientific connections. A transition into consistent senior authorship would represent the next meaningful milestone to monitor in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:02:28.370983+00', 'Collaborator network expanded nearly threefold, from 34 to 95, placing network momentum at the 97th percentile.', 'Engage now around the expanding collaborator network; monitor closely for first appearance of senior authorship as a trigger for deeper partnership.', 'moderate', '{"Senior-author share remains at zero across both periods, indicating Hu has not yet assumed independent scientific leadership on publications."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('1f9ffce4-a6e7-4fdb-ae49-7721ebc1bf78', 'b1aedbba-c7ad-4178-84eb-22450b0924b2', 'nsclc', 'Diansheng Zhong is an Emerging Leader in NSCLC based at Tianjin Medical University General Hospital, with 15 years of career experience and a Rising Star composite percentile of 94.0 (global rank 99). Publication output grew from 22 papers (2016–2020) to 37 (2021–2025), while citation volume increased by 596, reflecting sustained scientific productivity. The strongest signal is network expansion. Collaborator count grew more than fourfold, from 74 to 306 individuals across the two periods, driving a network visibility percentile of 96. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:47:19.345228+00', 'Collaborator network expanded fourfold to 306, driving a 96th-percentile network visibility score.', 'Monitor for return to senior authorship; initiate relationship-building now given high network visibility and broad collaborator reach.', 'moderate', '{"Senior-author share has declined to zero in 2021–2025 despite a +3 senior-author publication delta; independent leadership is not yet established."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('2100401f-24a2-4f43-a3ea-80fef816d7f8', '955e5d8c-d1ba-4c7c-8004-d92499cfb5c7', 'nsclc', 'Alessandro Di Federico is an established NSCLC researcher based at Azienda USL di Bologna, Italy, with approximately 12 years of active scientific contribution and a career publication record of 757 papers. His recent productivity places him at the 93rd percentile within his established peer cohort, indicating a sharp upward trajectory in output over the last five years that outpaces the majority of recognized experts in this therapeutic area. While his first/last authorship density and clinical trial leadership metrics are more modest relative to peers, his overall cohort score of 88.0 reflects sustained and recognized influence within the NSCLC scientific community.', 'v1.0', 'claude-sonnet-4-6', '2026-06-04 11:30:07.057845+00', 'Di Federico''s accelerating publication velocity in a rapidly evolving NSCLC landscape — marked by expanding biomarker-driven treatment stratification and emerging resistance mechanisms — positions him as an increasingly relevant voice in current scientific discourse.', 'Given his high-volume, broad publication profile, Di Federico is well-suited for scientific dialogue around evidence synthesis, treatment sequencing rationale, and the interpretation of emerging clinical data in NSCLC subpopulations. His perspective on how evolving trial data should inform real-world practice and patient selection frameworks would be particularly valuable given the current complexity of the NSCLC therapeutic landscape.', 'Signal confidence is moderate-to-strong, anchored primarily by exceptional recent productivity within an established cohort, though lead authorship density and direct trial leadership data suggest his influence is more prominently expressed through collaborative and commentary-driven scholarship than independent trial design.', NULL::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('21c5dd3c-9f54-4d7f-80df-afe874aac742', '9b75e4f1-2a84-4eaa-b1f3-56f6ed0b2ec7', 'nsclc', 'Dr. Rachel E. Sanborn is a rising Lung Cancer investigator at Providence Portland Medical Center whose research profile has expanded markedly across two consecutive five-year windows. The strongest signal is publication output. She authored 8 papers from Aug 2016 – Jul 2021, rising to 25 papers from Aug 2021 – Jul 2026, representing more than a three-fold increase in volume alongside a publication velocity delta of +2. Her collaborator network grew from 82 (Aug 2016 – Jul 2021) to 350 (Aug 2021 – Jul 2026), and citation volume increased by 509 across the same comparison. Senior-authored output appears in the Aug 2021 – Jul 2026 window but was absent in the Aug 2016 – Jul 2021 window. A sustained pattern of senior-authored publications in a high-impact Lung Cancer journal would represent the next meaningful milestone in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:32.847102+00', 'Publication output more than tripled, from 8 to 25 papers, between the two five-year windows.', 'Engage now around her expanding collaborator network to establish presence ahead of anticipated senior-author consolidation.', 'moderate', '{"Senior authorship emerged only recently; its durability and journal reach across Lung Cancer venues remain unconfirmed."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('22b9e3fc-ecea-4f41-ba28-af43068402bb', '2ed1b9cb-ffd2-447b-8c11-1dc7c1d36a93', 'nsclc', 'Melanie Janning is an Emerging Leader in NSCLC based at Universität Hamburg, 13 years into her career, ranked 208th globally with a Rising Star composite percentile of 87.4. Publication output grew from 7 papers (2016–2020) to 12 (2021–2025), while citation volume increased by 152, reflecting meaningful scientific momentum (percentile 88). The strongest signal is network expansion. Collaborator count grew nearly fourfold, from 62 to 236, driving a network momentum percentile of 78. Visibility remains the relatively weaker dimension, with scientific and network visibility at the 59th and 65th percentiles respectively. A transition into senior authorship, currently at zero share across both periods, would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:48:56.045481+00', 'Collaborator network expanded nearly fourfold, from 62 to 236, signaling rapid network momentum (78th percentile).', 'Early relationship-building now, with active monitoring for first senior-authored NSCLC publication as a key inflection point.', 'moderate', '{"Senior-author share remains zero across both periods, limiting independent scientific ownership and long-term influence assessment."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('22d273e0-bb35-4f41-aabe-86ed8f717c3e', 'ad0973c8-9335-4d85-95d7-82fd796befa5', 'nsclc', 'W. Victoria Lai is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, with nine years of career experience. Her publication output has remained substantial across both windows, with 10 papers from 2016–2020 and 9 from 2021–2025. The strongest signal is network expansion. Her collaborator count grew from 91 to 147 individuals across the same periods, reflecting meaningfully broader scientific engagement. Citation volume has grown by 29 over the recent window, indicating that her work is attracting increasing attention from the field. A transition into senior-authored output would represent the next meaningful milestone in her scientific development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:03.102226+00', 'Collaborator network expanded from 91 to 147 individuals alongside 29-unit citation volume growth.', 'Engage now around her expanding collaborator network and monitor closely for first senior-authored publication.', 'early', '{"No senior-authored output has been recorded to date, limiting evidence of independent scientific leadership."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('2467581a-62c5-47be-8ded-17ecfe7d5c64', 'a3fd3d00-aa98-4ff1-9b73-8bb79e9aa2ff', 'nsclc', 'Juliana Guarize is an Emerging Leader in NSCLC with 13 years of career experience at IRCCS. Her publication output has increased more than two-fold, from 5 papers (2016–2020) to 13 papers (2021–2025), accompanied by a citation volume growth of +29. The strongest signal is network momentum, which ranks at the 90th percentile globally. Her collaborator base expanded from 24 to 61 individuals across the two periods, representing more than a 2.5-fold increase in active scientific connections. First evidence of a transition into senior authorship would mark a meaningful inflection point for this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:13:34.872355+00', 'Collaborator network expanded 2.5-fold, from 24 to 61, placing her at the 90th network momentum percentile.', 'Engage around her expanding collaborator network now, and monitor closely for any first senior-authorship publications.', 'early', '{"Senior-author share remains at zero across both periods, limiting independent scientific ownership signals currently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('24896d20-2b6b-4bd6-ba68-ec740a57ceb9', 'c46422ad-cb7a-476c-8c54-a4bad0091d8a', 'nsclc', 'Scott M. Atay is an Emerging Leader in NSCLC at the University of Southern California, now in his tenth career year. The defining feature of the profile is publication growth. Output increased from 7 papers (2016–2020) to 13 papers (2021–2025), nearly doubling across windows. Collaborator count moved from 28 to 20 across the same periods, a contraction worth monitoring. Senior-authored output has not yet appeared in the record. A transition into first or senior authorship on an NSCLC-focused manuscript would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:53.915336+00', 'Publication output nearly doubled from 7 to 13 papers across consecutive five-year windows.', 'Early relationship-building now, with active monitoring for a first senior-authored NSCLC publication.', 'early', '{"No senior-authored output yet, and collaborator network contracted from 28 to 20, suggesting a narrowing scientific circle."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('25f40482-1b55-459f-816d-6c7bf7be4fd6', '500ef208-761b-4036-9851-a51869970792', 'nsclc', 'Terence T. Sio is an Emerging Leader in NSCLC based at Mayo Clinic in Florida, now 14 years into his career. His publication output held steady and grew modestly, from 7 papers (2016–2020) to 8 papers (2021–2025). The strongest signal is network expansion. His collaborator base grew from 33 to 95 individuals across the same two windows, nearly tripling in raw count. Authorship is moving toward senior positions, and citation volume declined by 26 over the period. A first senior-authored publication in a high-impact NSCLC venue would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:32.938416+00', 'Collaborator network nearly tripled, from 33 to 95, signaling rapid integration into the NSCLC research community.', 'Engage now around the expanding collaborator network and monitor closely for a first senior-authored NSCLC publication.', 'early', '{"Citation volume declined by 26 across periods, suggesting recent work has not yet accumulated broad field recognition."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('261cf43e-e487-461d-8b97-4b6fb28c2310', '8c684325-eac4-4015-ae61-058a37b3639e', 'nsclc', 'Filippo Gustavo Dall''Olio is an Emerging Leader in NSCLC based at Institut Gustave Roussy with 9 years of career experience. His publication output nearly doubled across periods, rising from 11 papers (2016–2020) to 20 papers (2021–2025), accompanied by citation volume growth of +22. The strongest signal is network expansion. His collaborator count grew from 73 to 204, a nearly three-fold increase that anchors his Network Visibility percentile at 84 and Network Momentum at the 71st percentile. Scientific Visibility sits at the 76th percentile, supporting a composite Rising Star rank of 367 globally at the 77.7th percentile. A transition into consistent senior authorship would represent the next meaningful milestone to monitor in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:09:22.646208+00', 'Collaborator network nearly tripled, from 73 to 204, driving an 84th-percentile Network Visibility score.', 'Monitor for first senior-authored publication as the trigger for deeper scientific engagement and relationship-building.', 'early', '{"Senior-author share remains at zero across both periods, indicating Dall''Olio has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('27e0164b-bacc-4ec5-a2fa-4987966d46ae', 'cb0ed3ba-db4c-443f-b573-4b768f06ca46', 'nsclc', 'Mohamed E. Abazeed is an Emerging Leader in NSCLC with 14 years of career experience at Northwestern University. Publication output held steady, moving from 5 papers (2016–2020) to 6 papers (2021–2025), while his collaborator network expanded meaningfully, from 32 to 45 individuals across the same windows. The strongest signal is network growth. That expansion of 13 net new collaborators suggests broadening scientific engagement even as per-paper output remains modest. A transition back into senior authorship on NSCLC-focused work would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:01.772469+00', 'Collaborator network grew from 32 to 45 individuals, signaling broadening scientific engagement in NSCLC.', 'Engage around the expanding collaborator network to establish early relationships before senior authorship re-emerges.', 'early', '{"Senior-author share is receding and citation volume declined by 297, raising questions about current independent scientific influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('286b1e67-f5e1-4e64-972c-466b12e8026a', '0d2e4e6d-0f32-4646-a6b8-ac7114b2407c', 'nsclc', 'Apar Pataer is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 15 years of career experience. Publication output grew from 9 papers (2016–2020) to 11 papers (2021–2025), while citation volume expanded by 576 citations across the same comparison, indicating that existing work is gaining meaningful downstream recognition. The strongest signal is citation growth. Those 576 additional citations reflect compounding scientific impact well beyond what the modest publication count increase alone would suggest. Collaborator reach expanded from 75 to 83 individuals across the two windows. First evidence of senior-authored output would mark a meaningful inflection in this profile''s development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:40.868054+00', 'Citation volume surged by 576 while collaborator network expanded from 75 to 83 peers.', 'Monitor for transition into senior authorship as the natural next milestone for relationship deepening.', 'early', '{"No senior-authored output has emerged yet, limiting evidence of independent scientific direction despite 15 career years."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('28f2520a-ec57-4cac-a02e-07c962290f92', '0b651899-941a-4483-8dc7-be864e758e8f', 'nsclc', 'Fernando Franco is an Emerging Leader in NSCLC based at Hospital Universitario Puerta de Hierro Majadahonda, with 9 years of career experience. Publication output grew from 8 to 12 papers across consecutive five-year periods, while citation volume increased by 128, reflecting steady scientific momentum at the 63rd percentile. The strongest signal is network momentum, which ranks at the 80th percentile. Collaborator count expanded from 38 to 98, a more than 2.5-fold increase in a single period. A transition into senior authorship on any forthcoming NSCLC publication would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:10:45.393061+00', 'Collaborator network expanded from 38 to 98, a 2.5-fold increase, driving 80th-percentile network momentum.', 'Engage around the expanding collaborator network and monitor closely for any first senior-authorship publication in NSCLC.', 'early', '{"Senior-author share remains at zero across both periods, limiting independent scientific identity and influence attribution."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('298d8b85-ad8b-4bba-bd1d-634d3c051143', '15fb63a2-f3b2-40f9-835a-8ab206722d52', 'nsclc', 'Hampartsoum B. Barsoumian is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 10 years of career activity. Publication output grew from 12 papers (2016–2020) to 15 papers (2021–2025), while the collaborator network expanded from 55 to 59 individuals across the same windows. The strongest signal is the collaborator base. That network of 59 active collaborators in the most recent window reflects a broadening scientific footprint that may precede more visible output. A transition into senior-authored publications would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:36.479294+00', 'Collaborator network grew from 55 to 59 alongside a modest publication increase from 12 to 15 papers.', 'Early relationship-building now, monitoring closely for first senior-authored publication as a key inflection point.', 'early', '{"No senior-authored output has been recorded yet, and citation volume declined by 765, suggesting limited downstream impact to date."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('2a88fd06-52ff-4f68-916e-0a86ba91a16e', '70e5a3c6-6179-4611-b043-a73dc1971e1d', 'nsclc', 'Yueyin Pan is an Emerging Leader in NSCLC based at Anhui Provincial Hospital, with 15 years of career experience and a Rising Star composite percentile of 98.8, ranking 21st globally. Publication output increased nine-fold, from 5 papers (2016–2020) to 45 papers (2021–2025), accompanied by citation volume growth of 2,278. The strongest signal is network expansion. Collaborator count grew from 45 to 562 between the two periods, a greater than twelve-fold increase, placing network momentum at the 93rd percentile and network visibility at the 99th percentile globally. A transition into a named senior-author role on a high-impact NSCLC publication would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:56:27.838745+00', 'Collaborator network expanded twelve-fold to 562, driving a 99th-percentile network visibility score.', 'Engage now around the expanding collaborator network; monitor closely for first senior-authored NSCLC publication as a priority trigger.', 'high', '{"Senior-author share remains 0 across both periods, suggesting output may reflect collaborative rather than independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('2aff21d5-3b05-4b94-b325-882862da932d', 'd8977545-64dd-488b-ab06-6064eff33630', 'nsclc', 'Benjamin J. Drapkin is a rising Lung Cancer investigator at Massachusetts General Hospital whose nine-year career shows a maturing research profile worth monitoring. The strongest signal is authorship positioning. Between Aug 2021 – Jul 2026 he held a higher senior-author share than in Aug 2016 – Jul 2021, indicating a shift from contributor to independent investigator. His collaborator network remained substantive, moving from 51 colleagues (Aug 2016 – Jul 2021) to 44 (Aug 2021 – Jul 2026), suggesting a more focused rather than contracting set of partnerships. First evidence of a senior-authored landmark publication in Lung Cancer would mark a meaningful inflection in his independent scientific voice.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:01.494276+00', 'Senior-author share is rising between the two five-year windows, signaling emerging independent investigator status.', 'Early relationship-building focused on his senior-authored work to establish presence before independent output accelerates.', 'early', '{"Publication volume declined from 8 (Aug 2016 – Jul 2021) to 5 (Aug 2021 – Jul 2026), and citation volume also contracted, tempering the authorship signal."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('2cf147e7-8bd6-45eb-956b-e2db23198021', '876b58e7-0dc0-4c4e-b13d-29d43d3a3255', 'nsclc', 'Xiaoli Zhu is a Balanced Rising Star in NSCLC at Zhongda Hospital Southeast University, ranked 44th globally with a composite Rising Star percentile of 97.4. Publication output grew from 6 papers (2016–2020) to 10 (2021–2025), while citation volume increased by 208, reflecting deepening scientific impact. The strongest signal is network momentum, which sits at the 93rd percentile. Collaborator count expanded more than threefold, from 50 to 178 individuals across the two periods. A transition into consistent senior authorship would represent the next meaningful milestone to monitor in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:48:19.917035+00', 'Collaborator network expanded 3.6x, from 50 to 178, driving a 93rd-percentile network momentum score.', 'Engage now around the expanding collaborator network; monitor closely for first senior-authored NSCLC publication as a priority trigger.', 'high', '{"Senior-author share remains at zero across both periods, raising questions about independent scientific ownership of published work."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('2d4b51a2-8a52-4f6d-8181-e0bc4a120889', '6c46ed04-68f7-4f45-8641-8667513c1abb', 'nsclc', 'Michael Farris is an Emerging Leader in NSCLC at Wake Forest University, now 11 years into his career. The strongest signal is publication output. Output doubled from 7 papers (2016–2020) to 14 papers (2021–2025), while his collaborator network expanded from 26 to 43 colleagues across the same windows. Authorship is moving toward senior positions, a structural shift that often precedes increased influence over research direction. A first independently senior-authored NSCLC publication would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:22.594711+00', 'Publication output doubled to 14 papers (2021–2025) alongside a collaborator network that grew from 26 to 43.', 'Engage now around the collaborator network expansion and monitor for a first senior-authored NSCLC publication.', 'early', '{"Citation volume declined by 193 across windows, suggesting output growth has not yet translated into broad field uptake."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('2dc576e9-5dd2-4cbf-93ff-68f44acb516a', '2ea6246a-692f-4427-a532-f6cf0e41660c', 'nsclc', 'Kathryn F. Mileham is a rising Lung Cancer investigator at Levine Cancer Institute whose research output has grown more than three-fold, from 5 publications (Aug 2016–Jul 2021) to 16 publications (Aug 2021–Jul 2026). The strongest signal is her network expansion. Collaborator count more than doubled, from 37 (Aug 2016–Jul 2021) to 84 (Aug 2021–Jul 2026), indicating broadening cross-institutional engagement. Senior-author share held steady across both windows, reflecting consistent independent contribution rather than a shift toward junior roles. A transition into multi-site trial leadership would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:27.972521+00', 'Publication output more than tripled and collaborator count more than doubled across the two most recent five-year windows.', 'Engage around her expanding collaborator network to explore co-investigator or advisory opportunities at Levine Cancer Institute.', 'early', '{"Citation volume declined by 318 across the two windows, tempering the impact signal despite strong output and network growth."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('30d74531-0e5e-4676-a290-db9c7c65a1f7', 'e8a685ff-898b-4170-8e3e-ab411b114933', 'nsclc', 'Udayan Guha is an Emerging Leader in NSCLC research at the Center for Cancer Research, now 14 years into an active scientific career. The strongest signal is network expansion. His collaborator base grew from 68 individuals in 2016–2020 to 153 in 2021–2025, more than doubling in raw count. Publication output also increased, from 11 papers in 2016–2020 to 13 in 2021–2025, accompanied by a citation volume growth of 46 additional citations. Notably, his senior-author share has been receding in the current window. A transition back toward senior authorship on NSCLC-focused work would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:50.577783+00', 'Collaborator network more than doubled, from 68 to 153, signaling rapidly expanding scientific reach.', 'Engage now around his expanding collaborator network to establish early visibility before senior authorship re-emerges.', 'early', '{"Senior-author share is receding in the current window, limiting evidence of independent scientific agenda-setting."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('31392742-9a63-4373-914d-4a17e5db814c', 'ea165b22-86c3-4d77-ac3d-ed5ad43cb459', 'nsclc', 'Nisha Mohindra is an Emerging Leader in NSCLC with 12 years of career experience at Northwestern University. She contributed 14 publications from 2016 to 2020 and 6 from 2021 to 2025, with her authorship role moving toward senior positions over that span. Her collaborator network contracted from 87 individuals in 2016–2020 to 68 in 2021–2025, suggesting a deliberate narrowing toward closer, more focused research relationships. The strongest signal is citation volume, which declined by 512 over the recent window, warranting close attention as her output mix shifts. A first senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:42.707937+00', 'Authorship moving toward senior roles signals a pivotal shift in scientific independence and influence.', 'Monitor for first senior-authored NSCLC publication as the primary trigger for deeper MSL engagement.', 'early', '{"Citation volume declined by 512 in the recent window, and no confirmed senior-authored output yet anchors her emerging independent voice."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('32bc6f53-360f-4fcf-b94b-b6892645986c', '3cd5123a-8345-49b2-bf35-8cb528623f7c', 'nsclc', 'Francesco Agustoni is an Emerging Leader in NSCLC based at the University of Pavia, with 15 years of career experience and a Rising Star composite percentile of 83 (rank 280 globally). Publication output increased more than four-fold, from 7 papers (2016–2020) to 29 papers (2021–2025), while his collaborator network expanded more than three-fold, from 96 to 328 unique collaborators. Network Visibility is the strongest component of this profile, reaching the 90th percentile, reflecting broad cross-institutional reach. Senior-author share remains at zero across both periods, indicating Agustoni is currently contributing as a collaborative mid-network node rather than an independent research driver. A first appearance as senior author on an NSCLC-focused publication would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:11:30.136953+00', 'Collaborator network surged from 96 to 328, placing network visibility at the 90th percentile.', 'Engage now around his expanding collaborator network and monitor closely for first senior-authorship transition.', 'early', '{"Senior-author share is 0% across both periods; independent scientific leadership is not yet evidenced in publication data."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('330ea906-f283-4656-8818-0c883666f896', 'f378052e-99d9-4f65-be25-56647f77519e', 'nsclc', 'Marta Brambilla is an Emerging Leader in NSCLC based at Fondazione IRCCS Istituto Nazionale dei Tumori, with 12 years of career experience. Publication output nearly tripled, from 11 papers (2016–2020) to 31 papers (2021–2025), while her collaborator network expanded more than four-fold, from 54 to 236 co-authors across the same periods. The strongest signal is network growth. That collaborator count rising from 54 to 236 places her at the 64th percentile for Network Momentum and underpins a composite Rising Star percentile of 79.5 (global rank 338). A transition into a named senior-author role on a multi-institutional NSCLC publication would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:00:09.814633+00', 'Collaborator network expanded more than four-fold, from 54 to 236, signaling rapid integration into NSCLC research circles.', 'Monitor for first senior-author publication as a trigger for deeper scientific engagement and relationship-building.', 'early', '{"Senior-author share remains at zero across both periods, indicating Brambilla has not yet assumed independent publication leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('3417b174-b0cd-4f7b-b99c-2eff999d0a99', 'dd94b378-cd85-4121-b9c4-c96aa8fa5911', 'nsclc', 'Jiajun Deng is a Balanced Rising Star in NSCLC at Tongji University, now in his eighth career year and ranked 43rd globally with a composite percentile of 97.4. Publication output increased five-fold, from 6 to 30 papers across the two periods, accompanied by a citation volume growth of +423. The strongest signal is network momentum, which sits at the 96th percentile. Collaborator count expanded more than three-fold, from 28 to 90 individuals. First evidence of a transition into senior authorship, where senior-author share currently remains at zero, would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:53:33.166414+00', 'Collaborator network expanded more than three-fold, from 28 to 90, driving a 96th-percentile network momentum score.', 'Engage now around his expanding 90-person collaborator network; monitor closely for first senior-author publication as a relationship trigger.', 'high', '{"Senior-author share remains at zero across both periods, suggesting Deng has not yet independently led published work."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('34540ede-6e50-4a16-baae-0eaa76d2e9a0', 'd3e6b3ed-ee4e-4cd0-97a8-45b11a748f41', 'nsclc', 'Fabrizio Tabbò is an Emerging Leader in NSCLC based at the University of Turin, with 14 years of career experience and a Rising Star composite percentile of 71.9 (global rank 462). Publication output nearly doubled, from 15 papers (2016–2020) to 27 (2021–2025), accompanied by a citation volume growth of +183. The strongest signal is network expansion. His collaborator count grew more than threefold, from 131 to 401 individuals across the two periods, driving a Network Visibility percentile of 91. Senior-author share remains at zero across both periods, leaving his independent scientific voice unestablished. A first appearance as senior author on an NSCLC-focused publication would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:06:38.645311+00', 'Collaborator network tripled to 401, pushing Network Visibility to the 91st percentile globally.', 'Monitor for transition into senior authorship as a trigger for deeper scientific engagement and relationship-building.', 'early', '{"Senior-author share is zero across both periods, indicating no independent scientific leadership established yet."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('35697a25-b97f-4107-8236-12d1ac83b4b1', 'ef965d6e-b025-4747-bba1-e4a62f52bf7f', 'nsclc', 'Nicholas R. Faris is an Emerging Leader in NSCLC based at Baptist Cancer Center, with 12 years of career experience. His publication output held steady, moving from 10 papers (2016–2020) to 11 papers (2021–2025), while his collaborator network expanded from 25 to 29 individuals across the same windows. The defining feature of the profile is citation volume. That figure declined by 420 citations in the more recent window, a contraction that tempers the otherwise stable output picture. A transition into senior-authored publications would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:28.041985+00', 'Collaborator network grew from 25 to 29, signaling broadening scientific connections across recent years.', 'Early relationship-building now, with close monitoring for first senior-authored publication as a key inflection point.', 'early', '{"No senior-authored output yet, and a citation volume decline of 420 reduces current evidence of field-wide scientific impact."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('35ce092d-5b50-4bd6-810f-b5463142c68d', 'aa65d05f-b517-45cd-86ec-909ba7b44604', 'nsclc', 'Yuchen Han is an Emerging Leader in NSCLC at Shanghai Jiao Tong University, ranked 63rd globally with a Rising Star composite percentile of 96.2. The strongest signal is scientific momentum, which sits at the 98th percentile. Publication output doubled from 10 papers (2016–2020) to 20 papers (2021–2025), while citation volume grew by 277 and the collaborator network more than doubled from 46 to 106 active collaborators. Scientific visibility and network visibility are both at the 73rd percentile, indicating room for broader field recognition relative to current output. A transition into senior authorship, where the current share remains at zero, would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:01:00.723307+00', 'Citation volume surged 277 points and collaborators more than doubled to 106 in 2021–2025.', 'Monitor closely for first senior-authored publication as the trigger for initiating direct scientific dialogue.', 'high', '{"Senior-author share remains zero across both periods, raising questions about independent scientific leadership and decision-making authority."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('3601dd78-6e21-4afe-836a-61f76eeaabf7', '25159dcd-3de5-49a5-bdaa-bf8c4c137218', 'nsclc', 'Tingting Wang is a Balanced Rising Star in NSCLC at Tongji University, ranked 32nd globally with a composite Rising Star percentile of 98.1. Publication output more than tripled, from 6 papers (2016–2020) to 19 papers (2021–2025), while citation volume grew by 497 over the same period. The strongest signal is network momentum, which sits at the 98th percentile. Collaborator count expanded fourfold, from 29 to 117 individuals across the two periods. First evidence of a transition into senior authorship, where senior-author share currently remains at 0, would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:53:41.548287+00', 'Collaborator network expanded fourfold, from 29 to 117, placing network momentum at the 98th percentile.', 'Engage now around the expanding 117-person collaborator network; monitor closely for first senior-author publication as a key milestone.', 'high', '{"Senior-author share remains at 0 across both periods, suggesting Wang may still be operating in a dependent collaborative role."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('36423998-bdec-4d0a-8d85-6964f439af11', 'b2ab223d-a4c8-4873-8aef-bea1e3d58de6', 'nsclc', 'Alex Martínez-Martí is an Emerging Leader in NSCLC based at Vall d''Hebron Hospital Universitari with 15 years of career experience. Publication output more than doubled, from 14 papers (2016–2020) to 32 papers (2021–2025), accompanied by citation volume growth of +992, reflecting sustained and accelerating scientific productivity. The strongest signal is network visibility, which sits at the 90th percentile globally. Collaborator count grew from 141 to 303 across the two periods, more than doubling the active network. A transition into senior authorship on any of these collaborative outputs would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:42:38.347404+00', 'Network visibility at the 90th percentile, with collaborators doubling from 141 to 303.', 'Engage now around the expanding collaborator network; monitor closely for first senior-authored publication as a relationship inflection point.', 'early', '{"Senior-author share remains at zero across both periods, limiting independent scientific ownership of the growing publication output."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('3699aaae-9ea1-48cc-b654-cc92797c487b', '6ca0bb5c-21b7-42f4-8b3d-75a32b73305f', 'nsclc', 'Carlos Aguado is an Emerging Leader in NSCLC based at Hospital Clínico San Carlos, with 12 years of career experience and a Rising Star composite percentile of 89.5 (global rank 173). The strongest signal is scientific momentum, which sits at the 91st percentile. Publication output more than doubled, from 5 papers (2016–2020) to 12 (2021–2025), while citation volume grew by 434 over the same period. Network breadth expanded substantially, with collaborators increasing from 70 to 127. A transition into senior authorship, currently at zero share across both periods, would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:50:55.30481+00', 'Citation volume surged by 434 and collaborators nearly doubled to 127 in 2021–2025.', 'Monitor for first senior-authored publication as the primary trigger for deeper scientific engagement.', 'moderate', '{"Senior-author share remains zero across both periods, limiting independent scientific identity despite strong output growth."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('372e39db-42ca-43bd-9677-6f8b51ece36c', '44a9472a-5aa4-4b7e-bfbf-b5dd0755836e', 'nsclc', 'Àlvaro Quintanal-Villalonga is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center whose research output has nearly doubled, growing from 11 publications (Aug 2016–Jul 2021) to 21 publications (Aug 2021–Jul 2026). The strongest signal is network expansion. His active collaborator base grew more than threefold, from 43 collaborators (Aug 2016–Jul 2021) to 134 collaborators (Aug 2021–Jul 2026), indicating deepening cross-institutional engagement. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), marking a meaningful shift in research independence. A sustained pattern of senior-authored publications in high-impact Lung Cancer journals would represent the next observable milestone in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:34.318089+00', 'Collaborator count tripled to 134 (Aug 2021–Jul 2026), signaling rapid network expansion now.', 'Engage now around his expanding collaborator network to establish early relationships before visibility broadens further.', 'early', '{"Citation volume declined by 265 between windows, warranting attention to whether recent publications are gaining traction."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('3740ee0d-0799-4132-826f-6d6f68b8e36f', 'fad4f76e-3bde-4e25-9605-3e29050c24d4', 'nsclc', 'Nicholas G. Zaorsky is an Emerging Leader in NSCLC with 14 years of career experience at Pennsylvania State University. He has maintained a consistent publication presence, contributing 6 papers from 2016–2020 and 5 papers from 2021–2025, while his collaborator network has remained stable at 28 and 24 co-authors across the same respective windows. The defining feature of the profile is authorship positioning. He is moving toward senior authorship, a structural shift that signals growing scientific ownership of research questions. First evidence of a sustained senior-authored NSCLC publication series would mark a meaningful inflection in his independent scientific voice.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:57.823578+00', 'A shift toward senior authorship signals growing independent scientific ownership across a stable publication base.', 'Initiate early relationship-building now, ahead of anticipated senior-authored output in NSCLC.', 'early', '{"Citation volume declined by 163 across windows, and publication output held flat, suggesting limited recent field-wide uptake."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('37dfcdeb-8c39-42a5-9437-e045cf8a8341', '23cefe93-fad3-4093-a16a-8248dfe2a4d5', 'nsclc', 'Pedro De Marchi is a Balanced Rising Star in NSCLC based at Hospital de Câncer de Barretos, ranking 13th globally with a composite percentile of 99.3 across a nine-year career. Publication output increased nearly four-fold, from 6 to 22 papers across consecutive five-year periods, accompanied by citation volume growth of 1,735. The strongest signal is network momentum, which sits at the 94th percentile. His collaborator base expanded from 32 to 157 individuals, a nearly five-fold increase in a single period. First evidence of a transition into senior authorship, given a current senior-author share of zero, would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:59:54.822841+00', 'Collaborator network expanded nearly five-fold, from 32 to 157, driving 94th-percentile network momentum.', 'Engage now around his expanding collaborator network and monitor closely for first senior-authorship transition.', 'high', '{"Senior-author share remains zero across both periods, indicating De Marchi has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('382ed22e-0e81-4b61-aa3b-95a872059962', '040f355f-cd2e-428d-a6ca-5c4c2f92002b', 'nsclc', 'Joshua Bauml is an Emerging Leader in NSCLC at the University of Pennsylvania, now 13 years into his career. Publication output grew from 18 papers (2016–2020) to 26 papers (2021–2025), reflecting steady and sustained scientific contribution. The strongest signal is network expansion. His collaborator count grew from 91 (2016–2020) to 282 (2021–2025), more than tripling in raw count across the two windows. Citation volume has grown by 6 over the same period, and authorship has not yet extended into senior-authored output. A transition into senior authorship would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:28.230228+00', 'Collaborator network more than tripled, from 91 to 282, signaling rapidly broadening scientific reach.', 'Monitor for first senior-authored publication as a trigger for deeper MSL relationship-building.', 'early', '{"No senior-authored output yet; influence within collaborative networks remains difficult to assess without that anchor."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('39fc9196-7552-4cbb-93e2-22c78a8ab47d', 'c34ece46-2abe-475c-b882-97121a3926ce', 'nsclc', 'Jonathan Benzaquen is an Emerging Leader in NSCLC, affiliated with Centre National de la Recherche Scientifique, with 9 years of career experience and a Rising Star composite percentile of 77.7 (global rank 368). His publication output nearly doubled from 11 papers (2016–2020) to 20 papers (2021–2025), driving a Scientific Momentum percentile of 81. The strongest signal is network expansion. His collaborator count grew from 59 to 93 across the two periods, placing Network Momentum at the 64th percentile. A transition into a named senior-author role on an NSCLC-focused publication would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:46:55.19003+00', 'Publication output nearly doubled to 20 papers (2021–2025), pushing Scientific Momentum to the 81st percentile.', 'Prioritize early relationship-building now, monitoring closely for first senior-authored NSCLC publication as an engagement trigger.', 'early', '{"Senior-author share remains at 0 across both periods, and citation volume declined by 29, limiting independent visibility."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('3a3717b0-c276-4a00-98a3-5d426a06c0d7', 'e6fe8fac-fd22-416d-8498-97351982ce75', 'nsclc', 'Débora S. Bruno is a rising Lung Cancer investigator at University Hospitals Seidman Cancer Center whose research output has grown more than two-fold, from 5 publications (Aug 2016–Jul 2021) to 13 publications (Aug 2021–Jul 2026). The strongest signal is citation volume growth. That growth reached +1,679 citations comparing the same two windows, indicating that her recent work is drawing substantially broader scientific attention. Her collaborator network expanded from 43 to 99 investigators across those periods, reflecting a widening sphere of scientific engagement. Senior-author share was lower in the recent window (Aug 2021–Jul 2026) than in the earlier window (Aug 2016–Jul 2021). A transition into a higher senior-author share in forthcoming publications would represent the next meaningful milestone in her independent research profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:10.001637+00', 'Citation volume surged by 1,679 comparing Aug 2016–Jul 2021 to Aug 2021–Jul 2026.', 'Monitor for transition into senior authorship as the natural trigger for deeper scientific engagement.', 'early', '{"Senior-author share declined in the recent window, suggesting independent research leadership is still developing."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('3a5a3506-12bc-4a9b-860e-8fe710091eba', '88230656-07b0-422a-a89e-bb4907c375ff', 'nsclc', 'Farastuk Bozorgmehr is an Emerging Leader in NSCLC based at Heidelberg University, with 10 years of career experience and a Rising Star composite percentile of 74.6 (global rank 419). Publication output grew from 18 papers (2016–2020) to 23 papers (2021–2025), while the collaborator network expanded from 88 to 178 co-authors, a doubling in network breadth that anchors a Network Visibility percentile of 78. Scientific Visibility stands at the 75th percentile, reflecting meaningful field presence. Senior-author share remains at zero across both periods, making the transition into independent authorship the next milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:11:43.593799+00', 'Collaborator network doubled to 178, driving Network Visibility to the 78th percentile.', 'Monitor for first senior-authored publication as the trigger for deeper scientific engagement.', 'early', '{"Senior-author share is 0 across both periods; citation volume declined by 245, raising questions about publication impact."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('3c9db795-41bc-46ff-93b4-cb91a8c709c6', 'd3a2253b-768e-4ac7-87ee-45135291064d', 'nsclc', 'Anwen Xiong is an Emerging Leader in NSCLC based at Tongji University, six years into an accelerating research career. Publication output increased nearly four-fold, from 6 papers (2016–2020) to 22 papers (2021–2025), while citation volume grew by 456, placing scientific momentum at the 89th percentile. The strongest signal is network expansion. Collaborator count grew nearly six-fold, from 40 to 235 individuals, driving network momentum to the 76th percentile and network visibility to the 87th percentile. Senior-author share remains at zero across both periods; a first senior-authored publication would mark a meaningful inflection in independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:02:13.208235+00', 'Collaborator network expanded nearly six-fold, from 40 to 235, signaling rapid integration into NSCLC research communities.', 'Monitor for first senior-authored publication as the trigger for deeper scientific engagement and relationship-building.', 'moderate', '{"Senior-author share is zero across all periods, indicating Xiong has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('3ebe625e-b652-4dcd-a761-a95cd2fc3966', 'b195fb55-4bd5-4ebd-a4f9-c8bce9761fd0', 'nsclc', 'Jeremy Fricke is an Emerging Leader in NSCLC based at City of Hope, six years into an active research career. The strongest signal is publication output. His output grew more than three-fold, from 6 papers in 2016–2020 to 20 papers in 2021–2025, accompanied by a citation volume increase of 89. His collaborator network expanded from 38 to 62 individuals across the same windows, reflecting broadening scientific engagement. Authorship to date has not yet included senior-authored work. A transition into senior or last authorship would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:15.403701+00', 'Publication output more than tripled to 20 papers in 2021–2025, with citation volume growing by 89.', 'Initiate early relationship-building now and monitor for first senior-authored NSCLC publication as a key inflection point.', 'early', '{"No senior-authored output yet; independent scientific leadership remains undemonstrated at this stage of his career."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4230225c-0b95-418a-b619-ae3b6cac26a1', 'bd43319c-2cdc-4f10-867e-60886fd4d835', 'nsclc', 'Dr. Sally C. M. Lau is a rising Lung Cancer investigator at NYU Langone Health whose research output has grown substantially across two consecutive five-year windows. Publication output increased more than twofold, from 8 papers (Aug 2016–Jul 2021) to 19 papers (Aug 2021–Jul 2026). The strongest signal is network expansion. Collaborator count grew more than fourfold, from 51 (Aug 2016–Jul 2021) to 232 (Aug 2021–Jul 2026), accompanied by a citation volume increase of 523 citations. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021). A sustained pattern of senior-authored publications in the next review cycle would represent the next meaningful milestone in her independent research profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:16.009109+00', 'Collaborator network expanded more than fourfold, from 51 to 232, in the most recent five-year window.', 'Engage now around her expanding collaborator network to establish early visibility before her senior-author profile solidifies.', 'moderate', '{"Senior authorship is newly emergent in the recent window; its durability and frequency across future output remain unconfirmed."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('436047d6-2703-4899-ac5d-92a6d90d1e1f', '0c5c4255-0e11-4299-a205-7084ea1aa121', 'nsclc', 'Pietro Bertoglio is a Scientific Accelerator in NSCLC at Azienda USL di Bologna, now 12 years into his career. The strongest signal is scientific momentum, which ranks at the 93rd percentile. Publication output more than doubled, from 7 papers (2016–2020) to 18 papers (2021–2025), alongside a citation volume growth of +70. Network breadth expanded from 99 to 170 collaborators, though network momentum sits at only the 46th percentile, indicating this remains a secondary driver. First evidence of a senior-author credit would mark a meaningful inflection in his independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:54:37.643605+00', 'Publication output rose from 7 to 18 papers and citation volume grew +70, both in the last five years.', 'Monitor for first senior-author publication as the trigger for deeper scientific engagement and relationship-building.', 'early', '{"Senior-author share remains at zero across both periods, suggesting Bertoglio has not yet established independent scientific ownership of publications."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4391a041-de8a-4b68-a239-c9c5f72b0a39', '4ebddb01-ff9c-4259-899c-82b7ebd2b9e4', 'nsclc', 'Annemarie F. Shepherd is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, now nine years into her career. The strongest signal is publication output. Her output grew nearly threefold, from 7 papers (2016–2020) to 19 papers (2021–2025), while citation volume expanded by 322 across the same shift. Her collaborator network grew more than sixfold, from 22 to 136 individuals, reflecting broad integration into the NSCLC research community. Senior-authored output has not yet appeared in her record. A transition into first senior-authored publication would represent the next meaningful milestone in her scientific development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:15.98808+00', 'Citation volume grew by 322 alongside a near-threefold increase in publications from 2021–2025.', 'Monitor for first senior-authored publication as a trigger for deeper scientific exchange and relationship-building.', 'early', '{"No senior-authored output has emerged yet, limiting evidence of independent scientific leadership at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4447394f-b2aa-4f71-bd15-42fd4583712f', '6643fb0e-75b9-40e1-8634-00e1a72efcdd', 'nsclc', 'Vito Longo is an Emerging Leader in NSCLC at Istituto Tumori Bari, ranked 442nd globally with a Rising Star composite percentile of 73.2. Publication output increased 2.5-fold, from 6 papers (2016–2020) to 15 (2021–2025), accompanied by a citation volume growth of +84. The strongest signal is network momentum, which sits at the 80th percentile. Collaborator count nearly doubled, expanding from 36 to 69 individuals across the two periods. First evidence of a transition into senior authorship, currently at zero across both periods, would mark a meaningful inflection in this profile''s independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:44:29.418569+00', 'Collaborator network nearly doubled from 36 to 69, driving an 80th-percentile network momentum score.', 'Engage now around growing collaborator network; monitor closely for first senior-author publication as a relationship-deepening trigger.', 'early', '{"Senior-author share remains zero across both periods, indicating Longo has not yet established independent publication leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('45956e94-bf2a-4bbc-8ceb-9a2f63ae8dcf', '7e4e09f8-1916-4336-946a-823b0960c610', 'nsclc', 'Dr. Yasir Y. Elamin is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center with 12 years of career experience. The defining feature of the profile is publication output. His output more than doubled, from 16 papers (Aug 2016–Jul 2021) to 34 papers (Aug 2021–Jul 2026), while his collaborator network expanded from 231 to 379 individuals across the same windows. Notably, senior-authored work appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), signaling a meaningful shift in scientific independence. A sustained pattern of senior-authored output on high-impact Lung Cancer questions would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:18.433827+00', 'Publication output more than doubled and senior authorship emerged in the Aug 2021–Jul 2026 window.', 'Engage now around emerging senior authorship and expanding collaborator network before external industry relationships solidify.', 'early', '{"Citation volume declined by 1,672 across the two windows, suggesting recent papers have not yet accumulated broad downstream engagement."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('463ed7b6-3352-4d78-8204-10c0fd15bfe0', '727d2911-4e36-487e-bcb7-00e0416d53d6', 'nsclc', 'Matthew S. Ning is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center whose research output has doubled, from 6 publications (Aug 2016–Jul 2021) to 12 publications (Aug 2021–Jul 2026). The strongest signal is network expansion. His collaborator base grew more than three-fold, from 31 collaborators (Aug 2016–Jul 2021) to 109 collaborators (Aug 2021–Jul 2026), indicating broad and accelerating scientific engagement. Citation volume increased by 335 over the same comparison, and senior-authored output appears in the recent window but not the early window. A sustained pattern of senior-authored publications across multiple journals would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:06.110384+00', 'Collaborator network more than tripled, from 31 to 109, between the two five-year windows.', 'Engage now around his expanding collaborator network to establish relationship ahead of anticipated senior authorship consolidation.', 'early', '{"Senior authorship is newly emergent in the recent window only; consistency across additional publications has not yet been established."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('46ab23fb-be5c-438a-ba8f-32bc5d64ca1d', '39ebbec8-6527-4f3c-bddf-50c01bd5571b', 'nsclc', 'Barzin Y. Nabet is a rising Lung Cancer investigator at Stanford University with nine years in the field. The strongest signal is publication output. Publications more than doubled, from 7 papers (Aug 2016–Jul 2021) to 16 papers (Aug 2021–Jul 2026), while his collaborator network expanded from 115 to 193 individuals across the same windows. Notably, senior-authored work appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), marking a meaningful shift in research independence. A sustained pattern of senior-authored output in high-impact Lung Cancer journals would represent the next observable milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:39.319043+00', 'Publication output more than doubled and senior authorship emerged in the Aug 2021–Jul 2026 window.', 'Engage now around the emerging senior authorship pattern before external industry relationships are established.', 'early', '{"Citation volume declined by 1,589 between windows, suggesting recent publications have not yet accumulated broad field uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('46cc51e3-8255-4b8b-bf08-3fe13df40edc', '41419308-74dd-4c74-9a79-5d52e7f5a9da', 'nsclc', 'Chen Chen is an Emerging Leader in NSCLC research based at City of Hope, now 13 years into an active research career. The strongest signal is network expansion. Collaborator count grew from 54 individuals in 2016–2020 to 119 in 2021–2025, more than doubling in raw terms. Publication output also increased, from 5 papers in 2016–2020 to 10 in 2021–2025, though citation volume has not yet grown in parallel. Senior-authored output has not yet appeared in the record. A transition into a first senior-authored publication would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:48.692492+00', 'Collaborator network more than doubled, from 54 to 119, signaling rapid expansion of research connections.', 'Early relationship-building now, with close monitoring for a first senior-authored publication as the key inflection point.', 'early', '{"No senior-authored output yet, and citation volume has declined, suggesting influence has not yet matched publication growth."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4898a880-8046-4c55-8e28-b5a6b328b2cd', 'f7e42510-c156-4b36-88b4-d65ef3fb200a', 'nsclc', 'Dania Nachira is a Network Accelerator in NSCLC based at Università Cattolica del Sacro Cuore, with 14 years of career experience and a Rising Star composite percentile of 81.2 (global rank 309). The strongest signal is network momentum, which sits at the 99th percentile. Her collaborator base expanded from 20 to 90 individuals across the two periods, a 4.5-fold increase in network reach. Publication output also grew from 5 to 18 papers, more than tripling, with citation volume up by 58. A transition into senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:10:59.538057+00', 'Collaborator network expanded 4.5-fold, from 20 to 90, placing network momentum at the 99th percentile.', 'Engage around her expanding collaborator network now, while monitoring for first appearance of senior authorship.', 'early', '{"Senior-author share remains at zero across both periods, limiting attribution of scientific independence to Nachira directly."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('489f519f-60f0-4045-860b-b930c6d81c17', 'e18f97fa-6992-4436-9fcd-d85915a83f9e', 'nsclc', 'Khinh Ranh Voong is a rising Lung Cancer investigator at Johns Hopkins University with 13 years of career experience. The strongest signal is network expansion. Collaborators grew from 38 (Aug 2016–Jul 2021) to 51 (Aug 2021–Jul 2026), a gain of 13 unique collaborators across the two windows. Publication output held relatively stable, at 10 papers (Aug 2016–Jul 2021) and 8 papers (Aug 2021–Jul 2026), while senior-author share rose between the two windows, indicating a shift toward independent scientific leadership. A transition into first- or last-authored publications in high-impact Lung Cancer journals would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:49.321924+00', 'Collaborator network expanded from 38 to 51 individuals across the two most recent five-year windows.', 'Engage around the expanding collaborator network to explore multi-site research partnerships and emerging investigator relationships.', 'early', '{"Citation volume declined by 849 between the two windows, suggesting recent work has not yet accumulated broad field uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('48ccc666-1564-441f-a107-565aa56251bb', 'd8d08005-2218-4bfa-ad71-fc3c0ee4c79b', 'nsclc', 'Tapan K. Maity is an Emerging Leader in NSCLC research based at the Center for Cancer Research, with 15 years of career experience. Publication output held steady at 6 papers in both the 2016–2020 and 2021–2025 windows, reflecting consistent engagement with the field. The defining feature of the profile is the contraction in collaborative network. Active collaborators declined from 41 in 2016–2020 to 21 in 2021–2025, suggesting a sharpening of research focus rather than broadening reach. Authorship has not yet moved into senior-authored output. A first senior-authored publication in NSCLC would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:50.247346+00', 'Sustained publication output across both windows signals continued active research presence in NSCLC.', 'Initiate early relationship-building now, monitoring closely for a first senior-authored NSCLC publication as the key inflection signal.', 'early', '{"No senior-authored output yet, and collaborator count has declined by 20, indicating a narrowing network that may limit broader field influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('491c88de-f084-4d91-9a75-18c8ae7ae4c4', '36a8e31f-ceb7-45f0-9058-cc5e3a3e2860', 'nsclc', 'Shankar Siva is a Balanced Rising Star in NSCLC at the University of Melbourne, now 15 years into his career. Publication output increased more than four-fold, from 7 to 31 papers across consecutive five-year periods, while citation volume grew by 283. The strongest signal is network momentum, which sits at the 94th percentile. His collaborator base expanded from 28 to 156 individuals, a greater than five-fold increase in a single period. This profile is characteristic of a Balanced Rising Star with reinforcing scientific and network signals; a transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:46:12.463944+00', 'Collaborator network expanded five-fold to 156, paired with four-fold publication growth since 2021.', 'Monitor for first senior-author publications as a trigger for deeper scientific exchange and collaborative discussion.', 'high', '{"Senior-author share remains at zero across both periods, meaning influence is currently exercised without formal last-author credit."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('49ba8b5b-0256-478d-acb0-18423b1d8045', 'c702db67-7bc0-492e-b6db-0a937b7a6861', 'nsclc', 'Hua Bao is an Emerging Leader in NSCLC whose most striking feature is publication growth. Output increased nearly threefold, from 13 papers (2016–2020) to 36 papers (2021–2025). The collaborator network expanded in parallel, growing from 140 to 265 individuals across the same windows, reflecting broadening scientific connectivity. Citation volume has declined by 278, and no senior-authored output has appeared yet, indicating the profile remains in an early formative phase. First evidence of senior or corresponding authorship on an NSCLC-focused manuscript would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:46.35114+00', 'Publication output nearly tripled, from 13 to 36 papers, alongside a collaborator network doubling to 265.', 'Begin early relationship-building now and monitor for a first senior-authorship appearance in NSCLC literature.', 'early', '{"No senior-authored output yet and a citation volume decline of 278 suggest limited independent scientific influence at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4a459034-a8a2-4d96-a2bf-63917e996868', 'e3f0fedd-5cff-4158-834c-7f8156c69492', 'nsclc', 'Daniel C. Christoph is a Scientific Accelerator in NSCLC based at Kliniken Essen-Mitte with 15 years of career experience, ranked 290th globally with a Rising Star composite percentile of 82.4. Publication output nearly doubled across periods, rising from 9 papers (2016–2020) to 16 papers (2021–2025), reflecting sustained scientific productivity. The strongest signal is scientific momentum, which sits at the 91st percentile. This is driven primarily by raw publication growth rather than citation volume, which declined by 20 over the same interval. A transition into a senior-author role would represent the next meaningful milestone for this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:11:15.091926+00', 'Scientific momentum reached the 91st percentile, anchored by publication growth from 9 to 16 papers.', 'Monitor for first senior-authored publication as a trigger for deeper scientific engagement and relationship-building.', 'early', '{"Senior-author share remains at 0 across both periods, and citation volume declined by 20, limiting independent scientific influence signals."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4a94251b-6c2b-4714-8884-fec58f7fa66e', '8317c658-469b-497f-91d2-b80e390e52aa', 'nsclc', 'Chantale Bernatchez is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center with 15 years of career experience. The strongest signal is authorship evolution. Between Aug 2021 – Jul 2026, senior-authored output appears in her record, a pattern absent in the Aug 2016 – Jul 2021 window, indicating a meaningful shift in scientific independence. Publication volume moved from 15 papers (Aug 2016 – Jul 2021) to 6 papers (Aug 2021 – Jul 2026), while her collaborator network narrowed from 188 to 58 over the same periods, suggesting deliberate focus. First evidence of a senior-authored publication in a high-impact Lung Cancer journal would mark a meaningful inflection in her independent research profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:20.37782+00', 'Senior-authored output emerging in Aug 2021 – Jul 2026 signals a shift toward independent scientific leadership.', 'Engage now around her emerging senior-authored work to establish early relationship before independent research profile solidifies.', 'early', '{"Citation volume declined by 2,541 and collaborator count dropped from 188 to 58, suggesting reduced broad network engagement recently."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4b635c89-5ad1-4e8e-8cef-c01469ce3eda', 'd637aa71-d71c-4f9f-8ec3-6fb663106fc8', 'nsclc', 'Ting Xu is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 15 years of career experience. Publication output has remained stable, with 18 papers from 2016–2020 and 17 papers from 2021–2025. The strongest signal is network expansion. Collaborator count grew from 95 in 2016–2020 to 134 in 2021–2025, an addition of 39 unique collaborators. Senior-authored output has not yet appeared in the record. A first senior-authored publication would mark a meaningful inflection in this profile''s scientific independence.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:48.723771+00', 'Collaborator network expanded from 95 to 134 individuals across the two observation windows.', 'Monitor for transition into senior authorship as the natural next milestone for relationship-building.', 'early', '{"No senior-authored output yet, and citation volume declined by 591, suggesting limited independent scientific visibility to date."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4bf602cf-a424-4e28-a903-465910b4d5ba', '6d3206ad-f8b8-4bb3-91b0-ca74aa0fb332', 'nsclc', 'Thomas Lycan is a rising Lung Cancer investigator at Wake Forest University whose research output has grown more than three-fold, from 5 publications (Aug 2016–Jul 2021) to 16 publications (Aug 2021–Jul 2026). The strongest signal is publication growth. That increase of 11 papers across windows, combined with a publication velocity delta of +2, indicates an accelerating pace of scientific contribution. His collaborator network has also expanded, from 35 colleagues (Aug 2016–Jul 2021) to 45 (Aug 2021–Jul 2026), reflecting broadening scientific engagement. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), marking a meaningful shift in research independence. First evidence of a sustained senior-authorship pattern across consecutive publications would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:09:01.045827+00', 'Publication output more than tripled, from 5 to 16 papers, across the two most recent five-year windows.', 'Engage now around emerging senior authorship and expanding collaborator network before external industry relationships solidify.', 'early', '{"Citation volume declined by 167 across the two windows, tempering the impact signal despite strong publication growth."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4c7f15b2-34a1-4d51-98f5-4ff8c0d09ed3', 'f7abde5b-22bf-45bf-9672-089ef7077ea8', 'nsclc', 'Raffaele Giusti is an Emerging Leader in NSCLC based at CTO Andrea Alesini, with 12 years of career experience and a Rising Star composite percentile of 71.5 (global rank 470). Publication output grew from 26 papers (2016–2020) to 37 (2021–2025), while his collaborator network expanded from 248 to 409 individuals across the same periods. The strongest signal is network visibility. It sits at the 95th percentile globally, indicating that Giusti''s work is reaching a broad and well-connected audience despite a scientific momentum percentile of 67. Senior-author share remains at zero across both periods, suggesting his influence is currently exercised through collaborative rather than independent output. First evidence of a senior-authored publication in NSCLC would mark a meaningful inflection in his independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:03:57.753747+00', 'Network visibility at the 95th percentile signals broad reach across 409 collaborators in 2021–2025.', 'Monitor for first senior-authored NSCLC publication as the trigger for deeper scientific engagement.', 'early', '{"Senior-author share is zero across both periods; all output reflects collaborative roles, not independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4c822888-48ea-4ff7-9fd1-39d025cca6d6', '2577d5b9-9d4b-4217-a5d1-4f9ac684baab', 'nsclc', 'Giuseppe Viscardi is an Emerging Leader in NSCLC based at Ospedale Monaldi with 10 years of career experience, ranked 219th globally with a Rising Star composite percentile of 86.7. Publication output nearly quadrupled, from 7 papers (2016–2020) to 27 papers (2021–2025), reflecting sustained and accelerating scientific productivity. His collaborator network expanded from 92 to 262 individuals across the same periods, driving a Network Visibility percentile of 88 and a Network Momentum percentile of 67. Scientific Visibility stands at the 84th percentile, reinforcing a profile with strong external recognition. A transition into senior authorship on NSCLC-focused publications would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:12:06.251645+00', 'Collaborator network grew from 92 to 262, anchoring a Network Visibility percentile of 88.', 'Engage around his expanding collaborator network of 262 to map institutional NSCLC influence and identify co-engagement opportunities.', 'moderate', '{"Senior-author share remains at 0 across both periods, and citation volume growth is negative at -252."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4cd095a4-45e6-424f-b761-fb93f4d348ac', '09215e4d-c5d5-465e-b72b-15170102e76b', 'nsclc', 'Seigo Katakura is an emerging clinical researcher in non-small cell lung cancer based at Kanagawa Prefectural Hospital Organization, with approximately 7 years of publication activity and a career output of 66 publications that places his velocity at the 74th percentile across the full NSCLC research population. His citation trajectory ranks at the 78th percentile within the therapeutic area, indicating that his work is gaining meaningful uptake and reference by peers at a rate that outpaces the majority of NSCLC researchers at comparable or more advanced career stages. Clinical trial activity at the 75th percentile further distinguishes him as a hands-on investigator rather than a purely academic voice, suggesting direct patient-care relevance and protocol-level experience in NSCLC.', 'v1.0', 'claude-sonnet-4-6', '2026-06-04 04:47:26.281391+00', 'The convergence of above-70th-percentile rankings across publication velocity, citation growth, and trial activity simultaneously — within a 7-year career window — signals an inflection point where early engagement by an MSL is likely to precede broader recognition of Katakura as a key opinion leader in the NSCLC space.', 'Given his active trial participation and publication momentum in NSCLC, a productive MSL conversation could center on evolving biomarker-driven patient selection strategies and the practical challenges of implementing molecularly targeted approaches in a community or regional hospital setting. His institutional context at a prefectural hospital organization also makes him a valuable perspective on real-world treatment sequencing decisions and access considerations that differ from large academic centers.', 'Signal strength is moderately strong and internally consistent — three independent metrics (publication velocity, citation trajectory, and trial activity) all align above the 74th percentile within a competitive therapeutic area, providing convergent evidence of genuine and accelerating scientific influence.', NULL::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4d289a3c-88c4-439c-8354-fd793ccade5d', 'dbf710d6-241f-4280-b253-66a3284c1904', 'nsclc', 'Michele Simbolo is an Emerging Leader in NSCLC based at the University of Verona, with 13 years of career experience and a Rising Star composite percentile of 75.6 (global rank 402). Publication output more than doubled, from 5 papers (2016–2020) to 12 (2021–2025), while the collaborator network nearly doubled from 52 to 96 individuals across the same periods. The strongest signal is network momentum, which sits at the 79th percentile. Collaborator count grew from 52 to 96, reflecting a broadening scientific community footprint that outpaces publication volume growth. First evidence of a senior-authorship credit would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:02:42.46795+00', 'Collaborator network nearly doubled to 96 peers (2021–2025), driving a 79th-percentile network momentum score.', 'Engage around the expanding 96-person collaborator network to build early relationships ahead of potential senior-authorship transition.', 'early', '{"Senior-author share remains at 0 across both periods, and citation volume declined by 369, limiting visibility impact."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4d38fe0a-7b2e-42a3-bcaa-097cd87de56e', '8fc6d649-4a7f-4bcf-9c0d-fc0a77c1561e', 'nsclc', 'Matthew P. Deek is a rising Lung Cancer investigator at Rutgers, The State University of New Jersey, with 11 years in the field. The strongest signal is network expansion. His active collaborator count grew from 22 (Aug 2016 – Jul 2021) to 31 (Aug 2021 – Jul 2026), a gain of nine collaborators, suggesting broadening cross-institutional engagement. Notably, senior-authored output appears in the Aug 2021 – Jul 2026 window but was absent in the Aug 2016 – Jul 2021 window, marking a meaningful shift in research independence. A first senior-authored Lung Cancer publication in a high-impact journal would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:54.470277+00', 'Senior-authored output emerged in the recent window after being absent in the prior window.', 'Engage now around his expanding collaborator network and emerging senior authorship to build an early relationship.', 'early', '{"Citation volume declined by 158 between the two windows, tempering the significance of publication and network growth."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4f07f8d0-9614-42fa-9ba8-668ce160a778', '1dda9bc1-73c9-40af-90cb-13beed0ec5dd', 'nsclc', 'Michael S. Oh is an Emerging Leader in NSCLC whose publication output has grown modestly, from 7 papers (2016–2020) to 8 papers (2021–2025), signaling sustained research engagement across nine career years at Northwestern University. The strongest signal is collaborator network contraction. His active collaborator count declined from 47 (2016–2020) to 29 (2021–2025), a reduction of 18 individuals, suggesting a deliberate narrowing toward focused research partnerships. Citation volume has decreased by 147 over the same comparison, a pattern consistent with an early-career researcher whose recent work has not yet accumulated broad downstream uptake. Senior-authored output has not yet appeared in either window. A first senior-authored publication in NSCLC would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:15.851006+00', 'Sustained publication output across both windows marks continued research presence despite network contraction.', 'Early relationship-building now, with monitoring for a first senior-authored NSCLC publication as the key inflection point.', 'early', '{"No senior-authored output yet, declining collaborator count, and falling citation volume collectively limit current influence signals."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('4ff72ca3-fbe6-494f-8c7b-aa82d7ad6364', 'f6cd0c53-1b5f-4491-b501-7e5e933e9f31', 'nsclc', 'Dr. Marjorie G. Zauderer is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center with 15 years of career experience. Her publication output grew from 12 papers (Aug 2016–Jul 2021) to 15 papers (Aug 2021–Jul 2026), reflecting steady and sustained productivity. The strongest signal is her collaborator network expansion. That network grew from 165 collaborators (Aug 2016–Jul 2021) to 228 collaborators (Aug 2021–Jul 2026), a gain of 63 individuals representing nearly 40% growth in reach. Senior-author share held steady across both windows, indicating consistent intellectual ownership of her work. A transition into higher-volume senior-authored output across this expanded network would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:46.067376+00', 'Collaborator network expanded by 63 individuals between Aug 2021–Jul 2026, signaling broadening scientific reach.', 'Engage around her expanding collaborator network to identify emerging multi-institutional Lung Cancer research opportunities.', 'early', '{"Citation volume declined by 393 between the two windows, suggesting recent work has not yet accumulated broad downstream engagement."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('516cf2b8-f720-41e0-b6e5-8636a45b2d29', '533cc59b-600b-4fbd-a4da-e0ff901643c8', 'nsclc', 'Marianna Macerelli is an Emerging Leader in NSCLC based at Ospedale Santa Maria della Misericordia di Udine, with 13 years of career experience and a Rising Star composite percentile of 66.2 (global rank 556). Publication output grew from 11 papers (2016–2020) to 14 (2021–2025), while her collaborator network expanded from 159 to 243 individuals, a 53% increase reflecting broadening scientific reach. Network Visibility is the strongest component of her profile, registering at the 80th percentile, supported by Scientific Momentum at the 74th percentile. Senior-author share remains at zero across both periods, which tempers the overall signal. First evidence of a senior-authored publication would mark a meaningful inflection in her independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:10:23.635766+00', 'Collaborator network grew from 159 to 243, driving Network Visibility to the 80th percentile.', 'Engage now around her expanding collaborator network; monitor closely for first senior-authored NSCLC publication.', 'early', '{"Senior-author share is zero across both periods (2016–2020 and 2021–2025), and citation volume declined by 154."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('51a236d4-16c8-4837-82f3-e94d487fa992', 'd9eb06e3-c348-4141-8e2b-fc2ff4cd99f2', 'nsclc', 'Jared J. Fradette is an Emerging Leader in NSCLC research based at The University of Texas MD Anderson Cancer Center, with 9 years in the field. He has maintained a consistent publication output, producing 10 papers from 2016–2020 and 9 papers from 2021–2025. The defining feature of the profile is the contraction in collaborative network. His collaborator count declined from 79 in 2016–2020 to 37 in 2021–2025, suggesting a shift toward a more focused, concentrated research effort. Authorship has not yet extended into senior-authored output. First evidence of a senior-authored publication would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:08.578444+00', 'Sustained publication output across both windows signals continued active research presence in NSCLC.', 'Early relationship-building now, monitoring closely for a first senior-authored NSCLC publication as the key inflection signal.', 'early', '{"No senior-authored output yet, and collaborator network has contracted from 79 to 37, limiting broader field visibility."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('526bc878-d050-40fd-ab37-86800b09bb7b', 'dd6342b2-5f9a-4183-92b3-139273d7f5bf', 'nsclc', 'Giandomenico Roviello is an Emerging Leader in NSCLC based at the University of Florence, 13 years into his career. Scientific momentum is the primary driver of his Rising Star composite percentile of 72.1, with publication output growing from 10 papers (2016–2020) to 12 (2021–2025) alongside a network expansion from 35 to 47 collaborators, a 34% increase. The strongest signal is network momentum, which sits at the 76th percentile. Collaborator count grew by 12 individuals across periods, suggesting broadening scientific engagement. A transition into consistent senior authorship, currently at zero share, would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:59:07.198667+00', 'Collaborator network grew 34%, from 35 to 47, driving a network momentum percentile of 76.', 'Early relationship-building now, monitoring closely for first senior-authored NSCLC publication as engagement inflection point.', 'early', '{"Senior-author share remains zero across both periods, and citation volume declined by 94, limiting visibility impact."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('52c06faf-b163-4595-bf77-fcbab6f51b59', '223de699-3f03-41b8-b005-55b831a45274', 'nsclc', 'Yuki Shinno is an Emerging Leader in NSCLC based at National Cancer Center, now nine years into an independent research career. The strongest signal is publication output. Output increased more than five-fold, from 8 papers (2016–2020) to 42 papers (2021–2025), while citation volume grew by 574 across the same period. Network expansion mirrors this pattern, with collaborators growing from 26 to 142 — a more than five-fold increase — indicating broad and accelerating scientific connectivity. All output to date reflects non-senior authorship; a transition into senior-authored publications would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:16.038958+00', 'Publication output grew more than five-fold, from 8 to 42 papers, alongside a 574-citation volume increase.', 'Monitor for first senior-authored publication as the trigger point for deeper scientific exchange and relationship-building.', 'early', '{"No senior-authored output has been recorded yet, limiting evidence of independent scientific leadership at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('54831705-39ba-47b4-988c-ef08e3fa8012', 'b070fd6e-c671-43f1-bd28-43eeae1b882d', 'nsclc', 'Waree Rinsurongkawong is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, now nine years into her career. The strongest signal is publication output. Her output grew more than three-fold, from 7 papers (2016–2020) to 23 papers (2021–2025), accompanied by a citation volume increase of 692. Her collaborator network expanded from 88 to 259 individuals across the same windows, reflecting broad and growing scientific connectivity. All output to date appears in non-senior authorship positions. A first senior-authored publication would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:42.655694+00', 'Publication output more than tripled to 23 papers (2021–2025), alongside a 692-citation volume increase.', 'Initiate early relationship-building now and monitor closely for a first senior-authored NSCLC publication as a key inflection point.', 'early', '{"No senior-authored output has been recorded yet, limiting evidence of independent scientific leadership at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('54a213f9-0862-4b4a-8023-eaae26e3ca75', '0246151b-64b2-4676-ad82-c4044975dd57', 'nsclc', 'Arturo Navarro-Martín is an Emerging Leader in NSCLC based at Institut Català d''Oncologia with 14 years of career experience and a Rising Star composite percentile of 71.6 (global rank 467). Publication output grew from 6 papers (2016–2020) to 10 papers (2021–2025), while his collaborator network expanded from 29 to 72 individuals, representing nearly a 2.5-fold increase in network breadth. Scientific Momentum sits at the 77th percentile and Network Momentum at the 76th percentile, indicating balanced growth across both dimensions. Scientific and Network Visibility remain lower, at the 36th and 45th percentiles respectively, suggesting recognition has not yet caught up with productivity. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:12:29.147626+00', 'Collaborator network nearly 2.5x growth, from 29 to 72, drives current Rising Star momentum.', 'Early relationship-building now, monitoring closely for first senior-author publications as a key inflection signal.', 'early', '{"Senior-author share remains at 0 across both periods, and citation volume declined by 117, limiting visibility impact."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('54cfeffd-1f00-4a57-9ba5-8f290394f15f', '885dde09-d579-45c1-9501-32a185cdcdfd', 'nsclc', 'Lukas Käsmann is an Emerging Leader in NSCLC based at LMU Klinikum, with a Rising Star composite percentile of 92.6 (global rank 123). Publication output grew from 18 papers (2016–2020) to 31 papers (2021–2025), a 72% increase, while his collaborator network expanded nearly fourfold, from 39 to 144 unique collaborators. The strongest signal is network momentum, which sits at the 84th percentile. That expansion from 39 to 144 collaborators reflects a rapidly broadening sphere of scientific engagement across the field. Senior-author share remains at zero across both periods; a first senior-authored publication in NSCLC would mark a meaningful inflection in his independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:01:36.433716+00', 'Collaborator network grew nearly fourfold, from 39 to 144, placing network momentum at the 84th percentile.', 'Engage around his expanding collaborator network and monitor closely for a first senior-authored NSCLC publication.', 'moderate', '{"Senior-author share is zero across both periods, and citation volume declined 21%, limiting evidence of independent scientific influence."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('5521a4c3-4e53-457c-b939-8baef197b726', 'adabbd76-2c00-4b85-9c7f-713523c4c859', 'nsclc', 'Carl M. Gay is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, now ten years into his career. The strongest signal is publication output. His output grew three-fold, from 13 papers (2016–2020) to 39 papers (2021–2025), while citation volume expanded by 906 citations across the same shift. His collaborator network grew from 154 to 483 individuals, more than tripling in scale, reflecting broad cross-institutional engagement. Senior-author share is receding, a pattern consistent with a scientist deepening collaborative breadth rather than consolidating independent output. A transition into sustained senior authorship on high-impact NSCLC manuscripts would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:36.003438+00', 'Publication output tripled to 39 papers and collaborator network more than tripled to 483 individuals.', 'Engage now around his expanding collaborator network as a foundation for early relationship-building before senior authorship consolidates.', 'early', '{"Senior-author share is receding, suggesting independent scientific voice is not yet consolidating despite strong collaborative growth."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('5562310d-20ec-4210-8296-cd52a474e4d4', 'de03c1a2-7486-48cb-846f-00c868e0d054', 'nsclc', 'Matthew M. Harkenrider is an Emerging Leader in NSCLC with 15 years of career experience at Loyola University Chicago. He has maintained a consistent publication presence, producing 7 papers from 2016–2020 and 6 from 2021–2025, with a publication velocity delta of +2 indicating a modest recent uptick in output pace. The strongest signal is authorship positioning. He is moving toward senior authorship, a structural shift that often precedes expanded field influence. His collaborator network has narrowed from 46 individuals in 2016–2020 to 22 in 2021–2025, suggesting a deliberate consolidation around core research relationships. A first senior-authored publication in NSCLC would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:59.908629+00', 'A positive publication velocity delta of +2 coincides with a clear move toward senior authorship roles.', 'Initiate early relationship-building now, ahead of an anticipated transition into senior authorship in NSCLC.', 'early', '{"Citation volume declined by 163, and the collaborator network halved from 46 to 22, limiting current external reach."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('562b61f0-b4b8-4ea8-8dd1-7e1b93871f58', 'd6493af8-139e-411a-afca-eb053d339deb', 'nsclc', 'Francesco Pepe is an Emerging Leader in NSCLC based at the University of Naples Federico II, with 10 years of career experience and a Rising Star composite percentile of 71.8 (global rank 465). Publication output more than doubled, from 16 papers (2016–2020) to 35 (2021–2025), while his collaborator network expanded threefold, from 68 to 204 unique collaborators. Scientific Visibility is the strongest individual component at the 87th percentile, indicating that his work is reaching a broad audience despite moderate momentum scores. Senior-author share remains at zero across both periods, which contextualizes the visibility gains as contributor- rather than driver-level recognition. A first appearance as senior author on an NSCLC-focused publication would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:57:28.95839+00', 'Collaborator network tripled from 68 to 204, signaling rapid integration into the NSCLC research community.', 'Monitor for first senior-authored NSCLC publication as the trigger for deeper scientific engagement.', 'early', '{"Senior-author share is zero across both periods; visibility gains may reflect contributor roles rather than independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('5678d1aa-6eb3-44cb-98dd-041452bdcc3f', 'ca4abb14-228c-4dba-99f7-b3b99ee19226', 'nsclc', 'Marco Chiappetta is an Emerging Leader in NSCLC based at Università Cattolica del Sacro Cuore, with 11 years of career experience and a Rising Star composite percentile of 65.1 (global rank 574). Publication output more than doubled, from 10 papers (2016–2020) to 25 (2021–2025), while his collaborator network expanded more than five-fold, from 30 to 164 co-investigators across the same periods. Citation volume grew by 9, and network visibility sits at the 65th percentile, indicating broadening recognition within the field. First evidence of a senior-authorship contribution would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:07:15.082085+00', 'Collaborator network expanded more than five-fold, from 30 to 164, signaling rapid network integration.', 'Engage now around growing collaborator network; monitor closely for first senior-authorship publication as a relationship milestone.', 'early', '{"Senior-author share remains at zero across both periods, suggesting Chiappetta has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('57bf623d-53e8-4bf8-b92a-c6699cf2421a', 'd2b69143-a12e-4d10-9a02-c304e5874ea0', 'nsclc', 'Ruoying Yu is an Emerging Leader in NSCLC whose most notable development over the past decade is a substantial expansion of collaborative reach. The strongest signal is network growth. Collaborator count grew from 33 in 2016–2020 to 97 in 2021–2025, nearly a threefold increase in raw numbers. Publication output doubled from 5 papers in 2016–2020 to 10 in 2021–2025, though citation volume has not yet grown in step with that expanded output. No senior-authored work has appeared to date. A first senior-authored publication would mark a meaningful inflection in this profile''s development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:47.645861+00', 'Collaborator network nearly tripled, from 33 to 97, signaling rapidly expanding scientific connectivity.', 'Monitor for transition into senior authorship as the natural next milestone to prompt deeper engagement.', 'early', '{"Citation volume has declined and no senior-authored output has emerged yet, limiting evidence of independent scientific influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('5a017edf-6f4d-48ae-9607-cfc2b25e5841', '2e4e4a1d-06eb-4d10-aeac-20ddd2f7f4f7', 'nsclc', 'Latasha Little is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, now nine years into her career. She has maintained a steady publication output of 5 papers in both the 2016–2020 and 2021–2025 windows, reflecting consistent engagement with the field. Her collaborator network remains broad and stable, spanning 90 individuals in the earlier window and 87 in the current one. No senior-authored output has appeared to date, marking an important next stage in her development. A first senior-authored publication would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:19:09.547416+00', 'Stable output of 5 papers and an 87-person collaborator network signal sustained, consistent field engagement.', 'Early relationship-building now positions the MSL well ahead of an anticipated transition into senior authorship.', 'early', '{"No senior-authored output has emerged across either window, and citation volume has declined by 413, limiting current independent scientific visibility."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('5c47e36b-a53b-41fc-bae0-8c95d8d09ec7', '11a0b3e5-5015-4011-b316-a96d6f5d7525', 'nsclc', 'Runzhe Chen is an Emerging Leader in NSCLC research based at The University of Texas MD Anderson Cancer Center, with 11 years of career activity. Publication output held steady at 9 papers in both the 2016–2020 and 2021–2025 windows, reflecting consistent scientific engagement. The defining feature of the profile is the collaborator network. That network contracted from 146 collaborators in 2016–2020 to 109 in 2021–2025, suggesting a shift toward more focused research relationships. Authorship has not yet moved into senior-authored output. A first senior-authored publication would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:40.963162+00', 'Consistent output of 9 publications across both five-year windows signals sustained NSCLC research engagement.', 'Early relationship-building now, monitoring closely for a first senior-authored NSCLC publication as the key milestone.', 'early', '{"No senior-authored output yet, and collaborator network declined by 37, suggesting narrowing scientific reach."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('5c61c8f6-d7a1-434f-b5a0-2c6fe8c46c33', 'abc2e087-6621-42c5-8283-691093313e40', 'nsclc', 'Guofang Zhao is a Balanced Rising Star in NSCLC at Ningbo No. 2 Hospital, ranked 72nd globally with a composite percentile of 95.7 across a 10-year career. Publication output grew from 12 to 16 papers across consecutive five-year periods, while citation volume expanded by 105, signaling deepening scientific engagement. The strongest signal is network momentum, which sits at the 91st percentile. Collaborator count grew more than six-fold, from 37 to 225 individuals, reflecting a rapid and sustained expansion of scientific relationships. A transition into senior authorship would represent the next meaningful milestone to monitor in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:10:02.169901+00', 'Collaborator network expanded six-fold, from 37 to 225, driving a 91st-percentile network momentum score.', 'Engage now around the expanding collaborator network while monitoring closely for a first senior-author publication.', 'high', '{"Senior-author share remains at zero across both periods, indicating Zhao has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('5e370fa9-9118-423d-9c7e-b6175c11f840', '5eb689e2-09e1-4773-989e-1f1c81063348', 'nsclc', 'Dorothy J. Giroux is an Emerging Leader in NSCLC research based at Cancer Research And Biostatistics, five years into her career. The strongest signal is publication output. She produced 5 papers from 2016–2020, rising to 11 papers from 2021–2025, representing more than a doubling in raw output across the two windows. Her collaborator network contracted from 123 individuals in 2016–2020 to 54 in 2021–2025, suggesting a shift toward a more focused set of working relationships. No senior-authored output has appeared to date. A first senior-authored publication in NSCLC would mark a meaningful inflection in her independent scientific voice.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:34.449073+00', 'Publication output more than doubled, from 5 papers to 11, across consecutive five-year windows.', 'Monitor for transition into senior authorship as the primary trigger for deeper MSL relationship-building.', 'early', '{"No senior-authored output yet, and a sharply contracted collaborator network may limit broader scientific reach at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('5fa1bf38-64c6-41a6-83af-04f148153766', '2787d84a-a328-482e-90b4-02982a3028aa', 'nsclc', 'Robert E. Merritt is an Emerging Leader in NSCLC based at The Ohio State University Wexner Medical Center, with 15 years of career experience. Publication output more than doubled, from 7 papers (2016–2020) to 15 papers (2021–2025), accompanied by a citation volume increase of 129 citations. The strongest signal is network expansion. His collaborator base grew from 43 to 97 individuals across the same windows, representing more than a twofold increase in co-author reach. Senior-author share is receding, suggesting a broadening collaborative role rather than consolidating independent output. A transition back toward senior authorship on NSCLC-focused work would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:44.248857+00', 'Collaborator network more than doubled to 97, alongside a 129-citation volume increase in 2021–2025.', 'Engage now around his expanding collaborator network to establish early relationships before senior-authorship consolidation.', 'early', '{"Senior-author share is receding, which may limit independent scientific positioning and reduce visibility as a primary voice in NSCLC."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('60a37246-a84b-41e0-90e3-ead0e7c337f8', 'fbce07d2-eead-4a7e-b0c4-9b5080bce7d0', 'nsclc', 'Jia-Tao Zhang is an Emerging Leader in NSCLC based at Guangdong Academy of Medical Sciences with 9 years in the field and a Rising Star composite percentile of 94.9 (global rank 84). Publication output increased five-fold, from 5 papers (2016–2020) to 25 papers (2021–2025). The strongest signal is network momentum, which sits at the 97th percentile for visibility and 89th percentile for momentum. His collaborator base expanded more than eight-fold, from 38 to 305 individuals across the two periods. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:58:36.652666+00', 'Collaborator network expanded eight-fold, from 38 to 305, driving 97th-percentile network visibility.', 'Engage now around his expanding collaborator network; monitor closely for first senior-authored NSCLC publication as a key inflection signal.', 'moderate', '{"Senior-author share remains at 0% across both periods, and citation volume declined by 213, limiting independent scientific attribution."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('653a3a52-dc3f-4db0-810e-6107b2fdc218', '64ac997c-a96c-4408-800d-b09ab579b763', 'nsclc', 'Jimmy Ruiz is an Emerging Leader in NSCLC at Wake Forest University, now 11 years into his career. The strongest signal is network expansion. His active collaborator base grew from 57 individuals in 2016–2020 to 87 in 2021–2025, a gain of 30 colleagues. Publication output increased modestly, from 14 papers in 2016–2020 to 17 in 2021–2025, while senior-author share has been receding across the same period. A transition into sustained senior authorship would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:40.022708+00', 'Collaborator network expanded by 30 individuals across consecutive five-year windows, signaling broadening scientific connectivity.', 'Engage now around the expanding collaborator network to establish presence before independent senior-authored work emerges.', 'early', '{"Senior-author share is receding and citation volume declined by 466, raising questions about independent scientific output consolidation."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('658cf0ef-7516-4f7a-aed7-6c20d9a2f44d', '252b48b2-12ab-43aa-9ed6-07ec7710fff4', 'nsclc', 'Dr. Loretta Erhunmwunsee is a rising Lung Cancer investigator at City of Hope whose research footprint has expanded meaningfully across two consecutive five-year windows. The strongest signal is her collaborator network. It grew from 33 collaborators (Aug 2016–Jul 2021) to 45 collaborators (Aug 2021–Jul 2026), a gain of 12 distinct research relationships in a single window. Publication output moved from 7 papers (Aug 2016–Jul 2021) to 9 papers (Aug 2021–Jul 2026), and her senior-author share rose between the two windows, indicating growing intellectual ownership of her research agenda. A first high-profile senior-authored publication in a flagship thoracic oncology journal would mark a meaningful inflection in her national visibility.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:24.113834+00', 'Her collaborator network expanded by 12 relationships in the most recent five-year window.', 'Engage now around her expanding collaborator network to establish presence before her senior-author profile solidifies.', 'early', '{"Citation volume declined by 94 between the two windows, suggesting recent work has not yet accumulated broad downstream engagement."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('65badf87-56b9-4204-83c3-8d1b811baccc', '7216a7d6-a583-466d-8974-157592667767', 'nsclc', 'Yin P. Hung is a rising Lung Cancer investigator at Massachusetts General Hospital whose research output has grown from 12 publications (Aug 2016–Jul 2021) to 18 publications (Aug 2021–Jul 2026). The strongest signal is network expansion. Collaborator count increased from 78 (Aug 2016–Jul 2021) to 130 (Aug 2021–Jul 2026), a gain of 52 colleagues reflecting broadening cross-institutional engagement. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), marking a meaningful shift in research independence. A sustained pattern of senior-authored publications in the next window would represent the next milestone in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:09:09.331916+00', 'Senior-authored output emerged in Aug 2021–Jul 2026 after being absent in the prior five-year window.', 'Engage now around the emerging senior authorship pattern to build an early relationship before independent research agenda solidifies.', 'early', '{"Citation volume declined by 451 between the two windows, suggesting limited downstream uptake of recent work so far."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('671ab26a-c674-4258-8905-980316d7ae83', '9b02d167-e5d5-4f73-9862-d9ac6cf6313c', 'nsclc', 'Paula A. Ugalde is an Emerging Leader in NSCLC based at Brigham and Women''s Hospital, now eight years into her career. The strongest signal is publication output growth. She produced 7 papers from 2016–2020 and 11 from 2021–2025, a meaningful increase in absolute volume. Her collaborator network has modestly contracted, from 89 to 80 individuals across the same windows, and her senior-author share is receding rather than expanding. A transition into a stabilized or growing senior-authorship pattern would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:09.897695+00', 'Publication output grew from 7 to 11 papers across consecutive five-year windows, signaling increasing research activity.', 'Early relationship-building now, with close monitoring for a reversal in senior-authorship direction.', 'early', '{"Senior-author share is receding and citation volume declined by 54, suggesting output growth has not yet translated into field influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('6b6349c5-a093-4a8c-9f8e-972778007c52', 'c8c7c187-a6b2-412b-8868-2ae7e35fa450', 'nsclc', 'Jinbo Zhao, at Air Force Medical University, is a Balanced Rising Star in NSCLC with a composite Rising Star percentile of 94.1, ranking 98th globally. Publication output doubled from 9 papers (2016–2020) to 18 papers (2021–2025), while citation volume grew by 258, reflecting sustained scientific productivity. The strongest signal is network momentum, which sits at the 88th percentile. Collaborator count expanded nearly threefold, from 31 to 89 individuals across the two periods. A transition into consistent senior authorship, given the current senior-author share of zero, would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:11:36.87306+00', 'Collaborator network nearly tripled from 31 to 89, driving 88th-percentile network momentum.', 'Monitor for first senior-authored publications as a trigger for proactive relationship-building.', 'moderate', '{"Senior-author share remains zero across both periods, limiting evidence of independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('6b8d3c5a-1786-4ab6-8abe-6cc1a9b91b4f', '41daa2ec-d008-47c7-a51d-26d4faf90f0c', 'nsclc', 'Zhiyong He is a Balanced Rising Star in NSCLC at Fujian Medical University, ranked 30th globally with a composite Rising Star percentile of 98.2. Publication output more than doubled, from 8 papers (2016–2020) to 17 (2021–2025), while citation volume grew by 687, signaling deepening scientific impact. The strongest signal is network expansion. Collaborator count grew nearly fourfold, from 63 to 238, placing network momentum at the 86th percentile and network visibility at the 93rd. This profile is characteristic of a Balanced Rising Star with reinforcing scientific and relational growth across 13 career years. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:03:13.16986+00', 'Collaborator network expanded nearly fourfold to 238, driving a 93rd-percentile network visibility score.', 'Engage now around the expanding collaborator network; monitor closely for first senior-authored NSCLC publication as a relationship inflection point.', 'high', '{"Senior-author share remains at zero across both periods, suggesting influence may still be intermediary rather than independently driven."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('6d540757-01f9-46bd-b2bf-09483282b9fb', '6e7acc52-2544-4d15-9b9b-625bbb075d8c', 'nsclc', 'Yanyan Lou is a rising Lung Cancer investigator at Mayo Clinic in Florida whose profile is defined by a sharp expansion in both research output and collaborative reach. The strongest signal is publication growth: output increased from 19 papers (Aug 2016–Jul 2021) to 31 papers (Aug 2021–Jul 2026), a gain of more than 60% across the two windows. Collaborator count grew more than three-fold, from 65 (Aug 2016–Jul 2021) to 214 (Aug 2021–Jul 2026), reflecting a broadening professional network. Senior-author share was lower in the recent window than in the earlier one, indicating a current phase of collaborative contribution rather than independent agenda-setting. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:42.504387+00', 'Collaborator count more than tripled, from 65 to 214, signaling rapid network expansion in Lung Cancer.', 'Monitor for transition into senior authorship as the clearest signal of independent research agenda emergence.', 'early', '{"Senior-author share declined in the recent window, and citation volume fell by 660, suggesting influence has not yet matched output growth."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('6d6fc3d5-bb90-4d78-9e15-e18ec49be033', '13da93e6-a899-41cf-adaf-d811a54b3614', 'nsclc', 'Sonam Puri is a rising Lung Cancer investigator at the University of Utah, now nine years into an increasingly productive research career. The strongest signal is publication output. Between Aug 2021 – Jul 2026, she authored 20 papers, compared with 7 in Aug 2016 – Jul 2021 — nearly a three-fold increase in the same span. Her collaborator network expanded from 33 individuals (Aug 2016 – Jul 2021) to 236 (Aug 2021 – Jul 2026), more than a seven-fold growth, and citation volume grew by 270 over the same comparison. Senior-authored output appears in the Aug 2021 – Jul 2026 window but was absent in Aug 2016 – Jul 2021. A sustained pattern of senior-authored publications in high-impact Lung Cancer journals would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:12.76964+00', 'Publication output nearly tripled, from 7 to 20 papers, while her collaborator network expanded more than seven-fold.', 'Engage now around her expanding collaborator network and emerging senior authorship to build an early, substantive relationship.', 'moderate', '{"The collaborator count growth is striking and warrants monitoring to confirm whether these reflect deep, sustained research partnerships or broader conference-level connections."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('6dab1480-d705-479d-a7fc-63af5b456860', 'ad99437a-6926-4329-8d55-28a23cd74f59', 'nsclc', 'Ryo Ariyasu is a clinical researcher at The Cancer Institute Hospital with approximately 9 years of publication history and a total of 108 career publications, reflecting a sustained and productive research output in non-small cell lung cancer. While publication velocity and citation trajectory remain in earlier growth stages relative to the broader TA population, Ariyasu''s clinical trial activity ranks at the 93rd percentile within the therapeutic area — a standout signal that positions him as an operationally active and clinically embedded investigator. Within the curated Rising Star cohort, his overall score at the 48th percentile reflects a researcher whose influence is concentrated in trial participation rather than bibliometric reach, making him a meaningful emerging voice in the clinical execution of NSCLC research.', 'v1.0', 'claude-sonnet-4-6', '2026-06-04 07:55:17.663722+00', 'Ariyasu''s exceptional clinical trial activity percentile (93rd within NSCLC) signals that he is currently embedded in active study infrastructure, making this a high-value window for scientific exchange while trials are ongoing and clinical questions are live.', 'Given his deep clinical trial involvement in NSCLC, productive MSL conversations could center on emerging biomarker-driven patient selection strategies and the evolving landscape of targeted therapy sequencing in lung cancer. His institutional base at The Cancer Institute Hospital also suggests openness to discussions around real-world clinical trial design challenges and endpoints relevant to NSCLC populations.', 'Signal strength is moderate-to-strong specifically on the clinical trial dimension, with high confidence that Ariyasu is an active trial investigator; bibliometric signals are early-stage and should not be weighted heavily in assessing his current influence.', NULL::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('6f32e23c-c0fa-4b0e-9bf3-69a163b50f67', '2a40745d-1e91-4ab3-9f98-8533eb44d129', 'nsclc', 'Pedro Rocha is a Network Accelerator in NSCLC at Hospital Del Mar, ranked 113rd globally with a Rising Star composite percentile of 93.2 after 9 years in practice. The defining feature of this profile is network momentum. Collaborator count expanded more than eleven-fold, from 27 to 305 individuals across the two periods, placing him at the 98th percentile for network momentum globally. Publication output also grew, rising from 6 to 21 papers, with citation volume increasing by 293, though scientific momentum sits at a more moderate 65th percentile. First evidence of a senior-author credit would mark a meaningful inflection in how his growing network translates into independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:41:43.069478+00', 'Collaborator network grew eleven-fold, from 27 to 305, placing him at the 98th network momentum percentile.', 'Engage through his broad collaborator network now, while monitoring closely for first senior-author publication.', 'moderate', '{"Senior-author share remains zero across both periods, suggesting influence is currently network-driven rather than independently led."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7004a545-4c98-44a8-b150-0c86a48fe322', 'be2dc1c5-d7a4-4fa0-a986-e814c5c95f1e', 'nsclc', 'Yong Fang is an Emerging Leader in NSCLC based at Sir Run Run Shaw Hospital, with 15 years of career experience and a Rising Star composite percentile of 98.0, ranking 33rd globally. Publication output increased nearly four-fold, from 7 papers (2016–2020) to 26 papers (2021–2025), accompanied by a citation volume growth of +1,114. The strongest signal is network expansion. Collaborator count grew from 52 to 440 between the two periods, an increase of more than eight-fold, placing network momentum at the 90th percentile and network visibility at the 97th percentile globally. First evidence of a transition into consistent senior authorship, given a current senior-author share of zero, would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:47:26.771231+00', 'Collaborator network expanded more than eight-fold, from 52 to 440, driving a 97th-percentile network visibility score.', 'Engage now around the expanding collaborator network; monitor closely for first senior-author publication as a key inflection signal.', 'high', '{"Senior-author share remains zero across both periods, indicating Fang has not yet assumed independent scientific leadership on publications."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('706bfe50-2cc8-4a64-8cd7-7cc6ee8f9196', '792bf9eb-6f88-4513-a46b-6d350525b234', 'nsclc', 'Pernelle Lavaud is an Emerging Leader in NSCLC based at Institut Gustave Roussy, with 11 years of career experience and a Rising Star composite percentile of 70.8 (global rank 480). Publication output more than doubled across periods, rising from 7 papers (2016–2020) to 15 papers (2021–2025), driving a Scientific Momentum percentile of 79. Network breadth expanded substantially, from 73 collaborators to 130, supporting a Network Visibility percentile of 74. Scientific Visibility remains more modest at the 48th percentile, suggesting output growth has not yet translated into broad field-wide citation recognition. A transition into a senior-author role on a high-profile NSCLC publication would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:57:43.784687+00', 'Publication output doubled to 15 papers (2021–2025), pushing Scientific Momentum to the 79th percentile.', 'Monitor for first senior-authored NSCLC publication; initiate early relationship-building given currently low scientific visibility.', 'early', '{"Senior-author share remains at zero across both periods, and citation volume growth is negative at -218, limiting visibility impact."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('70cf2d9b-09a3-43be-b492-85eefe07c745', '3af57fbe-03e7-443f-908b-95acd7cdaf97', 'nsclc', 'Kejing Tang (Sun Yat-sen University) is a Balanced Rising Star in NSCLC, ranked 15th globally with a composite Rising Star percentile of 99.2. Publication output more than doubled, from 7 papers (2016–2020) to 17 (2021–2025), while citation volume grew by 149 citations across the same window. The strongest signal is network momentum, which sits at the 93rd percentile. Collaborator count expanded nearly six-fold, from 45 to 267 individuals, signaling rapid integration into the broader NSCLC research community. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:59:37.24638+00', 'Collaborator network expanded nearly six-fold, from 45 to 267, driving a 93rd-percentile network momentum score.', 'Engage now around the expanding collaborator network; monitor closely for first senior-authored publication as a relationship inflection point.', 'high', '{"Senior-author share remains at zero across both periods, meaning Tang has not yet established independent research leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('725e3e33-cb36-4d07-9e49-854d2a69b539', '4c51d916-474e-4602-aa3f-e5f972a751be', 'nsclc', 'Ryan D. Gentzler is an Emerging Leader in NSCLC based at the University of Virginia, now 14 years into his career. The strongest signal is network expansion. His collaborator count grew from 62 in 2016–2020 to 167 in 2021–2025, a nearly threefold increase in a single window. Publication output also grew, from 15 papers in 2016–2020 to 23 in 2021–2025, though citation volume and publication velocity have not kept pace with that output increase. Senior-author share is receding, and a transition into a stabilized senior-authorship pattern would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:11.088406+00', 'Collaborator network nearly tripled, from 62 to 167, signaling rapid expansion of scientific connectivity.', 'Engage now around the expanding collaborator network to establish presence before senior-authorship consolidation occurs.', 'early', '{"Senior-author share is receding and citation volume declined, suggesting output growth has not yet translated into field-defining work."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('73379490-a586-4de5-856d-331bf1d6d23a', 'cb13e7b9-2c1c-4890-a967-f282699eb27e', 'nsclc', 'Isa Mambetsariev is an Emerging Leader in NSCLC based at City of Hope, now ten years into an active research career. Publication output grew from 18 papers (2016–2020) to 28 papers (2021–2025), while citation volume expanded by 309 citations across the same shift. The strongest signal is network growth. Collaborator count increased from 58 to 106 individuals, nearly doubling across the two windows. All output to date reflects contributing or mid-level authorship, with no senior-authored work yet recorded. A first senior-authored publication would represent the next meaningful milestone in this profile''s development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:13.656148+00', 'Citation volume grew by 309 and collaborator count nearly doubled, from 58 to 106.', 'Build early relationship now and monitor for first senior-authored NSCLC publication as a key inflection point.', 'early', '{"No senior-authored output has been recorded yet, limiting evidence of independent scientific leadership in NSCLC."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('73a2322e-2a51-45f0-8d4e-6d6ee6622f20', '8ecced92-e307-4f6c-906b-77d68205c569', 'nsclc', 'Marcelo V. Negrão is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center, now nine years into his career. The strongest signal is publication output. From Aug 2021 – Jul 2026 he produced 40 papers, compared with 16 in Aug 2016 – Jul 2021 — a 2.5-fold increase in raw count, accompanied by a citation volume growth of +84 and a publication velocity delta of +2. His collaborator network expanded from 169 (Aug 2016 – Jul 2021) to 426 (Aug 2021 – Jul 2026), more than doubling in breadth. Notably, senior-authored output appears in the Aug 2021 – Jul 2026 window but was absent in the earlier window. A sustained pattern of senior-authored publications in high-impact Lung Cancer journals would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:09:32.127678+00', 'Citation volume grew by 84 alongside a 2.5-fold rise in publications from Aug 2021 – Jul 2026.', 'Engage now around his expanding collaborator network and emerging senior authorship to build an early relationship.', 'early', '{"Senior authorship is newly emergent in the recent window; its consistency and journal impact level remain to be established."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('741d36ea-9691-43f9-8166-2ccbe032c639', 'f40a6ef1-ba7c-4f25-b635-fa7a1c791b28', 'nsclc', 'Shahed N. Badiyan is an Emerging Leader in NSCLC based at Washington University in St. Louis, with 14 years of career experience. He contributed 11 publications from 2016–2020 and 7 from 2021–2025, while his collaborator network expanded from 43 to 46 individuals across the same windows. The defining feature of the profile is authorship positioning. He is moving toward senior authorship, a structural shift that often precedes increased independent influence within a field. A first senior-authored NSCLC publication would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:48.788793+00', 'Authorship is shifting toward senior roles across a stable, expanding 46-person collaborator network.', 'Prioritize early relationship-building now, ahead of an anticipated transition into senior authorship roles.', 'early', '{"Citation volume declined by 224 across windows, and publication count decreased from 11 to 7, warranting close monitoring."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7ae7aaaa-809b-4d7e-9263-35f2ef1d918f', '4effa7bc-74d4-4dbb-abb3-18e7e4ffb8ca', 'nsclc', 'Marco Russano is an Emerging Leader in NSCLC based at Università Campus Bio-Medico with 13 years of career experience and a Rising Star composite percentile of 72.2 (global rank 458). Publication output doubled from 11 papers (2016–2020) to 22 papers (2021–2025), and his collaborator network expanded from 154 to 315 individuals, reflecting broad and growing scientific engagement. Network Visibility is the stronger pillar of this profile, ranking at the 80th percentile globally, while Scientific Visibility sits at the 76th percentile. Senior-author share remains at zero across both periods, which contextualizes the publication growth as primarily a contributor-level signal. First evidence of a senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:12:13.976801+00', 'Collaborator network doubled to 315 (2021–2025), driving an 80th-percentile Network Visibility score.', 'Monitor for transition into senior authorship; build early relationship now given rising network visibility but low independent output.', 'early', '{"Senior-author share is zero across both periods; publication growth reflects contributor roles, not independent scientific leadership yet."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7bb4e096-d343-48c1-b7ab-9398b28168ee', 'd618afda-35d1-469d-a0f9-41903f7a8f0c', 'nsclc', 'Matteo Santoni is a Scientific Accelerator in NSCLC based at Ospedale di Macerata, with 15 years of career experience and a Rising Star composite percentile of 74 (global rank 429). The strongest signal is scientific momentum, which ranks at the 91st percentile. Publication output grew from 7 papers (2016–2020) to 8 (2021–2025), while citation volume expanded by 246 citations across the same periods, indicating deepening field engagement. Network breadth increased from 99 to 138 collaborators, reflecting a 39% expansion in active scientific relationships. A transition into a senior-author role would represent the next meaningful milestone for this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:00:53.335826+00', 'Citation volume surged by 246 across periods, driving a 91st-percentile scientific momentum score.', 'Monitor closely for first senior-authored NSCLC publication as a trigger for proactive relationship-building.', 'early', '{"Senior-author share remains at 0 across both periods, indicating no independent scientific leadership established yet."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7be9590a-fd94-4ace-96d5-85cba49a17f1', 'c29e52fe-6c06-4e43-92f8-f70446877cad', 'nsclc', 'Kurtis D. Davies is an Emerging Leader in NSCLC research based at the University of Colorado Anschutz Medical Campus, now 15 years into his career. The strongest signal is network expansion. His collaborator count grew from 34 in 2016–2020 to 100 in 2021–2025, nearly tripling in raw terms. Publication output increased modestly, from 7 papers in 2016–2020 to 9 in 2021–2025, while senior-author share has been receding in the more recent window. A transition back into a dominant senior-authorship role would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:47.96802+00', 'Collaborator network nearly tripled, from 34 to 100, signaling rapid expansion of scientific connectivity in NSCLC.', 'Engage around the expanding collaborator network to understand new institutional partnerships and emerging NSCLC research directions.', 'early', '{"Senior-author share is receding and citation volume declined by 248, suggesting output influence has not yet matched network growth."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7c11f62b-3f92-4752-9fc5-47ac4eb7f557', 'e651c920-07a7-4dc9-83dc-dc16c5024ec8', 'nsclc', 'Alessandra Bulotta is a Network Accelerator in NSCLC, ranked at the 75.9th percentile globally (rank 397) with a composite driven primarily by network expansion rather than scientific output. The strongest signal is network momentum, which sits at the 92nd percentile. Collaborator count grew nearly six-fold, from 30 to 174 individuals across the two periods, reflecting a rapid broadening of her collaborative footprint at IRCCS Ospedale San Raffaele. Publication output increased from 7 to 18 papers, but scientific momentum remains at the 43rd percentile, with citation volume declining by 104 and senior-author share holding at zero across both periods. First evidence of a senior-authored publication would mark a meaningful inflection in the scientific dimension of this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:07:29.553803+00', 'Collaborator network expanded nearly six-fold, from 30 to 174, placing network momentum at the 92nd percentile.', 'Engage through her broad collaborator network and monitor for transition into senior authorship as a relationship-deepening trigger.', 'early', '{"Senior-author share is zero across both periods; output growth may reflect collaborative participation rather than independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7e72d0ae-3031-4909-bb73-c9d51325d8a4', 'faefe4a3-e72c-4097-87f7-f4fcaa68c497', 'nsclc', 'Marissa S. Mattar is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, with 10 years of career experience. She has maintained a consistent publication presence, contributing 6 papers from 2016–2020 and 5 papers from 2021–2025, with no net change in velocity. The defining feature of the profile is the contraction in collaborative network. Her collaborator count declined from 80 in 2016–2020 to 60 in 2021–2025, alongside a reduction in citation volume growth of 334. Authorship has not yet moved into senior-authored output. A first senior-authored publication would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:01.637655+00', 'Sustained publication output across both windows at an institution of MSK''s caliber signals continued active engagement in NSCLC research.', 'Prioritize early relationship-building now, monitoring specifically for a first senior-authored publication as the key inflection signal.', 'early', '{"No senior-authored output yet, and a declining collaborator network and negative citation growth warrant close monitoring before deeper investment."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7e73a438-ecd1-4f19-8440-ec1ccce65adf', '8300b9bd-2fc5-436e-af99-05bff4ffd8ac', 'nsclc', 'Afsheen N. Iqbal is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, approximately 10 years into an active research career. The defining feature of the profile is network expansion. Collaborator count grew from 48 in 2016–2020 to 104 in 2021–2025, more than doubling in raw terms across the two windows. Publication output held steady, moving from 5 papers in 2016–2020 to 6 in 2021–2025, while senior-authored output has not yet appeared. A transition into senior or last authorship would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:54.963313+00', 'Collaborator network more than doubled, from 48 to 104, signaling rapidly expanding scientific connectivity.', 'Engage now around the expanding collaborator network while monitoring for first senior-authored publication.', 'early', '{"No senior-authored output yet; citation volume declined, suggesting influence has not yet matched network growth."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7edf3f3e-4d01-44fc-a7ec-d291d45abb64', '82826ae4-743d-4d6b-a5ed-a7b126ffe83b', 'nsclc', 'Brett W. Carter is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 15 years of career experience. Publication output grew from 12 papers (2016–2020) to 14 papers (2021–2025), a modest but steady increase. The strongest signal is network expansion. Collaborator count grew from 152 (2016–2020) to 177 (2021–2025), reflecting broadening engagement across the field. Senior-authored output has not yet appeared in the record. A transition into senior or last authorship would represent the next meaningful milestone in this profile''s development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:32.352649+00', 'Collaborator network expanded from 152 to 177, signaling broadening field engagement across both windows.', 'Engage now to build early relationship ahead of an anticipated transition into senior authorship roles.', 'early', '{"No senior-authored output has been recorded yet, limiting evidence of independent scientific leadership in NSCLC."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7f2111c7-119e-4cd7-a060-e021b4166b44', '495ff34d-5b45-43e2-89fc-2503aa6bf58c', 'nsclc', 'Sharyn I. Katz is an Emerging Leader in NSCLC with 11 years of career experience based at the University of Pennsylvania. She maintained a consistent publication presence, producing 15 papers from 2016–2020 and 14 from 2021–2025. The defining feature of the profile is network expansion. Her collaborator base more than doubled, growing from 83 individuals in 2016–2020 to 171 in 2021–2025, a growth of 88 additional collaborators. Senior-author share has been receding in the recent window. A transition back into senior authorship on NSCLC-focused work would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:48.858624+00', 'Collaborator network more than doubled, from 83 to 171, signaling rapidly broadening scientific connectivity.', 'Engage now around her expanding collaborator network to establish presence before peer relationships solidify further.', 'early', '{"Senior-author share is receding and citation volume declined, raising questions about independent scientific output consolidation."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7f236a4c-2730-4a35-b404-09ce825cd35b', '37a124d0-6425-40e3-9e95-a920e306c32f', 'nsclc', 'Whitney S. Brandt is an Emerging Leader in NSCLC based at Washington University in St. Louis, four years into an active research career. The strongest signal is publication output. Output grew more than twofold, from 6 papers (2016–2020) to 13 papers (2021–2025), while the collaborator network expanded more than threefold, from 38 to 127 individuals across the same windows. Authorship to date reflects no senior-authored output yet, indicating Brandt remains in a contributor rather than directing role. A first senior-authored publication would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:21.968025+00', 'Collaborator network more than tripled, from 38 to 127, signaling rapid integration into the NSCLC research community.', 'Engage now around the growing collaborator network to establish presence ahead of a potential senior authorship transition.', 'early', '{"No senior-authored output yet and citation volume growth is negative, suggesting influence has not yet consolidated despite expanding activity."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('7fa2b392-6f8f-4a32-b7d9-f968f1c52b87', 'f223feee-4fbf-4592-97cc-6364c2c9fcd2', 'nsclc', 'Saumil Gandhi is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center, eight years into his career. The strongest signal is publication output. His output nearly tripled, growing from 11 papers (Aug 2016 – Jul 2021) to 31 papers (Aug 2021 – Jul 2026), accompanied by a citation volume increase of 1,091 across the same comparison. His collaborator network expanded from 62 to 215 individuals across those two windows, reflecting a markedly broader scientific footprint. A transition into consistent senior authorship across the recent window would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:05.055849+00', 'Citation volume surged by 1,091 alongside a near-tripling of publication output in the recent five-year window.', 'Monitor for transition into senior authorship as a trigger for deeper scientific dialogue and relationship-building.', 'moderate', '{"Senior-author share declined in the recent window (Aug 2021 – Jul 2026) relative to the earlier window, suggesting continued mid-author positioning."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('80230e14-38df-4734-9b52-e22e13da11f8', '978300dc-6e6b-41bd-ac53-61fce7bd9d0c', 'nsclc', 'Anna Minchom is an Emerging Leader in NSCLC, ranked 71st globally with a Rising Star composite percentile of 95.7. Publication output nearly tripled, from 8 papers (2016–2020) to 22 (2021–2025), while citation volume grew by 388 over the same period. The strongest signal is network momentum, which sits at the 90th percentile. Her collaborator base expanded nearly fivefold, from 39 to 190 individuals, indicating rapid integration into broader NSCLC research communities. First evidence of a senior-authorship credit would mark a meaningful inflection in her independent scientific standing at the Royal Marsden.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:03:35.203635+00', 'Collaborator network expanded nearly fivefold, from 39 to 190, driving a 90th-percentile network momentum score.', 'Monitor for first senior-authorship credit and engage proactively around her expanding 190-collaborator NSCLC network.', 'high', '{"Senior-author share remains at zero across both periods, indicating all output is currently attributed to non-lead roles."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('80f31aec-dd89-4456-9a1b-e779ac07e10a', '4cb1bad6-ab44-4473-a563-253ae66be107', 'nsclc', 'Catherine B. Meador is a rising Lung Cancer investigator at Massachusetts General Hospital whose research output has grown threefold, from 5 publications (Aug 2016–Jul 2021) to 15 publications (Aug 2021–Jul 2026). The strongest signal is her network expansion. Collaborator count grew from 34 (Aug 2016–Jul 2021) to 137 (Aug 2021–Jul 2026), an increase of more than fourfold in raw count. Citation volume added 98 citations across the same comparison, and senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021). A sustained pattern of senior-authored publications in the lung cancer space would represent the next meaningful milestone in her independent research profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:46.553466+00', 'Collaborator count surged from 34 to 137, alongside a threefold rise in publications.', 'Engage now around her expanding collaborator network and emerging senior authorship to build an early relationship.', 'moderate', '{"The collaborator count expansion is striking and warrants monitoring to confirm depth of engagement rather than broad but shallow co-authorship."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('81e48b4b-6331-4a56-8a74-bc9c1548e627', '44cae309-ef95-4c7e-8761-2d1d7d8b6a43', 'nsclc', 'Gabriele Minuti is an Emerging Leader in NSCLC based at Azienda Unità Sanitaria Locale Della Romagna, ranked 234th globally with a Rising Star composite percentile of 85.8. Publication output increased more than five-fold, from 5 papers (2016–2020) to 26 papers (2021–2025), while his collaborator network expanded nearly four-fold, from 91 to 359 individuals across the same periods. Network visibility (84th percentile) and scientific visibility (81st percentile) confirm that this growing output is reaching a broad audience. The strongest signal is network momentum, which sits at the 76th percentile, underpinned by that 268-collaborator absolute expansion. A transition into a formal senior-author role on a multi-center NSCLC study would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:54:45.561848+00', 'Collaborator network grew nearly four-fold, from 91 to 359, signaling rapid community integration.', 'Engage now around his expanding collaborator network; monitor closely for first senior-author publication as an inflection point.', 'moderate', '{"Senior-author share remains at zero across both periods, and citation volume growth is negative at -396."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('852ad61c-e9db-4f40-97bf-495ec4bfc84c', '543fa1f6-f1d8-4edd-9577-8f8cf6600b3c', 'nsclc', 'Yu Yao is an Emerging Leader in NSCLC based at the First Affiliated Hospital of Xi''an Jiaotong University, with 15 years of career experience and a Rising Star composite percentile of 97.9, ranking 35th globally. Publication output increased more than five-fold, from 7 to 38 papers across the two periods, accompanied by a citation volume growth of +1,754. The strongest signal is network visibility. Network Visibility sits at the 99th percentile, supported by a collaborator base that grew nearly four-fold, from 116 to 432 individuals between 2016–2020 and 2021–2025. A transition into consistent senior authorship would represent the next meaningful milestone for this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:59:47.956622+00', 'Collaborator network expanded nearly four-fold to 432, driving a 99th-percentile network visibility score.', 'Engage now around the expanding collaborator network while monitoring closely for first senior-author publications.', 'high', '{"Senior-author share remains at zero across both periods, meaning independent scientific ownership is not yet established."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('855ce2f7-562d-4657-a3eb-6812da7bf130', '22a4d97f-f60c-4fcd-8274-b9b64804f80e', 'nsclc', 'Vincenzo Sforza is an Emerging Leader in NSCLC based at Istituto Nazionale Tumori IRCCS ''Fondazione G. Pascale,'' ranked 499th globally with a Rising Star composite percentile of 69.7. Publication output doubled from 6 papers (2016–2020) to 12 papers (2021–2025), while citation volume grew by 156 over the same period. His collaborator network expanded from 114 to 218 individuals, reflecting broad and deepening scientific connectivity. Senior-author share remains at zero across both periods, indicating he is still operating primarily as a contributing rather than directing author. A transition into a first senior-authored publication would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:12:50.399906+00', 'Collaborator network doubled to 218 and citations grew by 156, signaling rapid scientific integration.', 'Monitor for first senior-authored publication as a trigger for proactive relationship-building and scientific dialogue.', 'early', '{"Senior-author share is zero across both periods; all output reflects contributing authorship, limiting independent scientific identity assessment."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('870f698d-d7f8-4ee4-b6a2-77d963df5ab7', 'f0d590b8-b45b-4163-a0c5-07e28306bd5f', 'nsclc', 'Pradnya D. Patil is a rising Lung Cancer investigator at Cleveland Clinic whose profile is defined by a rapid expansion of collaborative reach. The strongest signal is network growth. Her collaborator count grew more than three-fold, from 47 (Aug 2016 – Jul 2021) to 163 (Aug 2021 – Jul 2026). Publication output held steady at 11 papers (Aug 2016 – Jul 2021) and 10 papers (Aug 2021 – Jul 2026), while senior-authored work appears in the recent window but not the early window — a meaningful shift in scientific independence. A transition into consistent senior authorship on high-impact Lung Cancer manuscripts would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:55.617527+00', 'Collaborator count expanded more than three-fold, from 47 to 163, across the two most recent five-year windows.', 'Engage now around her expanding collaborator network to establish early relationships before visibility broadens further.', 'early', '{"Citation volume declined by 473 between the two windows, tempering the otherwise strong network and authorship signals."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('87456138-e9a0-4ac1-916c-7636e95efee4', '9c074866-1421-408b-ae32-9bc24bc5f01a', 'nsclc', 'Dongqing Lv is an Emerging Leader in NSCLC based at Wenzhou Medical University, with 8 years in the field and a Rising Star composite percentile of 98.6, ranking 24th globally. Publication output increased more than eight-fold, from 6 to 49 papers across the two periods, accompanied by a citation volume growth of +1,777. The strongest signal is network momentum, which sits at the 97th percentile. Collaborator count expanded from 26 to 734, a more than 28-fold increase in a single period. First evidence of a transition into senior authorship would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:39:43.280412+00', 'Collaborator network expanded 28-fold, from 26 to 734, driving a 97th-percentile network momentum score.', 'Monitor for first senior-authored publication as the trigger point for proactive direct engagement.', 'high', '{"Senior-author share remains at 0 across both periods, indicating Lv has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('87cb1c2f-fb64-4f20-847d-a8de7827211e', '2ab0bb27-32f9-4523-a491-2f3f8e2a5b84', 'nsclc', 'Erin L. Schenk is an Emerging Leader in NSCLC at the University of Colorado Anschutz Medical Campus, now seven years into her career. The strongest signal is publication output. She doubled her published work from 9 papers (2016–2020) to 18 papers (2021–2025), while her collaborator network expanded from 60 to 88 individuals across the same windows. Authorship is moving toward senior positions, a meaningful structural shift for a researcher at this career stage. A first appearance as senior author on an NSCLC-focused manuscript would represent the next milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:19.508583+00', 'Publication output doubled to 18 papers (2021–2025) while her collaborator network grew to 88.', 'Engage now ahead of anticipated senior authorship transition to establish early relationship before influence consolidates.', 'early', '{"Citation volume declined by 963 across windows, suggesting recent papers have not yet accumulated broad field uptake."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('88a4d5fb-2977-4a78-b992-84bd8337bc04', 'baa2cebf-2619-46f6-86fe-f7a7377c1fcd', 'nsclc', 'Aparna Hegde is an Emerging Leader in NSCLC at the University of Alabama at Birmingham, now 10 years into her career. The strongest signal is network expansion. Her collaborator count grew from 27 in 2016–2020 to 74 in 2021–2025, nearly a three-fold increase in raw terms. Publication output held steady at 5 papers across both windows, while citation volume grew by 1,505, indicating that existing work is gaining sustained downstream attention. All output to date reflects non-senior authorship positions. A transition into senior-authored publications would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:42.85403+00', 'Collaborator network nearly tripled from 27 to 74, alongside citation volume growth of 1,505.', 'Engage now around the expanding collaborator network and monitor closely for first senior-authored NSCLC publication.', 'early', '{"No senior-authored output yet; independent scientific voice in NSCLC remains unestablished across both publication windows."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('8c20e8da-5118-4a99-9646-e2cbd40c3a6b', '07a06ad9-0d67-47d9-bab9-f1b1befe705b', 'nsclc', 'Dr. Ramin Salehi-Rad is a rising Lung Cancer investigator at UCLA whose research output has grown meaningfully across consecutive five-year windows. Publication count increased from 6 (Aug 2016–Jul 2021) to 10 (Aug 2021–Jul 2026), while his collaborator network expanded from 35 to 51 over the same periods. The strongest signal is authorship positioning. Senior-authored work appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window, indicating a shift toward independent scientific leadership. First sustained senior-authored output in high-impact Lung Cancer journals would mark a meaningful inflection in his standing as an independent voice in the field.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:38.126101+00', 'Senior-authored output emerged in the recent window after being absent in the prior five-year period.', 'Engage now around emerging senior authorship and expanding collaborator network before independent research agenda fully consolidates.', 'early', '{"Citation volume declined by 336 between windows, tempering the significance of increased publication and collaborator counts."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('8d6f438c-1c1d-4eab-81b6-d779098e7cdb', 'b7eefc1d-53c4-4962-baf5-afbe8f6daf30', 'nsclc', 'Richard D. Hall is a rising Lung Cancer investigator at the University of Virginia whose profile is defined by a dramatic expansion of collaborative reach. The strongest signal is network growth: his collaborator count increased more than six-fold, from 27 (Aug 2016–Jul 2021) to 179 (Aug 2021–Jul 2026). Publication volume held steady at 6 papers across both windows, while citation volume grew by 213 over the same period, suggesting that existing work is gaining broader recognition. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but not the early window (Aug 2016–Jul 2021), marking a meaningful shift in his role within research teams. A sustained pattern of senior-authored publications in the coming window would represent the next milestone in his development.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:53.95534+00', 'Collaborator network expanded more than six-fold, from 27 to 179, between Aug 2016–Jul 2021 and Aug 2021–Jul 2026.', 'Engage now around his expanding collaborator network to establish presence before senior-authored output accelerates.', 'early', '{"Publication volume has not grown across the two windows, which may limit near-term visibility if network activity does not convert to output."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('8eed6da8-6606-4856-9419-ea96d065e62e', '5d13d87b-d733-4fcc-a4a6-9ec06dd1014e', 'nsclc', 'B. Leticia Rodriguez is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 9 years of career activity. The strongest signal is publication output growth. She produced 7 papers from 2016–2020 and 11 from 2021–2025, reflecting a meaningful increase in research productivity. Her collaborator network shifted from 84 individuals in 2016–2020 to 63 in 2021–2025, suggesting a consolidation toward a more focused set of working relationships. Senior-authored output has not yet appeared in the record. A first senior-authored publication would mark a meaningful inflection in her independent scientific standing.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:19:08.142035+00', 'Publication output grew from 7 to 11 papers across consecutive five-year windows, signaling increasing research productivity.', 'Early relationship-building now, with close monitoring for a first senior-authored NSCLC publication as the key inflection trigger.', 'early', '{"No senior-authored output has been recorded yet, limiting evidence of independent scientific leadership at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('8f04a7c3-44b9-4ce0-862b-d6317139d32a', '7508fcd0-bf25-4fb8-a918-7b694fdf4829', 'nsclc', 'C. Patrick is an Emerging Leader in NSCLC at Penn State Milton S. Hershey Medical Center, approximately ten years into an active research career. The strongest signal is network expansion. Collaborator count grew from 36 in 2016–2020 to 116 in 2021–2025, a more than three-fold increase in a single window. Publication output also grew, from 6 papers in 2016–2020 to 10 in 2021–2025, though senior-author share has been receding across that same period. A transition into consistent senior authorship on NSCLC-focused work would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:19:11.655014+00', 'Collaborator network more than tripled, from 36 to 116, signaling rapid integration into the NSCLC research community.', 'Engage now around collaborative research opportunities, monitoring for a shift back toward senior authorship as an inflection signal.', 'early', '{"Senior-author share is receding and citation volume declined by 771, suggesting growing activity has not yet translated into independent scientific influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('8f664ee3-3c65-42bd-9661-985880a9731b', '0e94b966-f20c-4101-aaee-8677f3824344', 'nsclc', 'Petros Christopoulos is a Scientific Accelerator in NSCLC at Heidelberg University with 15 years of career experience and a Rising Star composite percentile of 94.3. The strongest signal is scientific momentum. Publication output increased more than four-fold, from 23 to 107 papers between 2016–2020 and 2021–2025, accompanied by a citation volume growth of +771 and a senior-author publication delta of +16. Scientific visibility and network visibility each sit at the 98th percentile, supported by a collaborator base that grew from 162 to 678. First evidence of independent grant leadership or a named position as principal investigator on a prospective NSCLC trial would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:57:04.24602+00', 'Publication output quadrupled to 107 papers (2021–2025) with citation growth of +771.', 'Monitor for transition into senior authorship; initiate relationship-building now given high visibility but unestablished independent voice.', 'moderate', '{"Senior-author share remains at 0 across both periods, raising questions about independent scientific ownership of this output."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('8ffdec99-3a61-44b8-8640-c322dfe4775a', '96e415c2-3e9c-49cd-a90c-f05c461a7a02', 'nsclc', 'Gene Grant Finley is a rising Lung Cancer investigator at Allegheny Health Network with ten years of career experience. His collaborator network expanded from 35 colleagues (Aug 2016–Jul 2021) to 44 colleagues (Aug 2021–Jul 2026), reflecting broadening engagement across the field. The strongest signal is authorship positioning. Senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), marking a meaningful shift in scientific responsibility. A first senior-authored publication in a high-impact Lung Cancer journal would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:44.478807+00', 'Senior-authored output emerged in Aug 2021–Jul 2026 after being absent in the prior five-year window.', 'Engage now around the emerging senior authorship signal and growing 44-collaborator network to build an early relationship.', 'early', '{"Publication volume declined from 7 (Aug 2016–Jul 2021) to 5 (Aug 2021–Jul 2026), and citation volume also contracted, warranting close monitoring."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('926c1dbb-29bc-4d0c-817c-f32f5710ae76', 'b4ea7814-7bf0-4586-924d-156258ee8f47', 'nsclc', 'Dr. Jennifer W. Carlisle is a rising Lung Cancer investigator at Emory University whose research output has grown substantially across two consecutive five-year windows. Publication volume increased from 8 papers (Aug 2016–Jul 2021) to 20 papers (Aug 2021–Jul 2026), representing a 2.5-fold increase in output. The strongest signal is her collaborator network expansion. That network grew from 39 collaborators (Aug 2016–Jul 2021) to 154 collaborators (Aug 2021–Jul 2026), nearly a fourfold increase, accompanied by citation volume growth of 54 additional citations in the recent window. Senior-authored output appears in the recent window but was absent in the earlier window. A sustained pattern of senior-authored publications in the next review period would represent the next meaningful milestone in her scientific independence.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:23.485703+00', 'Collaborator network nearly quadrupled, from 39 to 154, between Aug 2016–Jul 2021 and Aug 2021–Jul 2026.', 'Engage now around her expanding collaborator network to establish early relationships before her scientific platform fully matures.', 'moderate', '{"Senior authorship is newly emergent in the recent window only; its durability and frequency across future output remain unconfirmed."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('942b939e-45cd-4341-8996-681d4cd1b6fb', 'a2710de3-6655-46b7-8dfb-bea5af2e00c4', 'nsclc', 'Kenneth L. Kehl is a rising Lung Cancer investigator at Dana-Farber Cancer Institute whose profile reflects steady, broadening activity across two consecutive five-year windows. Publication output grew from 10 papers (Aug 2016–Jul 2021) to 12 papers (Aug 2021–Jul 2026), a modest but consistent increase. The strongest signal is network expansion: his collaborator count grew from 117 (Aug 2016–Jul 2021) to 192 (Aug 2021–Jul 2026), a gain of 75 unique collaborators reflecting meaningful cross-institutional reach. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), marking a meaningful shift in his role within the research enterprise. A sustained pattern of senior-authored Lung Cancer publications would represent the next observable milestone in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:05.813609+00', 'Collaborator network expanded from 117 to 192 individuals alongside emerging senior authorship in the recent window.', 'Engage now around his expanding collaborator network and emerging senior authorship to build an early relationship.', 'early', '{"Citation volume declined by 391 between windows, warranting attention to whether recent publications are gaining traction."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('94405880-2c95-4e35-9c40-022598ecf642', 'b7388bda-012a-481a-a1d6-866bbece6203', 'nsclc', 'Ryma Benayed is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, with 11 years of career experience. The strongest signal is network expansion. Her collaborator count grew from 52 (2016–2020) to 106 (2021–2025), more than doubling in raw terms. Publication output increased from 5 (2016–2020) to 7 (2021–2025), a modest but steady gain. Authorship has not yet included senior-authored output. A transition into senior authorship would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:37.470182+00', 'Collaborator network doubled from 52 to 106, signaling rapid integration into the NSCLC research community.', 'Engage now around her expanding collaborator network and monitor closely for first senior-authored publication.', 'early', '{"No senior-authored output yet, and citation volume declined by 342, suggesting limited independent scientific impact to date."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('9688c89b-345f-4698-b3ac-3b78f265bf05', 'a3c3ac11-7199-488b-a41a-992c7774b713', 'nsclc', 'James J. Saller is an Emerging Leader in NSCLC based at Moffitt Cancer Center, now nine years into his career. The strongest signal is citation volume growth. His 5 publications from 2016–2020 accumulated citations that grew by 270 additional citations in the 2021–2025 window, indicating that earlier work is gaining sustained recognition. His collaborator network has remained stable, spanning 51 active collaborators in the most recent period compared with 52 previously, reflecting a consistent but not yet expanding external footprint. Authorship to date has not yet included senior-authored output. A first senior-authored publication would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:54.600934+00', 'Citation volume has grown by 270, signaling that his existing 5-paper output is gaining meaningful recognition.', 'Early relationship-building now, with close monitoring for a first senior-authored NSCLC publication as the key inflection point.', 'early', '{"No senior-authored output yet; without it, independent scientific leadership in NSCLC remains difficult to assess."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('96c41650-0e87-4c38-ad65-4453e66a1919', '98e47765-319b-4b6b-898c-024eb59acb52', 'nsclc', 'Piro Lito is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center whose research output has grown from 11 publications (Aug 2016–Jul 2021) to 16 publications (Aug 2021–Jul 2026). The strongest signal is the authorship shift. Between the two windows, Lito''s senior-author share increased, indicating a move from contributor to intellectual driver of research programs. His collaborator network expanded from 140 (Aug 2016–Jul 2021) to 189 (Aug 2021–Jul 2026), reflecting broadening cross-institutional reach. A transition into consistently anchoring high-impact multi-center trials as principal investigator would represent the next meaningful milestone in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:05.603755+00', 'Rising senior-author share paired with network expansion from 140 to 189 collaborators signals accelerating research independence.', 'Engage around the expanding collaborator network to explore multi-institutional research partnership opportunities early.', 'early', '{"Citation volume declined by 3,466 across the two windows, suggesting recent work has not yet accumulated broad field uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('98579b27-accc-4b62-9359-617b478ee163', '4da84f67-ffb9-489c-bdec-b1d09b24b6a3', 'nsclc', 'Ivana Sullivan is a Balanced Rising Star in NSCLC based at Hospital de Sant Pau, ranked 67th globally with a composite Rising Star percentile of 96. Publication output tripled, from 6 papers in 2016–2020 to 18 in 2021–2025, accompanied by a citation volume growth of +362. The strongest signal is network momentum, which sits at the 92nd percentile. Her collaborator base expanded more than fourfold, from 37 to 152 individuals across the two periods. First evidence of a transition into senior authorship, given a current senior-author share of zero, would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:49:24.716196+00', 'Collaborator network expanded fourfold to 152, driving a 92nd-percentile network momentum score.', 'Monitor for first senior-authored publications as a trigger for deeper scientific partnership conversations.', 'high', '{"Senior-author share remains zero across both periods, limiting independent scientific ownership despite strong output and network growth."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('98b675bc-fbc9-4925-8789-fd9a1a35fc53', '0ab53077-919a-4471-b240-4a633f4804d5', 'nsclc', 'Mohammadhadi Khorrami is an Emerging Leader in NSCLC research based at Case Western Reserve University, now eight years into an independent career. Publication output grew modestly from 5 papers (2016–2020) to 6 papers (2021–2025), while the collaborator network held steady at 24 and 23 researchers across the same respective windows. The defining feature of the profile is citation volume. That figure declined by 508 citations in the more recent window, a contraction worth monitoring alongside the stable output count. No senior-authored publications have appeared to date, meaning the authorship direction remains early-stage. First evidence of a senior-authored paper in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:44.182+00', 'Sustained publication output across both windows signals continued active engagement in NSCLC research.', 'Early relationship-building now positions the MSL ahead of a potential transition into senior authorship.', 'early', '{"Citation volume declined by 508 in the recent window, and no senior-authored output has emerged yet, limiting demonstrated independent influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('9a6415a8-93d9-4177-9cfa-98348f9a5e71', '5de9f6c8-6213-4e49-bea9-09e4baeb3b50', 'nsclc', 'Christine Ciunci is an Emerging Leader in NSCLC based at the University of Pennsylvania, now 11 years into her career. The strongest signal is publication output growth. She produced 10 papers from 2016 to 2020 and 17 from 2021 to 2025, reflecting a meaningful step up in research productivity. Her collaborator network expanded from 53 to 91 individuals across the same windows, indicating broadening scientific engagement. She has not yet produced senior-authored output. A transition into a first senior-authored publication would represent the next meaningful milestone in her scientific development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:06.313483+00', 'Publication output grew from 10 to 17 papers alongside a collaborator network expanding from 53 to 91.', 'Initiate early relationship-building now and monitor for first senior-authored NSCLC publication as a key inflection point.', 'early', '{"No senior-authored output has emerged yet, limiting evidence of independent scientific leadership at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('9a6d2bca-8c7f-4c74-a480-5a94b2b04d78', '195ca53a-6d89-4d75-a2c1-f1d7246999ff', 'nsclc', 'Carminia Maria Della Corte is an Emerging Leader in NSCLC with a Rising Star composite percentile of 70.0 (global rank 493), driven predominantly by strong visibility signals. Scientific Visibility and Network Visibility both score at the 82nd–83rd percentile, reflecting meaningful recognition within the field. Publication output grew from 16 to 20 papers across consecutive five-year periods, while her collaborator network expanded nearly threefold, from 77 to 221 individuals. Notably, senior-author share remains at zero across both periods, indicating she is still operating in a collaborative rather than independent-lead capacity. First evidence of a senior-authored publication in NSCLC would mark a meaningful inflection in her independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:08:53.093879+00', 'Collaborator network expanded nearly threefold, from 77 to 221, signaling rapid network integration.', 'Engage now around her expanding collaborator network; monitor for first senior-authored NSCLC publication as a relationship deepening trigger.', 'early', '{"Senior-author share is zero across both periods; all output reflects collaborative rather than independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('9b475cca-a1a8-47ca-99a9-9263cbec419e', 'acb45857-b122-42bd-a550-ca5758475262', 'nsclc', 'Lynne D. Berry is an Emerging Leader in NSCLC at Vanderbilt University, with 13 years of career experience and a publication record of 6 papers from 2016–2020 followed by 5 papers from 2021–2025. The defining feature of the profile is network breadth. Collaborator count reached 49 in the 2016–2020 window, then contracted to 40 in 2021–2025, suggesting a consolidation phase rather than continued expansion. No senior-authored output has appeared in either window, and citation volume declined by 955 across periods. A first senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:58.868439+00', 'A broad collaborator base of 49 peers in the prior window signals established scientific connectivity in NSCLC.', 'Early relationship-building now positions the MSL ahead of a potential transition into senior authorship.', 'early', '{"No senior-authored output in either window and a citation volume decline of 955 suggest limited independent scientific visibility to date."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('9b70e121-b4bf-4aff-a1ec-4ef25d06c2e0', '3be13ab2-bb51-4d41-a89c-037e095b1e73', 'nsclc', 'Jieling Miao is an Emerging Leader in NSCLC research based at Fred Hutch Cancer Center, now nine years into an independent career. She contributed 7 publications from 2016–2020 and 5 from 2021–2025, maintaining a steady output across both windows. Her collaborator network has remained similarly stable, spanning 52 individuals in the earlier window and 50 in the more recent one. The defining feature of the profile is authorship positioning. No senior-authored output has appeared to date, marking this as the clearest next developmental threshold. A transition into senior authorship would represent the next meaningful milestone in her scientific evolution.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:49.30311+00', 'Sustained publication output across two five-year windows signals consistent engagement in active NSCLC research.', 'Early relationship-building now positions the MSL ahead of a potential transition into senior authorship roles.', 'early', '{"No senior-authored output yet and a citation volume decline of 326 suggest limited independent scientific visibility at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('9db1241c-fc83-442f-8387-7e783bc55389', 'ed40b96f-7f4c-44af-a9cf-d163f42bcc1d', 'nsclc', 'Angel Qin is an Emerging Leader in NSCLC at the University of Michigan, now ten years into an independent career. Publication output grew from 11 papers (2016–2020) to 14 papers (2021–2025), while the defining feature of the profile is network expansion. The collaborator base grew more than fourfold, from 38 to 173 individuals across the same windows, accompanied by a citation volume increase of 1,217. Senior-author share has remained steady throughout, reflecting consistent scientific ownership rather than a shift in role. A transition into first or last authorship on a multicenter NSCLC trial would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:43.353438+00', 'A fourfold collaborator expansion, from 38 to 173, signals rapidly broadening scientific influence in NSCLC.', 'Engage around the expanding collaborator network to identify emerging NSCLC research partnerships and multicenter study opportunities.', 'early', '{"Publication volume growth is modest at three additional papers; the profile is currently driven almost entirely by network expansion rather than output volume."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('9e604a72-63c6-4953-8882-146aeb421779', '8cc96e78-171b-4530-9b2a-cad026c308b3', 'nsclc', 'Quynh-Nhu Nguyen is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 15 years of career experience. The strongest signal is publication output. Publications tripled, from 5 papers (2016–2020) to 15 papers (2021–2025), while citation volume grew by 107 citations across the same shift. Collaborator reach expanded substantially as well, from 47 collaborators (2016–2020) to 115 (2021–2025), reflecting a broadening scientific network. Senior-authored output has not yet appeared. A first senior-authored publication would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:47.495647+00', 'Publication output tripled to 15 papers and citation volume grew by 107 in the most recent five-year window.', 'Initiate early relationship-building now and monitor closely for a first senior-authored NSCLC publication as the key inflection signal.', 'early', '{"No senior-authored output has emerged yet, limiting evidence of independent scientific leadership within the NSCLC field."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a093b0a8-8e37-4835-bd8b-4235e59bffd6', '0c36b3ea-8667-47f2-9482-a99b990f85c8', 'nsclc', 'Marco Tagliamento is an Emerging Leader in NSCLC based at Ospedale Policlinico San Martino, currently ranked 343rd globally with a Rising Star composite percentile of 79.2. His visibility profile is the dominant signal, reaching the 88th percentile overall, underpinned by a network visibility score at the 91st percentile and scientific visibility at the 86th percentile. The strongest signal is network expansion. Collaborator count grew nearly six-fold, from 47 in 2016–2020 to 267 in 2021–2025, while publication output increased from 17 to 31 papers across the same periods. A transition into senior authorship on any NSCLC publication would represent the next meaningful milestone for this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:49:39.994371+00', 'Collaborator network expanded nearly six-fold, from 47 to 267, driving 91st-percentile network visibility.', 'Engage now around collaborative network opportunities; monitor closely for first senior-authored NSCLC publication as key inflection.', 'early', '{"Senior-author share remains at zero across both periods, limiting independent scientific attribution despite strong network growth."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a11fe462-5b55-4b3f-8b8f-4369814e6fb4', '00749591-ab16-4320-9d73-7e2db02d9e76', 'nsclc', 'Shinji Kohsaka is a Scientific Accelerator in NSCLC, ranked 330th globally with a Rising Star composite percentile of 80. The strongest signal is scientific momentum, which sits at the 92nd percentile. Publication output nearly doubled from 10 papers (2016–2020) to 19 papers (2021–2025), while his collaborator network expanded from 70 to 104 unique collaborators. Notably, senior-author share remains at zero across both periods, which tempers the interpretation of output growth. First evidence of a senior-author credit on an NSCLC publication would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:02:49.106819+00', 'Publication output nearly doubled to 19 papers (2021–2025), driving a 92nd-percentile scientific momentum score.', 'Monitor for first senior authorship; initiate early relationship-building given current contributing-author stage and growing network.', 'early', '{"Senior-author share is zero across both periods, suggesting Kohsaka remains in a contributing rather than directing research role."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a2f1e517-feae-472b-b09f-d64a165da07c', '85455e0a-7f39-4665-8823-0486a756ae66', 'nsclc', 'John T. Poirier is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, with 14 years of career experience. The defining feature of the profile is the contraction in collaborative network. Collaborator count declined from 216 in 2016–2020 to 136 in 2021–2025, a reduction of 80 connections, suggesting a deliberate narrowing toward focused research partnerships. Publication output moved from 18 papers in 2016–2020 to 9 in 2021–2025, accompanied by citation volume growth of 4,350, indicating that a smaller body of recent work is generating meaningful downstream engagement. Authorship has not yet reached senior-authored output. A first senior-authored publication would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:36.685896+00', 'Citation volume grew by 4,350 despite a halved publication count, signaling concentrated research impact.', 'Monitor for transition into senior authorship as the primary trigger for deeper MSL relationship-building.', 'early', '{"No senior-authored output yet after 14 career years; authorship ceiling may limit perceived independent scientific standing."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a3f151eb-4332-42e6-beeb-9b46a7facda7', '43d805fa-b50c-4473-bbe1-5892b9b6941d', 'nsclc', 'Magda Bahcall is an Emerging Leader in NSCLC based at Dana-Farber Cancer Institute, with 11 years of career experience. She contributed 9 publications between 2016 and 2020, followed by 5 publications between 2021 and 2025, reflecting a measured but sustained presence in the literature. Her collaborator network remained broad across both windows, spanning 95 collaborators from 2016 to 2020 and 90 from 2021 to 2025, indicating durable peer connectivity. Authorship has not yet extended to senior-authored output, representing an open directional shift in her scientific role. A first senior-authored publication would mark a meaningful inflection in her standing within the NSCLC research community.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:30.047369+00', 'A broad, stable collaborator network of 90 peers signals sustained scientific connectivity in NSCLC.', 'Early relationship-building now, monitoring closely for a first senior-authored NSCLC publication as the key trigger.', 'early', '{"No senior-authored output yet, and publication volume declined from 9 to 5 papers across the two windows."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a426d3c2-9733-40ae-bce4-c955b1aa3c14', '659e0892-0795-4976-9938-8e43e4ea473b', 'nsclc', 'Dr. Aditi Singh is a rising Lung Cancer investigator at the University of Pennsylvania whose research output has grown markedly across two consecutive five-year windows. The strongest signal is publication volume. Output increased nearly threefold, from 9 papers (Aug 2016–Jul 2021) to 25 papers (Aug 2021–Jul 2026), accompanied by a citation volume growth of 2,568 over the same span. Her collaborator network expanded from 47 to 150 individuals across those same windows, reflecting broad and deepening scientific engagement. Senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021). A sustained pattern of senior-authored publications in high-impact Lung Cancer venues would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:45.764711+00', 'Citation volume grew by 2,568 alongside a near-threefold rise in publications from Aug 2021–Jul 2026.', 'Engage now around her expanding collaborator network and emerging senior authorship to build an early relationship.', 'moderate', '{"Senior authorship is newly emergent in the recent window; consistency and venue prominence of that output remain unestablished."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a7dda541-4152-4323-8428-cfa0f173f861', '5331be58-910a-43f6-accc-6541f330037d', 'nsclc', 'Fernando C. Santini is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, now nine years into his career. The defining feature of the profile is network expansion. His active collaborator base grew from 25 individuals in 2016–2020 to 67 in 2021–2025, nearly a three-fold increase in raw count. Publication output across the same windows moved from 8 papers to 6, while senior-author share has been receding, suggesting energy is currently directed outward rather than toward independent scholarly production. A transition back into senior-authored original research would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:31.140297+00', 'Collaborator network nearly tripled, from 25 to 67, signaling rapid expansion of scientific connections.', 'Engage around the expanding collaborator network to understand emerging multi-institutional NSCLC research relationships.', 'early', '{"Receding senior-author share and declining publication volume suggest independent scientific voice is not yet consolidating."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a7e20b14-938d-4eb1-bca9-a338bd037166', '41a0f1a4-cf22-4738-8663-dafadc7e6ae0', 'nsclc', 'Imayavaramban Lakshmanan is a rising Lung Cancer investigator at the University of Nebraska Medical Center, now 13 years into an active research career. The strongest signal is publication output growth. He authored 5 papers in the Lung Cancer space from Aug 2016 – Jul 2021, increasing to 7 papers from Aug 2021 – Jul 2026, while his collaborator network held steady at 27 across both windows. Notably, senior-authored output appears in the Aug 2021 – Jul 2026 window but was absent in the Aug 2016 – Jul 2021 window, marking a meaningful shift in research independence. First evidence of sustained senior-authored publication output across consecutive cycles would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:59.264292+00', 'Senior-authored output emerged in the recent window, signaling a shift toward independent research leadership.', 'Early relationship-building now, ahead of potential senior-authored output consolidating into a defined research program.', 'early', '{"Citation volume declined by 185 between windows, tempering the significance of modest publication count growth."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a89e81fe-4eb3-4d80-9a1c-6c950b1eaa9f', '0015ed55-de71-4ae4-982b-76ddb505850e', 'nsclc', 'Gaia Piperno is an Emerging Leader in NSCLC based at the European Institute of Oncology, with 15 years of career experience and a Rising Star composite percentile of 74.5 (global rank 420). Publication output tripled, from 5 papers (2016–2020) to 15 (2021–2025), accompanied by a citation volume growth of +36. The strongest signal is network momentum, which sits at the 83rd percentile. Collaborator count expanded threefold, from 39 to 117 individuals across the two periods. A transition into senior authorship on any forthcoming NSCLC manuscript would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:08:59.984155+00', 'Collaborator network tripled from 39 to 117, driving an 83rd-percentile network momentum score.', 'Engage around her expanding collaborator network; monitor closely for first senior-authored NSCLC publication.', 'early', '{"Senior-author share remains at zero across both periods, indicating Piperno has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a8b4c603-0914-4967-ba5d-57e522a34416', 'c12b3958-51d9-4fac-bf34-03ebc911ea56', 'nsclc', 'Erin M. Corsini is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 15 years of career experience. The strongest signal is citation growth. Across the two observation windows, citations grew by 53, while publication output held steady at 10 papers (2016–2020) and 8 papers (2021–2025), and her collaborator network remained stable at 52 across both periods. Authorship has not yet moved into senior-authored output. A transition into first senior-authored publications would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:23.345684+00', 'Citation volume grew by 53 while publication count and network size remained stable.', 'Monitor for transition into senior authorship as the primary trigger for deeper MSL engagement.', 'early', '{"No senior-authored output has emerged yet, limiting evidence of independent scientific leadership within the field."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a8ba8151-08a8-4b66-9fb6-6a2d5e61fd98', '50a20f25-dd62-4fd6-a5df-cfdaae3dfe59', 'nsclc', 'Takahiro Karasaki is an Emerging Leader in NSCLC, ranked 136th globally with a Rising Star composite percentile of 91.8. His publication output nearly doubled across periods, growing from 10 papers (2016–2020) to 19 (2021–2025), while citation volume expanded by 2,164. The strongest signal is network momentum, which sits at the 88th percentile. His collaborator base grew nearly six-fold, from 56 to 331 individuals, reflecting a rapid broadening of scientific connections. A transition into senior authorship, currently at zero across both periods, would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:12:43.585539+00', 'Collaborator network expanded nearly six-fold, from 56 to 331, driving 88th-percentile network momentum.', 'Monitor for first senior-authored publication as a trigger for proactive relationship-building and scientific dialogue.', 'moderate', '{"Senior-author share remains zero across both periods, indicating Karasaki has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('a921257a-d616-4a72-9656-77cbe435ac22', 'd0a21ab1-8cef-4460-83df-2de5caf1bf6e', 'nsclc', 'Lejie Cao is a Scientific Accelerator in NSCLC at the University of Science and Technology of China, ranked 48th globally with a Rising Star composite percentile of 97.1. Publication output increased six-fold, from 5 papers (2016–2020) to 30 papers (2021–2025), accompanied by citation volume growth of +1,981. The strongest signal is network visibility. Network Visibility sits at the 97th percentile, supported by a collaborator base that grew more than three-fold, from 95 to 311 individuals across the same periods. Senior-author share remains at zero across both periods, meaning all output to date reflects a contributor rather than independent investigator role. A transition into first or senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:03:05.607263+00', 'Collaborator network tripled to 311 and citation volume grew +1,981, driving a 97.1 composite percentile.', 'Monitor closely for first senior-authored publication as the trigger for deeper scientific engagement and relationship-building.', 'high', '{"Senior-author share is zero across both periods; all output reflects a non-independent contributor role, limiting standalone scientific influence."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('aa81e32e-c352-4ec1-ae75-5bb331d4a83a', 'a41673d6-e5d5-4b37-b38d-4ffa2193a616', 'nsclc', 'Steven Kao is an emerging clinical voice in non-small cell lung cancer based at Chris O''Brien Lifehouse in Sydney, with approximately 9 years of research activity and 41 career publications that reflect a focused and sustained contribution to the field. His citation trajectory ranks at the 80th percentile across the full NSCLC researcher population, indicating that his work is gaining meaningful traction and reference value among peers well beyond his immediate institution. Most notably, his clinical trial activity places him at the 85th percentile across all career stages in the TA, signalling that he is actively embedded in the trial infrastructure that shapes real-world NSCLC practice.', 'v1.0', 'claude-sonnet-4-6', '2026-06-04 04:33:34.618431+00', 'The combination of high clinical trial activity and accelerating citation uptake — both in the top quintile of the broader NSCLC population — marks this as a point of inflection where Kao''s scientific influence is beginning to outpace his publication volume, making early MSL engagement particularly timely.', 'Given his strong trial participation profile, the MSL would find productive ground in discussing evolving endpoints, patient selection criteria, and biomarker-driven stratification strategies in NSCLC clinical research. His citation growth also suggests his work intersects with areas of active scientific debate, making data-focused conversations around emerging treatment sequencing or resistance mechanisms in NSCLC well-suited to his interests.', 'Signal strength is solid and internally consistent: trial activity and citation trajectory are both high-percentile and mutually reinforcing, even though publication velocity is more modest, suggesting quality and clinical relevance over volume.', NULL::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ac4a5883-a033-430e-8120-d56371b9a6af', 'bbdec13d-bd17-4aba-9e8a-921e96bf6a3c', 'nsclc', 'Luigi Ventura is an Emerging Leader in NSCLC based at the University of Parma, with 10 years of career experience. Publication output more than doubled, from 5 papers (2016–2020) to 12 papers (2021–2025), accompanied by a citation volume growth of +62, reflecting increasing scientific engagement. The strongest signal is network momentum, which ranks at the 81st percentile globally. His collaborator base nearly doubled, expanding from 52 to 99 unique collaborators across the two periods. A transition into senior authorship on NSCLC publications would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:13:41.846129+00', 'Collaborator network nearly doubled to 99, driving an 81st-percentile network momentum score.', 'Engage around his expanding 99-person collaborator network to map emerging NSCLC connections and identify co-engagement opportunities.', 'early', '{"Senior-author share remains at 0 across both periods, indicating Ventura has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ac7d1a45-8ebf-4f44-a3fd-b30d62f2539b', '72bf1413-402f-47d3-9a4c-10eade8701fa', 'nsclc', 'Jeffrey C. Thompson is an Emerging Leader in NSCLC research at the University of Pennsylvania, now ten years into his career. His publication output has remained notably consistent, with 14 papers from 2016–2020 and 13 papers from 2021–2025. The strongest signal is network expansion. His active collaborator count grew from 66 to 85 individuals across the same two windows, reflecting broadening scientific engagement. No senior-authored output has appeared to date. A transition into a first senior-authored publication would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:04.456713+00', 'Collaborator network expanded from 66 to 85 researchers across consecutive five-year windows.', 'Monitor for first senior-authored publication as the key inflection point warranting deeper MSL engagement.', 'early', '{"No senior-authored output has emerged across either window, limiting evidence of independent scientific leadership."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ace2241e-5ec3-41b6-920f-c7f6ec97bbfa', '973dec43-5ff7-4095-8404-3a3898cbd2d6', 'nsclc', 'Xue Wu is a rising Lung Cancer investigator at Genesee Community College with 11 years of career experience. The strongest signal is authorship evolution. Senior-authored output appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window, marking a meaningful shift in scientific independence. Wu produced 41 publications in Aug 2016–Jul 2021 and 28 in Aug 2021–Jul 2026, alongside a collaborator network of 244 and 229 respectively across those same periods. A first high-impact senior-authored publication in a dedicated Lung Cancer journal would represent the next milestone in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:13.279885+00', 'Senior-authored output emerged in Aug 2021–Jul 2026 after being absent in the prior five-year window.', 'Engage now around emerging senior authorship to build early relationship before independent research agenda solidifies.', 'early', '{"Citation volume declined by 1,735 between windows, and publication count also decreased from 41 to 28, tempering the authorship signal."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('afc22f14-ca26-4c3c-9be9-d29673c69689', '39d4dedb-a1b9-469e-b2c6-0286f3323bdf', 'nsclc', 'Ammar Sukari is an Emerging Leader in NSCLC at Wayne State University with 15 years of career experience. The strongest signal is network expansion. His collaborator count grew from 21 (2016–2020) to 78 (2021–2025), a nearly fourfold increase in raw terms. Publication output also grew, from 9 papers (2016–2020) to 14 (2021–2025), though citation volume declined by 162 and senior-author share is receding rather than growing. A transition into sustained senior authorship on NSCLC-focused work would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:37.288969+00', 'Collaborator network expanded nearly fourfold, from 21 to 78, signaling rapid integration into broader NSCLC research communities.', 'Engage around the expanding collaborator network to establish presence before senior authorship and citation impact solidify.', 'early', '{"Senior-author share is receding and citation volume declined by 162, suggesting influence within the network has not yet consolidated."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b022e113-55f3-445d-8e15-880f8885542c', '3ee48dbd-e059-41f1-ad07-f9b640e19ac9', 'nsclc', 'Lizhu Lin is a Balanced Rising Star in NSCLC, ranked 39th globally with a composite percentile of 97.7 across a 10-year career at the First Affiliated Hospital of Guangzhou University of Chinese Medicine. Publication output more than doubled, from 14 papers (2016–2020) to 31 (2021–2025), while citation volume grew by 396, reflecting sustained and accelerating scientific productivity. This profile is characteristic of a Balanced Rising Star: both momentum components (Scientific 86th, Network 87th percentile) and visibility components (Scientific 87th, Network 94th percentile) are uniformly elevated. The strongest network signal is collaborator expansion from 62 to 157 individuals—a 2.5-fold increase—driving a Network Visibility percentile of 94. A transition into consistent multi-paper senior authorship beyond the current senior-author share of 1 would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:58:52.319787+00', 'Collaborator network grew from 62 to 157 individuals, reaching the 94th percentile for Network Visibility.', 'Engage around the expanding 157-person collaborator network to explore multi-institutional NSCLC research partnership opportunities.', 'high', '{"Senior-author share remains at 1 across both periods; independent scientific leadership is not yet reflected in authorship position."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b063d5ec-d6c2-4ba0-808a-d0743b47ea2f', '9ec73935-efae-4d41-bcff-d4b02cc27e54', 'nsclc', 'Lieming Ding is an Emerging Leader in NSCLC based at Betta Pharmaceuticals, China, ranked 34th globally with a Rising Star composite percentile of 98.0. Publication output increased more than 2.6-fold, from 8 papers (2016–2020) to 21 papers (2021–2025), accompanied by a citation volume growth of +163, reflecting sustained and accelerating scientific productivity. The strongest signal is network expansion. Collaborator count grew from 100 to 246 between the two periods, a 2.5-fold increase that drives a Network Visibility percentile of 96. Senior-author share remains at zero across both periods, which contextualizes the output growth. First evidence of a senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:04:05.565183+00', 'Network collaborators surged from 100 to 246, placing Ding at the 96th percentile for network visibility.', 'Monitor for transition into senior authorship as the natural next milestone signaling independent research leadership.', 'high', '{"Senior-author share is zero across both periods; output growth reflects contributing rather than independent scientific leadership currently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b1031057-56bb-4ae9-8338-50fb9715748b', 'b8ea3bfa-f53f-4108-9739-449a636f51ee', 'nsclc', 'Dr. Liza C. Villaruz is a rising Lung Cancer investigator at UPMC Hillman Cancer Center whose research output and collaborative reach have expanded meaningfully across two consecutive five-year windows. Publication output grew from 16 papers (Aug 2016–Jul 2021) to 22 papers (Aug 2021–Jul 2026), while her collaborator network expanded from 130 to 216 individuals across those same periods. The strongest signal is her network growth. That expansion—from 130 to 216 collaborators—represents a 66-person net increase between Aug 2016–Jul 2021 and Aug 2021–Jul 2026, suggesting broadening cross-institutional engagement. Senior-author share held steady across both windows, reflecting consistent independent contribution. A first senior-authored publication in a high-impact Lung Cancer journal would mark a meaningful inflection in her independent scientific voice.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:07.47883+00', 'Collaborator network grew from 130 to 216 between the two five-year windows, signaling rapid cross-institutional expansion.', 'Engage around her expanding collaborator network to explore cross-institutional research partnerships and emerging Lung Cancer initiatives.', 'early', '{"Citation volume declined by 2,759 between the two windows, suggesting recent work has not yet accumulated downstream scientific engagement."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b198633a-79e5-4aa9-a166-6c3cba485ef2', '150756fb-2643-41cc-9851-3889a0dfa6d5', 'nsclc', 'Edwin J. Ostrin is an Emerging Leader in NSCLC research based at The University of Texas MD Anderson Cancer Center, now 11 years into his career. The strongest signal is network expansion. His active collaborator count grew from 55 individuals in 2016–2020 to 102 in 2021–2025, nearly doubling in raw terms and reflecting a broadening scientific footprint across the field. Publication output moved from 8 papers in 2016–2020 to 11 in 2021–2025, while senior-author share has been receding in the more recent window. A transition into a sustained senior-authorship pattern would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:51.713589+00', 'Collaborator network nearly doubled, from 55 to 102, signaling rapid expansion of scientific reach.', 'Engage now around the expanding collaborator network while monitoring for a return to senior authorship.', 'early', '{"Senior-author share is receding and citation volume declined by 402, raising questions about independent scientific influence at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b2017104-3009-48cd-990d-4b76ae4dc3d4', 'c3573e4f-8e13-4671-ad0c-b76301b438cb', 'nsclc', 'Dr. Shadia I. Jalal is a rising Lung Cancer investigator at Indiana University Health with 15 years of career experience. Publication output grew from 11 papers (Aug 2016–Jul 2021) to 13 papers (Aug 2021–Jul 2026), while her collaborator network expanded modestly from 68 (Aug 2016–Jul 2021) to 69 (Aug 2021–Jul 2026). The defining feature of the profile is authorship positioning. Between the two windows, her senior-author share increased, signaling a shift toward independent scientific direction. A transition into a principal investigator role on a prospective lung cancer trial would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:06.951863+00', 'Senior-author share is rising between the two five-year windows, signaling growing independent scientific direction.', 'Engage now around her rising senior-authorship activity to build relationship ahead of potential trial leadership opportunities.', 'early', '{"Citation volume declined by 2,122 between the two windows, suggesting impact breadth has not yet kept pace with output growth."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b2198db3-4ae2-456f-b816-c6a54af5fa1f', '891671d1-f1cf-45a4-9875-8bf377c383fa', 'nsclc', 'Maria Lucia Reale is a Balanced Rising Star in NSCLC, ranked 112nd globally with a composite Rising Star percentile of 93.2. Her publication output increased 3.5-fold, from 6 papers in 2016–2020 to 21 in 2021–2025, accompanied by a citation volume growth of +126, placing her Scientific Momentum at the 86th percentile. Her collaborator network expanded from 56 to 199 individuals across the same periods, a 3.6-fold increase that anchors her Network Momentum equally at the 86th percentile. This profile is characteristic of a Balanced Rising Star, with scientific and network signals reinforcing each other rather than one clearly dominating. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:06:11.127762+00', 'Collaborator network grew 3.6-fold to 199 and publications 3.5-fold to 21 since 2021.', 'Monitor for first senior-authored publication as a concrete trigger for deeper scientific engagement.', 'moderate', '{"Senior-author share remains at 0 across both periods, indicating Reale has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b3b5dd11-fb43-4646-a16b-65cf2b4912e2', 'e9ccd7a1-5cda-46b6-aa12-841fc5d79112', 'nsclc', 'Laura V. Klotz is a Balanced Rising Star in NSCLC at Heidelberg University, ranked 60th globally with a composite percentile of 96.4 across a 9-year career. Publication output increased more than four-fold, from 5 papers (2016–2020) to 23 papers (2021–2025), accompanied by a citation volume growth of +71. The strongest signal is network momentum, which sits at the 93rd percentile. Her collaborator base expanded from 38 to 141 individuals across the two periods, nearly a four-fold increase. Senior-author share remains at zero throughout both periods, a pattern worth monitoring; first evidence of a senior-author credit would mark a meaningful inflection in independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:01:43.85994+00', 'Collaborator network expanded from 38 to 141, nearly four-fold, driving 93rd-percentile network momentum.', 'Monitor for first senior-author publication as the primary trigger for deeper scientific engagement and relationship-building.', 'high', '{"Senior-author share is zero across both periods, suggesting output may still reflect collaborative rather than independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b51ecef8-9d17-4a51-a5c8-cd1481a6175e', '203456e4-3228-4f67-867e-f90a7803e67f', 'nsclc', 'Xiuyu Cai is an Emerging Leader in NSCLC based at Sun Yat-sen University, ranked 61st globally with a Rising Star composite percentile of 96.3. Publication output more than doubled, from 12 papers (2016–2020) to 25 (2021–2025), while citation volume grew by 650, reflecting sustained scientific productivity. The strongest signal is network expansion. Collaborator count increased more than 3.5-fold, from 86 to 302, placing network visibility at the 98th percentile globally. Senior-author share remains at zero across both periods, which warrants monitoring. First evidence of a senior-author credit would mark a meaningful inflection in independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:58:21.480857+00', 'Collaborator network surged 3.5-fold to 302, reaching the 98th percentile for network visibility.', 'Engage now around the expanding collaborator network; monitor closely for first senior-author publication as a relationship deepening trigger.', 'high', '{"Senior-author share is zero across both periods; all output appears in non-senior roles, limiting independent scientific attribution."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b539ca36-5e4c-4de9-80a2-dc8e997e64e1', '7e9959d6-f3ed-4bab-b13e-bd4239f4b742', 'nsclc', 'Vincent Fallet is an Emerging Leader in NSCLC at Sorbonne Université with 12 years of career experience and a Rising Star composite percentile of 81 (global rank 313). Publication output grew from 11 papers (2016–2020) to 16 (2021–2025), while his collaborator network expanded more than three-fold, from 43 to 145 unique collaborators. The strongest signal is network momentum, which sits at the 66th percentile and is the primary driver of his overall scientific momentum score of 81. Citation volume declined by 136, and senior-author share remains at zero across both periods, suggesting output growth has not yet translated into independent scholarly recognition. First evidence of a senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:09:30.409392+00', 'Collaborator network expanded more than three-fold, from 43 to 145, signaling rapid integration into NSCLC research communities.', 'Monitor for transition into senior authorship; early relationship-building now positions MSL ahead of anticipated independence milestone.', 'early', '{"Senior-author share is zero across both periods and citation volume declined by 136, limiting evidence of independent scientific standing."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b57c8672-5c70-4d71-b019-523614af3eaf', 'cf793abf-9c6a-486c-91d6-ef007c84f71e', 'nsclc', 'Ismail M. Meraz is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 14 years of career experience. He has maintained a consistent publication presence, contributing 6 papers from 2016–2020 and 5 papers from 2021–2025. His collaborator network has remained substantive across both windows, engaging 44 collaborators from 2016–2020 and 39 from 2021–2025. No senior-authored output has appeared to date, marking a clear next developmental threshold. A transition into senior or last authorship would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:35.403425+00', 'Sustained publication output across two consecutive five-year windows at a major NCI-designated cancer center signals continued active engagement.', 'Early relationship-building now positions the MSL ahead of a potential transition into senior authorship roles.', 'early', '{"No senior-authored output has emerged across either window, and citation volume declined by 161, suggesting limited downstream impact so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('b86d0c9f-0a2a-466b-b9dd-ea3eacc0f94a', '241fe4fd-aae5-4a0a-99aa-e2026d8db2b5', 'nsclc', 'Aurélie Lagrange is an Emerging Leader in NSCLC based at Centre Georges François Leclerc, with 10 years of career experience and a Rising Star composite percentile of 68.5 (global rank 518). The strongest signal is network momentum, which sits at the 87th percentile. Her collaborator base expanded more than four-fold, from 32 to 144 individuals across the two periods. Publication output doubled from 6 to 12 papers, though citation volume declined by 135 and senior-author share remains at zero across both periods. First evidence of a senior-authored publication would mark a meaningful inflection in her scientific independence.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:57:11.121883+00', 'Collaborator network grew four-fold, from 32 to 144, placing network momentum at the 87th percentile.', 'Engage around her expanding collaborator network now, and monitor closely for a first transition into senior authorship.', 'early', '{"Senior-author share is zero across both periods, and citation volume declined by 135, limiting evidence of independent scientific standing."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('bace574b-c817-4a23-9b9a-854273ebd13d', '740a0ce0-0026-4624-a06b-ea699cf9247b', 'nsclc', 'Brian S. Henick is an Emerging Leader in NSCLC based at Columbia University Irving Medical Center, now nine years into his career. The strongest signal is network expansion. His collaborator count grew from 65 individuals in 2016–2020 to 117 in 2021–2025, nearly doubling in raw terms. Publication output also increased, from 7 papers in 2016–2020 to 11 in 2021–2025, though authorship has not yet extended into senior-authored work. A transition into senior or last authorship on an NSCLC-focused manuscript would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:03.62629+00', 'Collaborator network nearly doubled, from 65 to 117, signaling rapidly expanding scientific connectivity in NSCLC.', 'Engage now around his expanding collaborator network and monitor closely for first senior-authored NSCLC publication.', 'early', '{"No senior-authored output has emerged yet, and citation volume declined by 439, suggesting limited downstream impact to date."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('bb232d90-47e5-433f-9233-8571988b410a', '1ab395ed-1aa4-483f-9f0e-d207f160915d', 'nsclc', 'William P. Levin is an Emerging Leader in NSCLC at the University of Pennsylvania, now 14 years into his career. The strongest signal is publication output growth. He produced 8 papers from 2016 to 2020, rising to 13 papers from 2021 to 2025, while his collaborator network expanded from 44 to 52 individuals across the same windows. Senior-authored output has not yet appeared in the record. A first senior-authored publication in NSCLC would represent the next meaningful milestone in this profile''s development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:09.476142+00', 'Publication output grew from 8 to 13 papers alongside a collaborator network expanding to 52.', 'Early relationship-building now, with active monitoring for a first senior-authored NSCLC publication.', 'early', '{"No senior-authored output has been recorded yet, and citation volume declined by 124 across the most recent window."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('bb893850-e226-49cf-8451-0df388c6b968', '83a6184e-5948-4323-aa4f-6251099991ab', 'nsclc', 'Fabrizio Citarella is an Emerging Leader in NSCLC based at Università Campus Bio-Medico, with 7 years of career activity. Publication output increased more than five-fold, from 5 papers (2016–2020) to 26 papers (2021–2025), accompanied by a citation volume growth of +305. The strongest signal is network visibility. His collaborator network expanded from 94 to 391 individuals across the two periods, placing him at the 93rd percentile for network visibility globally. Scientific visibility ranks at the 82nd percentile, supporting a composite Rising Star percentile of 78.1 (global rank 361). A transition into senior authorship on NSCLC-focused publications would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:41:10.142124+00', 'Collaborator network grew from 94 to 391, reaching the 93rd percentile for network visibility.', 'Engage now around his expanding collaborator network; monitor closely for first senior-authored NSCLC publication.', 'early', '{"Senior-author share remains at zero across both periods, indicating Citarella has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('bbc58adc-4d40-4dce-a6ca-db3702fa6e01', 'c3086edd-1c5f-4aca-97c0-286989902492', 'nsclc', 'Girish S. Shroff is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 15 years of career experience. The strongest signal is publication growth. Output increased threefold, from 5 papers (2016–2020) to 15 papers (2021–2025), while his collaborator network expanded from 28 to 80 individuals across the same windows — nearly a threefold broadening in reach. Authorship has not yet included senior-authored output, and citation volume has not grown in parallel with publication count. A transition into senior authorship would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:41.039725+00', 'Publication output tripled to 15 papers and collaborators nearly tripled to 80 in the most recent five-year window.', 'Initiate early relationship-building now and monitor for first senior-authored publication as a key inflection point.', 'early', '{"No senior-authored output yet, and citation volume has declined despite rising publication count, suggesting limited downstream field uptake so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('bd5cd6db-0d20-4397-a806-1a9adb1bbc65', '0020a328-1ffd-4a87-a820-ff27daacb590', 'nsclc', 'Ben Creelan is an Emerging Leader in NSCLC research based at Moffitt Cancer Center, with 14 years of career experience. He has sustained a meaningful publication presence, producing 21 papers from 2016–2020 and 16 from 2021–2025, while his authorship is moving toward senior positions. His collaborator network remains broad, spanning 169 individuals in 2016–2020 and 154 in 2021–2025, reflecting durable cross-institutional engagement. The defining feature of the profile is citation volume. That figure shifted by -4,571 across windows, a pattern worth monitoring as authorship seniority increases. A first senior-authored publication in a high-impact NSCLC venue would represent the next meaningful milestone.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:36.943807+00', 'Authorship moving toward senior roles signals a pivotal shift in scientific influence within NSCLC.', 'Engage now to build relationship ahead of anticipated first senior-authored NSCLC publications.', 'early', '{"Citation volume declined by 4,571 across windows; senior-authored output has not yet materialized to anchor independent scientific identity."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('bef5558c-f5aa-439d-b875-2f9bdb4aa095', 'f694de74-0c68-458b-a7f0-adcdb8be2b2a', 'nsclc', 'Bin Xu is a Balanced Rising Star in NSCLC at Wuhan University, now ranked 23rd globally with a composite Rising Star percentile of 98.7. Publication output nearly doubled, from 7 papers (2016–2020) to 13 (2021–2025), while citation volume grew by 259, reflecting meaningful scientific acceleration. The strongest signal is network momentum, which sits at the 98th percentile. Collaborator count expanded nearly six-fold, from 27 to 159 individuals across the two periods. Senior-author share remains at zero throughout, a pattern worth monitoring; first evidence of a senior-author credit would mark a meaningful inflection in independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:10:30.970107+00', 'Collaborator network expanded nearly six-fold, from 27 to 159, placing network momentum at the 98th percentile.', 'Monitor for first senior-author publication as the trigger for deeper scientific engagement and relationship-building.', 'high', '{"Senior-author share is zero across both periods, suggesting Xu has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('bf711d6a-7c85-472e-8e16-0a2cc53691cf', 'e1216932-fc8f-470b-b133-97bbcb0dadd0', 'nsclc', 'Sibo Tian is an Emerging Leader in NSCLC at Emory University, now nine years into an academic career marked by measurable network expansion. The strongest signal is publication output. Paper count doubled from 5 (2016–2020) to 10 (2021–2025), while the collaborator network grew from 25 to 48 individuals across the same windows, nearly doubling in reach. Citation volume has not yet grown in step with output, and all authored work remains in non-senior positions to date. A transition into first or last authorship on an NSCLC-focused manuscript would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:44.078614+00', 'Publication output doubled to 10 papers (2021–2025) alongside a near-doubling of active collaborators to 48.', 'Engage now around the expanding 48-person collaborator network to build early visibility before senior authorship emerges.', 'early', '{"No senior-authored output yet, and citation volume has declined by 137, suggesting limited downstream impact so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c09b154a-9f96-47e2-9cb9-5256cc4e3634', '01cb967b-9f10-49ed-88eb-3f8965e2b9a7', 'nsclc', 'Jessica R. Bauman is a rising Lung Cancer investigator at Fox Chase Cancer Center whose research output has nearly tripled, growing from 6 publications (Aug 2016–Jul 2021) to 16 publications (Aug 2021–Jul 2026). The strongest signal is her expanding collaborator network. That network grew from 60 collaborators (Aug 2016–Jul 2021) to 122 collaborators (Aug 2021–Jul 2026), more than doubling in raw count. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), marking a meaningful shift in her role within the research community. A sustained pattern of senior-authored publications across multiple collaborative groups would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:39.270483+00', 'Publication output nearly tripled and collaborator network more than doubled across the two most recent five-year windows.', 'Engage now around her expanding collaborator network and emerging senior authorship before external industry relationships solidify.', 'early', '{"Citation volume declined by 172 across the two windows, tempering the impact signal despite strong output and network growth."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c157728b-50e9-4f31-9ca9-2c2af0b87152', '39b81ad1-3b21-4b6b-bbf7-fa2de9220896', 'nsclc', 'Édouard Auclin is an Emerging Leader in NSCLC based at Université Paris Cité, with 14 years of career experience and a Rising Star composite percentile of 74.8 (global rank 415). Publication output grew from 16 papers (2016–2020) to 21 (2021–2025), while his collaborator network expanded from 135 to 188 unique collaborators across the same periods. The strongest signal is network visibility, which sits at the 83rd percentile, supported by scientific visibility at the 80th percentile. Notably, senior-author share remains at zero across both periods, and citation volume declined by 2,587, tempering the otherwise solid visibility scores. A transition into a first senior-authored NSCLC publication would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:57:36.266203+00', 'Network visibility at the 83rd percentile drives current Rising Star status, with collaborators expanding to 188.', 'Monitor for transition into senior authorship; early relationship-building now positions MSL ahead of that inflection.', 'early', '{"Senior-author share is zero across both periods and citation volume declined by 2,587, suggesting limited independent scientific leadership so far."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c2d7c717-c0e1-46d5-8a9a-6292e95e0b51', '6f8e9b36-1f4e-426f-acd7-b154941d8089', 'nsclc', 'Moises J. Velez is a rising Lung Cancer investigator at the University of Rochester, eight years into an independent career. Publication output grew from 5 papers (Aug 2016–Jul 2021) to 6 papers (Aug 2021–Jul 2026), a modest but consistent increase in productivity. The strongest signal is authorship positioning: senior-authored work appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window, marking a meaningful shift in scientific independence. Collaborator breadth narrowed from 57 (Aug 2016–Jul 2021) to 45 (Aug 2021–Jul 2026), suggesting a more focused network. A first high-impact senior-authored publication in a leading Lung Cancer journal would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:34.629729+00', 'Senior-authored output emerging in the recent window signals a meaningful shift toward independent scientific leadership.', 'Early relationship-building now, ahead of anticipated senior-authored publications that could expand his visibility and influence.', 'early', '{"Citation volume declined by 2,832 across windows, and the collaborator network contracted, warranting close monitoring of research visibility."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c2e4deba-96ca-44db-83d0-fd9977c12de3', 'c0baf501-fa9f-40b3-a524-4c1509a0aa16', 'nsclc', 'Ethan B. Ludmir is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, with 12 years of career experience. He has sustained a consistent publication presence, producing 7 papers from 2016–2020 and 6 from 2021–2025, while his collaborator network has narrowed from 47 to 35 colleagues across the same windows. The defining feature of the profile is authorship evolution. His first senior-authored output has appeared in the recent window, signaling a shift from contributor to independent scientific voice. A transition into a sustained pattern of senior-authored publications would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:17.125958+00', 'First senior-authored output has emerged in 2021–2025, marking a meaningful shift in scientific independence.', 'Engage now around the emerging senior authorship signal before independent research agenda fully consolidates.', 'early', '{"Citation volume declined by 71 in the recent window, and the collaborator network contracted from 47 to 35, warranting close monitoring."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c3635966-ef82-4d21-8772-6c89b963ddbb', 'a571569a-3490-4b4c-864d-9abd696e13e0', 'nsclc', 'Valerio Nardone is an Emerging Leader in NSCLC based at the University of Campania ''Luigi Vanvitelli,'' with 11 years of career experience and a composite Rising Star percentile of 83.5 (global rank 272). Publication output grew from 11 papers (2016–2020) to 19 (2021–2025), while his collaborator network expanded from 51 to 155 individuals—a three-fold increase that anchors a Network Momentum percentile of 80. Scientific Momentum stands at the 74th percentile, supported by publication growth, though citation volume declined by 154, tempering the output signal. A transition into a named senior-author role on an NSCLC-focused publication would represent the next meaningful milestone for this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:52:48.769622+00', 'Collaborator network tripled from 51 to 155, driving an 80th-percentile Network Momentum score.', 'Engage now around his expanding collaborator network; monitor closely for first senior-authorship transition in NSCLC.', 'early', '{"Senior-author share remains at zero across both periods, indicating limited independent scientific ownership to date."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c4d7db4a-efa5-428e-9bda-17686cde330e', 'eaf03157-feb9-4c6f-8a56-f89a4178b407', 'nsclc', 'Vincent K. Lam is a rising Lung Cancer investigator at Johns Hopkins University with ten years in the field. The strongest signal is publication output. His output more than doubled, from 12 papers (Aug 2016–Jul 2021) to 27 papers (Aug 2021–Jul 2026), accompanied by a publication velocity delta of +2. His collaborator network expanded from 95 (Aug 2016–Jul 2021) to 227 (Aug 2021–Jul 2026), reflecting broadening scientific engagement. Notably, senior-authored work appears in the recent window (Aug 2021–Jul 2026) but not the early window, a meaningful shift in his role within research teams. First evidence of sustained senior-authored output in high-impact Lung Cancer journals would mark a meaningful inflection in his independent scientific voice.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:12.39883+00', 'Publication output more than doubled across consecutive five-year windows, now accompanied by emerging senior authorship.', 'Engage now around his expanding collaborator network and monitor for consolidation of senior-authored Lung Cancer publications.', 'early', '{"Citation volume declined by 37 across the two windows, suggesting newer work has not yet accumulated broad field uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c4f77846-af98-4e40-ac5f-397eb7babd25', '6ed53e15-8448-418f-b73e-25e1725f2f2c', 'nsclc', 'Sophie Cousin is a Balanced Rising Star in NSCLC, ranked 17th globally with a composite Rising Star percentile of 99.0. Publication output increased more than five-fold, from 5 papers (2016–2020) to 26 papers (2021–2025), accompanied by citation volume growth of +1,146. Her collaborator network expanded nearly eight-fold, from 34 to 267 collaborators, reflecting broad and accelerating scientific connectivity. This profile is characteristic of a Balanced Rising Star, with Scientific Momentum at the 95th percentile and Network Visibility at the 90th percentile advancing in parallel. First evidence of a transition into senior authorship, given a current senior-author share of zero, would mark a meaningful inflection in her independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:04:27.093372+00', 'Collaborator network grew nearly eight-fold, from 34 to 267, driving a 90th-percentile Network Visibility score.', 'Monitor closely for first senior-authored publication as the trigger for deeper scientific partnership conversations.', 'high', '{"Senior-author share remains zero across both periods, indicating all output is currently attributed to non-senior roles."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c566bd7c-c6b8-42e9-bc9f-43514bfc2898', '51760cb9-3694-4e5c-a7e5-937c477c495f', 'nsclc', 'Ibiayi Dagogo-Jack is a rising Lung Cancer investigator at Massachusetts General Hospital whose profile reflects sustained scientific engagement across a decade of clinical research. She contributed 33 publications from Aug 2016–Jul 2021 and 28 from Aug 2021–Jul 2026, maintaining consistent output while her collaborator network expanded from 133 to 177 across the same respective windows. The strongest signal is authorship evolution. Senior-authored work appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window, marking a meaningful shift in scientific independence. First evidence of senior-authored output in high-impact Lung Cancer journals would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:06:58.62356+00', 'Senior-authored output emerging in the recent window signals a meaningful shift toward independent scientific leadership.', 'Engage now around emerging senior-authored work to build relationship ahead of anticipated independent research program growth.', 'early', '{"Citation volume declined by 3,733 between windows, suggesting recent work has not yet accumulated broad field-wide uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c63dc7b8-5ff2-4511-81c5-5fbbb695f831', 'bd7b2583-9fc8-4f11-9619-bde7e9ebb584', 'nsclc', 'Xinqing Lin is a Balanced Rising Star in NSCLC, ranked 16th globally with a composite percentile of 99.1 across a nine-year career. Publication output increased more than four-fold, from 12 to 49 papers between the two periods, accompanied by a citation volume growth of +165. The strongest signal is network momentum, which sits at the 93rd percentile. Collaborator count expanded nearly tenfold, from 34 to 318 individuals, reflecting a rapid integration into broad scientific networks. A transition into consistent senior authorship would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:40:11.663013+00', 'Collaborator network expanded nearly tenfold, from 34 to 318, driving a 93rd-percentile network momentum score.', 'Prioritize early relationship-building now and monitor closely for first senior-authored publications as a key inflection signal.', 'high', '{"Senior-author share remains at zero across both periods, indicating Lin has not yet assumed independent scientific leadership on publications."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c732874d-0a29-41b0-9349-4127c4090922', '16d3a675-9b09-49fa-946a-7fc881145735', 'nsclc', 'Stefano Bongiolatti is a Network Accelerator in NSCLC based at Azienda Ospedaliero-Universitaria Careggi, ranked in the 70.7th percentile globally among Rising Stars. The strongest signal is network momentum, which sits at the 94th percentile. Collaborator count grew more than three-fold, from 71 to 235 individuals across the two periods. Publication output also increased, from 5 to 16 papers, though scientific momentum remains at the 46th percentile. A transition into senior authorship, currently at zero across both periods, would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:11:57.964503+00', 'Collaborator network expanded more than three-fold, from 71 to 235, placing network momentum at the 94th percentile.', 'Engage through his expanding collaborator network; monitor for first senior-authored publication as an inflection signal.', 'early', '{"Senior-author share remains zero across both periods, limiting attribution of scientific output directly to Bongiolatti."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c7446bd8-37a3-4298-bb9b-b36f464a84ec', '8a321e67-f9eb-491c-aa08-948654108604', 'nsclc', 'Valerio Gristina is a Balanced Rising Star in NSCLC at the University of Palermo, ranked 83rd globally with a composite Rising Star percentile of 95. Publication output more than tripled, from 5 papers (2016–2020) to 18 papers (2021–2025), while citation volume grew by 59 over the same period. The strongest signal is network momentum, which sits at the 95th percentile. His collaborator base expanded from 35 to 100 individuals across the two periods, nearly a threefold increase in active connections. A transition into a documented senior-author role would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:45:57.880005+00', 'Collaborator network nearly tripled to 100 peers, driving a 95th-percentile network momentum score.', 'Engage now around his expanding collaborator network; monitor closely for first senior-author publication as a relationship inflection point.', 'high', '{"Senior-author share remains at zero across both periods, indicating Gristina has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c7cc6f7a-99c0-4c31-bcb4-c8a6f4f576d5', '6806b094-a456-41e1-8b33-5f1c6135ee19', 'nsclc', 'Daniel M. Trifiletti is a rising Lung Cancer investigator at Mayo Clinic in Florida with 12 years of career experience. His publication output grew from 6 papers (Aug 2016–Jul 2021) to 8 papers (Aug 2021–Jul 2026), while his active collaborator network expanded from 72 to 93 colleagues across the same windows. The strongest signal is authorship positioning. Between the two windows, his senior-author share moved upward, indicating a shift toward independent scientific leadership. A first high-profile senior-authored publication in a top-tier Lung Cancer journal would mark a meaningful inflection in his standing within the field.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:19.927999+00', 'Collaborator network grew from 72 to 93 and senior-author share rose between the two windows.', 'Engage now around his expanding collaborator network to build early relationships before senior-author visibility increases.', 'early', '{"Citation volume declined by 297 between the two windows, suggesting limited downstream impact of recent output so far."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c7f2f8c7-89ef-4a63-9038-fae728ab086f', '92392d7a-dd31-4c85-800d-1f67ed869366', 'nsclc', 'Ronglai Shen is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center with 15 years of career experience. Across the two comparison windows, publication output held relatively stable, with 13 papers in Aug 2016–Jul 2021 and 11 papers in Aug 2021–Jul 2026, while collaborator reach remained broad at 203 and 197 respectively. The strongest signal is authorship positioning. Senior-authored output appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window, marking a meaningful shift in scientific responsibility. A sustained pattern of senior-authored publications in peer-reviewed Lung Cancer venues would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:12.778637+00', 'Senior-authored output emerged in Aug 2021–Jul 2026 after being absent in the prior five-year window.', 'Engage now around the emerging senior authorship signal before external industry relationships are established.', 'early', '{"Citation volume declined by 4,854 between windows, and publication count also dipped slightly, warranting close monitoring."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c90e4179-083b-4316-b39e-d6bc93525d5a', 'b087d046-d633-41a2-bd98-da2f48efa780', 'nsclc', 'Kezhong Chen at Peking University is a Balanced Rising Star in NSCLC, ranked 6th globally with a composite Rising Star percentile of 99.7. The strongest signal is scientific momentum, which sits at the 100th percentile. Publication output more than doubled, from 11 papers (2016–2020) to 26 (2021–2025), while citation volume grew by 608 and collaborator count expanded more than sevenfold, from 32 to 235. This profile is characteristic of a Balanced Rising Star, with both scientific and network dimensions advancing in parallel. First evidence of a senior-author publication would mark a meaningful inflection in Chen''s independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:05:56.183926+00', 'Citation volume surged by 608 and collaborators grew sevenfold to 235 in 2021–2025.', 'Monitor for first senior-author publication as the trigger for proactive scientific exchange and relationship-building.', 'high', '{"Senior-author share remains at 0 across both periods, indicating Chen has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c94a729f-cea3-41ad-878d-198c09b7f2e2', '8969001f-a29a-4981-acb3-7895693089fb', 'nsclc', 'Aurélie Swalduz is a Scientific Accelerator in NSCLC based at Centre Léon Bérard, ranked 121st globally with a Rising Star composite percentile of 92.7. The strongest signal is publication momentum. Output grew nearly five-fold, from 7 papers (2016–2020) to 33 papers (2021–2025), accompanied by a citation volume increase of +357, placing her scientific momentum at the 94th percentile. Her collaborator network expanded substantially, from 60 to 219 unique collaborators, reflecting a 3.6-fold broadening of her scientific reach. Senior-author share remains at zero across both periods; a first senior-authored publication in NSCLC would mark a meaningful inflection in her independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:46:39.386934+00', 'Publication output grew nearly five-fold and citation volume surged +357, placing scientific momentum at the 94th percentile.', 'Monitor for first senior-authored NSCLC publication as the trigger for deeper scientific partnership conversations.', 'moderate', '{"Senior-author share is 0 across both periods, indicating no independent authorship signal yet despite high output volume."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('c9e140f8-c8a1-4212-8a16-f2b13e0b5240', '870b70b3-5344-46f9-a3d5-1a650f43992f', 'nsclc', 'Ayal A. Aizer is an Emerging Leader in NSCLC with 15 years of career experience and an institutional base at Brigham and Women''s Hospital. He has sustained a consistent publication presence, contributing 11 papers from 2016–2020 and 9 from 2021–2025. The defining feature of the profile is authorship positioning. He is moving toward senior authorship, a shift that signals growing scientific ownership within the field. His collaborator network contracted from 103 individuals in 2016–2020 to 58 in 2021–2025, suggesting a deliberate focus rather than broad expansion. First evidence of a senior-authored, high-citation NSCLC publication would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:56.222075+00', 'A sustained publication record across both windows, now converging toward senior authorship, defines his current standing.', 'Engage now around senior authorship transition to establish relationship before independent scientific voice fully emerges.', 'early', '{"Collaborator network contracted by 45 individuals across windows, and citation volume declined, raising questions about current field-wide reach."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cb0d88a5-29ce-47c3-a918-fcc73f83b5f0', 'a01c10b9-9a21-4014-9aeb-ab8facd7a10c', 'nsclc', 'Theresa A. Boyle is an Emerging Leader in NSCLC research based at Moffitt Cancer Center, with 12 years of career experience. She has maintained a consistent publication output of 17 papers from 2016–2020 and 16 papers from 2021–2025, with senior-author share holding steady across both windows. The defining feature of the profile is the contraction in active collaborators. That network narrowed from 133 collaborators in 2016–2020 to 94 in 2021–2025, a reduction of 39 individuals, suggesting a deliberate consolidation around a focused research agenda. A transition into broader multi-institutional consortium work would represent the next milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:08.141264+00', 'Sustained publication output across both five-year windows signals durable, focused research productivity in NSCLC.', 'Engage now around focused research priorities before potential re-expansion of collaborative network at consortium level.', 'early', '{"Collaborator network contracted by 39 individuals across windows; reduced breadth may limit cross-institutional visibility and external citation growth."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cb9bfaaa-6ff6-4e25-afb6-787f4f2762ca', 'd0087106-74b0-4a03-8eae-8faecebf1d33', 'nsclc', 'Nicholas R. Mayne is an Emerging Leader in NSCLC at Duke University, with 10 years of career activity and a consistent publication record of 8 papers from 2016–2020 and 7 papers from 2021–2025. The defining feature of the profile is the contraction in collaborative network. Collaborator count declined from 35 in 2016–2020 to 27 in 2021–2025, suggesting a narrowing rather than broadening of research partnerships. Citation volume has decreased by 129 over the same span, and no senior-authored output has yet appeared in the record. A first senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:50.670128+00', 'Sustained output of 7–8 papers across both windows signals continued active engagement in NSCLC research.', 'Early relationship-building now positions the MSL ahead of a potential transition into senior authorship.', 'early', '{"No senior-authored output yet, declining collaborator count, and falling citation volume collectively limit current influence signals."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cbb61b43-5cfc-4c89-826f-2c26bc785c2a', 'd7c7423f-20d0-4b4b-a867-dd4b7410fa43', 'nsclc', 'Jeff Lewis is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, nine years into his career. The strongest signal is network expansion. His collaborator count grew from 74 individuals in 2016–2020 to 141 in 2021–2025, nearly doubling in raw terms. Publication output doubled as well, from 6 papers in 2016–2020 to 12 in 2021–2025, reflecting sustained and broadening scientific engagement. Senior-authored output has not yet appeared in the record. A transition into senior or last authorship would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:19:10.057123+00', 'Collaborator network nearly doubled to 141 individuals alongside doubled publication output in 2021–2025.', 'Early relationship-building now, with active monitoring for a first senior-authored publication as the key inflection signal.', 'early', '{"No senior-authored output has emerged yet, limiting evidence of independent scientific leadership within this profile."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cc082d5a-253a-4378-9abf-34406354b7ad', '42dab34d-9bee-4ca6-8d40-03f97b676e78', 'nsclc', 'Cole Friedes is a rising Lung Cancer investigator at the University of Pennsylvania whose research output has nearly tripled, growing from 5 publications (Aug 2016–Jul 2021) to 14 publications (Aug 2021–Jul 2026). The strongest signal is publication growth. That increase of 9 papers across windows is accompanied by a citation volume gain of 48, reflecting meaningful uptake of his work by the broader field. His collaborator network has also expanded substantially, from 24 (Aug 2016–Jul 2021) to 49 (Aug 2021–Jul 2026), more than doubling in the recent window. Notably, senior-authored output appears in the recent window but was absent in the earlier one. First evidence of independent grant funding or a first-author landmark publication would mark a meaningful inflection in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:42.116164+00', 'Publication output nearly tripled across windows, from 5 to 14, with 48 additional citations accrued.', 'Early relationship-building now, monitoring for expansion of senior-authored output and independent research initiatives.', 'early', '{"Career span is only 3 years; senior-authored output is nascent, and sustained independence remains to be demonstrated."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cc9a5123-1f07-432e-bcf3-836ea82208d7', 'f0b04e18-3abb-4e24-a5eb-a5ffb3b15915', 'nsclc', 'Jacob Sands is a rising Lung Cancer investigator at Dana-Farber Cancer Institute whose research output has nearly doubled, growing from 12 publications (Aug 2016–Jul 2021) to 22 publications (Aug 2021–Jul 2026). The strongest signal is citation volume. That growth reached +1,039 citations across the same comparison windows, reflecting meaningful uptake of his work by the broader scientific community. His collaborator network expanded from 146 to 247 researchers across those two periods, and senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021). A sustained pattern of senior-authored publications in the coming window would represent the next meaningful milestone in his scientific development.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:19.79397+00', 'Citation volume surged by over 1,039 across the two five-year windows, signaling rapid scientific uptake.', 'Engage now around the emerging senior authorship pattern and expanding 247-collaborator network for early relationship-building.', 'early', '{"Senior authorship is newly emergent in the recent window; its consistency across future output remains unconfirmed."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ccd55189-d394-44ee-b690-ebd129bd56be', '1060f8de-8d14-4db8-8d48-0ace0981ee78', 'nsclc', 'Kay See Tan is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, with 14 years of career experience. The strongest signal is network expansion. Collaborators grew from 90 to 142 individuals across the two windows, reflecting meaningful broadening of scientific relationships. Publication output increased from 22 papers (2016–2020) to 28 papers (2021–2025), a modest but steady gain. Senior-authored output has not yet appeared in the record. A transition into senior authorship would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:49.693541+00', 'Collaborator network expanded from 90 to 142 individuals, signaling broadening scientific engagement in NSCLC.', 'Initiate early relationship-building now, ahead of an anticipated transition into senior authorship roles.', 'early', '{"No senior-authored output has emerged yet, and citation volume declined by 640, suggesting limited downstream impact to date."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cdd5f9b5-b03c-477d-86c6-5d9730433af1', 'eeb40cdf-a2d4-40dd-a69c-d7b3b72a4099', 'nsclc', 'Benjamin H. Kann is a rising Lung Cancer investigator at Brigham and Women''s Hospital whose research output has grown from 5 publications (Aug 2016–Jul 2021) to 7 publications (Aug 2021–Jul 2026). The strongest signal is his expanding collaborative network. That network grew from 26 collaborators (Aug 2016–Jul 2021) to 36 collaborators (Aug 2021–Jul 2026), a gain of ten relationships in the more recent window. His senior-author share increased between the two windows, indicating a shift toward independent scientific direction. A transition into a principal investigator role on a dedicated lung cancer trial would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:55.980014+00', 'Collaborator network expanded by ten researchers and senior-author share rose across the two most recent windows.', 'Engage around his growing collaborator network to explore potential multi-site research partnerships in lung cancer.', 'early', '{"Citation volume declined by 104 between the two windows, tempering the otherwise positive publication and network growth signals."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cebcc855-2465-4816-bd79-ee1b61310340', '2d3f6037-2701-454c-96f2-6163cc7313f5', 'nsclc', 'Jason C. Chang is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, now ten years into his career. The strongest signal is publication output. His output more than doubled, from 10 papers (2016–2020) to 22 papers (2021–2025), while his collaborator network expanded from 80 to 205 individuals across the same windows — a more than 2.5-fold broadening in co-author reach. Senior-authored output has not yet appeared in the record. A transition into senior or last authorship would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:01.91153+00', 'Publication output doubled to 22 papers (2021–2025) alongside a collaborator network expanding to 205.', 'Build early relationship now and monitor for first senior-authored publication as a key inflection point.', 'early', '{"No senior-authored output has emerged yet, and citation volume has not grown in step with increased publication activity."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cf8be82c-23a5-4a5e-8738-2a92710bfc10', 'b4b21f67-b88a-4922-afcd-9465428f7cb4', 'nsclc', 'Jeffrey Clarke is a rising Lung Cancer investigator at Duke Medical Center whose research footprint has expanded meaningfully across two consecutive five-year windows. Publication output grew from 13 papers (Aug 2016–Jul 2021) to 18 papers (Aug 2021–Jul 2026), while citation volume increased by 240 citations between the same periods. The strongest signal is network growth. His collaborator count nearly doubled, from 72 (Aug 2016–Jul 2021) to 142 (Aug 2021–Jul 2026), reflecting a rapidly broadening sphere of scientific engagement. Senior-author share rose between the two windows, indicating a shift toward independent scientific leadership. A first high-profile senior-authored publication in a flagship Lung Cancer journal would mark a meaningful inflection in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:34.881189+00', 'Collaborator count nearly doubled to 142 (Aug 2021–Jul 2026), signaling rapid network expansion now.', 'Engage around his expanding collaborator network to identify emerging multi-site Lung Cancer research opportunities early.', 'early', '{"Network growth substantially outpaces publication volume growth, raising questions about whether collaborative breadth is yet converting to proportional output."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cfcdede9-3393-4953-a545-2436af343adf', '1c4160e4-a916-494d-b9e8-93648cdf75b0', 'nsclc', 'Dr. Jia Luo is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center whose research output and collaborative reach have expanded markedly over the past decade. Publication output grew from 9 papers (Aug 2016–Jul 2021) to 13 papers (Aug 2021–Jul 2026), accompanied by a citation volume increase of 220 citations between the same windows. The strongest signal is the network expansion. Collaborator count more than doubled, from 87 (Aug 2016–Jul 2021) to 196 (Aug 2021–Jul 2026), reflecting a broadening scientific footprint. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021), marking a meaningful shift in research independence. A sustained pattern of senior-authored publications in the next window would represent the next milestone in Dr. Luo''s scientific development.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:09:20.962213+00', 'Collaborator count more than doubled, from 87 to 196, between Aug 2016–Jul 2021 and Aug 2021–Jul 2026.', 'Engage now around growing collaborative network and emerging senior authorship to establish early relationship before visibility increases further.', 'early', '{"Publication count growth is modest in absolute terms; citation and network gains should be monitored to confirm sustained momentum."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('cfefc5b5-ff83-4cf4-a1c9-9f8f9988685a', 'f78fc297-3150-4780-be0d-b066fef2aa98', 'nsclc', 'Amy L. Cummings is an Emerging Leader in NSCLC based at the University of California, Los Angeles, with 9 years in the field. The strongest signal is her collaborator network expansion. Her network grew more than six-fold, from 30 collaborators in 2016–2020 to 191 in 2021–2025, while publication output more than doubled, from 6 papers to 13 across the same windows. All output to date reflects non-senior authorship, and citation volume has not yet scaled proportionally with the publication increase. A transition into senior-authored publications would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:19:02.084787+00', 'Collaborator network expanded more than six-fold, from 30 to 191, signaling rapid integration into the NSCLC research community.', 'Engage now around her expanding collaborator network and monitor closely for first senior-authored NSCLC publication.', 'early', '{"No senior-authored output yet, and citation volume has declined despite increased publication count, suggesting limited independent influence so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d1116e8b-7d39-4991-a402-16b783d2dc81', 'd30851f2-6ba2-44d6-a224-6fe91e1917bf', 'nsclc', 'Nitin Roper is a rising Lung Cancer investigator at the Center for Cancer Research, now 12 years into his career. The strongest signal is publication output. His output doubled, from 5 papers (Aug 2016–Jul 2021) to 10 papers (Aug 2021–Jul 2026). Alongside this, his collaborator network expanded from 59 (Aug 2016–Jul 2021) to 142 (Aug 2021–Jul 2026), more than doubling in raw count. Senior-authored work appears in the recent window (Aug 2021–Jul 2026) but not the early window (Aug 2016–Jul 2021), a meaningful directional shift. First evidence of sustained senior-authored output in a high-impact journal would mark a meaningful inflection in his independent scientific voice.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:26.126641+00', 'Publication output doubled and senior authorship emerged for the first time in the recent five-year window.', 'Engage now around the emerging senior authorship pattern and growing collaborator network before visibility broadens further.', 'early', '{"Citation volume declined by 80 in the recent window, suggesting newer work has not yet accumulated broad field engagement."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d25ade74-5eb5-46fc-8e4c-123f86403445', '97a5863d-d147-43c3-96a9-7bafbffe3f76', 'nsclc', 'Guangjian Yang is an Emerging Leader in NSCLC based at the Chinese Academy of Medical Sciences & Peking Union Medical College, with 8 years of career activity and a Rising Star composite percentile of 94.9 (global rank 85). Publication output more than doubled, from 14 papers (2016–2020) to 29 papers (2021–2025), accompanied by a citation volume growth of +57 and a collaborator network that expanded from 49 to 80 individuals. The strongest signal is scientific momentum, which sits at the 92nd percentile. Senior-author share remains at zero across both periods, indicating that volume and network growth are currently driving the profile rather than independent scientific leadership. A first senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:49:03.388322+00', 'Publication output doubled to 29 papers and citation volume grew +57, driving a 92nd-percentile scientific momentum score.', 'Monitor for first senior-authored NSCLC publication as the trigger for proactive relationship-building.', 'moderate', '{"Senior-author share is zero across both periods; all output reflects collaborative or junior contributions, not independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d3d53137-a5cb-400a-b296-547ec16772b0', '17ef69ab-238a-4e09-8ba9-ed2a18c92694', 'nsclc', 'Colin R. Lindsay is an Emerging Leader in NSCLC based at the University of Manchester, 13 years into his career. Publication output nearly tripled, from 8 papers (2016–2020) to 22 papers (2021–2025), while citation volume grew by 515, signalling accelerating scientific productivity. The strongest signal is network expansion. Collaborator count grew more than sixfold, from 52 to 347 individuals across the two periods, driving a Network Momentum percentile of 79 and a Network Visibility percentile of 85. A transition into consistent senior authorship, currently recorded at zero senior-author share, would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:51:56.468372+00', 'Collaborator network expanded more than sixfold, from 52 to 347, pushing Network Visibility to the 85th percentile.', 'Engage now around collaborative NSCLC research opportunities and monitor closely for first senior-authorship publications as an inflection signal.', 'early', '{"Senior-author share remains zero across both periods, limiting independent scientific ownership despite strong network and output growth."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d4bd4ca1-4c71-4978-9433-956a6c35d88b', 'c50f8b21-fa1f-40c0-bbd7-afa44c4123f3', 'nsclc', 'Rafael López Castro is an Emerging Leader in NSCLC based at Hospital Clínico Universitario de Valladolid with 11 years of career experience. Publication output increased more than four-fold, from 7 to 29 papers across the two periods, accompanied by a citation volume growth of +314, placing him at the 65th percentile for scientific momentum. The strongest signal is network visibility. His collaborator base expanded from 93 to 242 individuals—a 2.6-fold increase—driving a network visibility percentile of 92 and an overall Rising Star composite percentile of 86.2, ranked 227th globally. A transition into senior authorship, currently at zero across both periods, would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:50:38.221416+00', 'Network visibility at the 92nd percentile, with collaborators expanding from 93 to 242.', 'Engage now around his expanding collaborator network; monitor closely for first senior-authorship publications.', 'moderate', '{"Senior-author share remains zero across both periods, limiting evidence of independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d52f8e8d-99f7-43b2-bbc3-1ec601863bd3', '43144a66-b32a-4522-ae26-0fa086cfc12c', 'nsclc', 'Hira Rizvi is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, now nine years into her career. Her publication output has remained active across both windows, with 25 papers from 2016–2020 and 27 from 2021–2025. The strongest signal is network expansion. Her collaborator count grew from 260 to 335 across the same periods, reflecting a broadening scientific footprint. Senior-authored output has not yet appeared in the record. A transition into a first senior-authored publication would represent the next meaningful milestone in her development as an independent voice in the field.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:03.448363+00', 'Collaborator network expanded from 260 to 335, signaling broadening scientific engagement across two windows.', 'Engage now to build early relationship ahead of anticipated transition into senior authorship roles.', 'early', '{"No senior-authored output has emerged yet, limiting evidence of independent scientific leadership at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d563d180-0136-4a04-9f14-80c91ab0c6d8', 'b196e3d4-58c8-42ff-9cdc-c7c58487520a', 'nsclc', 'Rajwanth Veluswamy is a rising Lung Cancer investigator at the Icahn School of Medicine at Mount Sinai with 13 years of career experience. The strongest signal is publication output growth. He authored 8 papers from Aug 2016 – Jul 2021, increasing to 11 papers from Aug 2021 – Jul 2026, while his collaborator network expanded from 62 to 74 researchers across the same respective windows. His senior-author share rose between the Aug 2016 – Jul 2021 and Aug 2021 – Jul 2026 windows, indicating a shift toward independent scientific leadership. A transition into consistently anchoring high-impact multi-institutional studies would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:02.212391+00', 'Publication output grew from 8 to 11 papers and senior-author share rose between the two five-year windows.', 'Engage around his expanding collaborator network of 74 to explore multi-site Lung Cancer research partnership opportunities.', 'early', '{"Citation volume declined by 1,105 between the two windows, suggesting recent work has not yet accumulated broad field uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d64db819-66ca-42cc-b952-3600fa8dfd3d', '1ebf7457-888b-418a-9832-6fb2b3138d76', 'nsclc', 'Gaofeng Li is a Balanced Rising Star in NSCLC based at Kunming Medical University, ranked 31st globally with a composite Rising Star percentile of 98.2. Publication output grew from 8 to 14 papers across consecutive five-year periods, while citation volume expanded by 563, reflecting sustained scientific productivity. The strongest signal is network momentum, which sits at the 89th percentile. Collaborator count increased more than seven-fold, from 39 to 277 individuals, indicating rapid integration into broader research communities. First evidence of senior authorship would mark a meaningful inflection in Li''s independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:56:20.192337+00', 'Collaborator network expanded more than seven-fold, from 39 to 277, driving a 98.2 composite percentile.', 'Monitor for first senior-authored publication as the trigger for proactive scientific exchange and relationship-building.', 'high', '{"Senior-author share remains at zero across both periods, indicating Li has not yet led publications independently."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d66f9e2d-efc2-4a47-9b19-5b6fcafe4fde', 'f96c18a6-89db-43c9-a264-263c70f4ee4f', 'nsclc', 'Maen Hussein is an Emerging Leader in NSCLC based at Sarah Cannon, now 11 years into his career. The strongest signal is publication output. His published work doubled from 6 papers (2016–2020) to 12 papers (2021–2025), reflecting a sustained increase in research productivity. His collaborator network has also expanded meaningfully, growing from 83 to 115 individuals across the same windows. A transition into a stabilized or growing senior-author role would represent the next milestone to monitor in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:53.785811+00', 'Publication output doubled from 6 to 12 papers in 2021–2025, alongside a collaborator network expanding to 115.', 'Engage now around collaborative research opportunities given his expanding 115-person network and early-stage profile.', 'early', '{"Senior-author share is receding and citation volume declined, suggesting output growth has not yet translated into field-defining influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d6bde1dc-2bb7-4498-83fb-8964a56c18e9', '7a0d014d-0889-42ae-82ab-b60acb324a0e', 'nsclc', 'Rania G. Aly is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, now nine years into her career. The strongest signal is her collaborator network expansion. Her active collaborators grew from 22 in 2016–2020 to 56 in 2021–2025, a more than two-fold increase in raw count. Publication output held steady at 5 papers across both windows, and no senior-authored work has appeared to date. A first senior-authored publication in NSCLC would mark a meaningful inflection in her independent scientific voice.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:04.007934+00', 'Collaborator network more than doubled, from 22 to 56, signaling rapidly expanding scientific connectivity.', 'Monitor for first senior-authored NSCLC publication as the primary trigger for deeper MSL engagement.', 'early', '{"No senior-authored output yet, and citation volume declined by 162, suggesting limited independent scientific impact so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d798240c-4ea0-4b47-99a5-6419d8a628e3', 'a52c288f-1b96-4a58-b046-c85ae1804ac8', 'nsclc', 'Dr. Veronica Chiang is a rising Lung Cancer investigator at Yale University whose research output has grown from 10 publications (Aug 2016–Jul 2021) to 12 publications (Aug 2021–Jul 2026), accompanied by a publication velocity delta of +1 across those same windows. Her collaborator network expanded from 105 (Aug 2016–Jul 2021) to 123 (Aug 2021–Jul 2026), reflecting broadening cross-institutional engagement. The strongest signal is authorship positioning. Between the two windows, her senior-author share has risen, indicating a shift toward independent scientific leadership within Lung Cancer research. A transition into principal investigator status on a Lung Cancer-focused clinical or translational study would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:27.801278+00', 'Rising senior-author share across both windows signals growing independent scientific leadership in Lung Cancer research.', 'Engage now around her expanding collaborator network to establish relationship ahead of anticipated senior-led study activity.', 'early', '{"Citation volume declined by 1,892 between the two windows, suggesting recent work has not yet accumulated broad field uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d79b3142-f208-43d7-8556-cf43c2e8e80c', '61285d5a-a912-475f-a64a-e128fd16c6f0', 'nsclc', 'Caroline E. McCoach is an Emerging Leader in NSCLC research based at the University of California, San Francisco, with 14 years of career experience. She produced 21 publications from 2016 to 2020 and 13 from 2021 to 2025, maintaining a sustained output across both windows. The defining feature of the profile is authorship direction. She is moving toward senior authorship, a structural shift that signals growing independent scientific authority. Her collaborator network held steady at 182 researchers across both periods, reflecting a stable and established peer base. A first senior-authored publication in a high-impact NSCLC venue would mark a meaningful inflection in her independent scientific standing.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:21.213317+00', 'Authorship moving toward senior roles signals growing independent scientific authority across 14 career years.', 'Engage now to build relationship ahead of anticipated transition into senior authorship in NSCLC.', 'early', '{"Publication volume declined from 21 to 13 across the two windows, and citation volume growth is negative, warranting close monitoring."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d967b5b4-5ed1-472c-9e00-6943c8265f4c', '5932cde0-bfa5-459f-8501-2c741a5333d8', 'nsclc', 'Alissa Poteete is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, approximately 10 years into her career. The strongest signal is network expansion. Her collaborator count grew from 73 in 2016–2020 to 173 in 2021–2025, a more than twofold increase of 100 additional collaborators. Publication output doubled from 5 papers in 2016–2020 to 10 in 2021–2025, though senior-authored output has not yet appeared. First evidence of senior or last authorship would mark a meaningful inflection in her independent scientific voice.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:49.056947+00', 'Collaborator network more than doubled, from 73 to 173, signaling rapidly expanding scientific reach.', 'Engage now around her expanding collaborator network and monitor closely for first senior-authored publication.', 'early', '{"No senior-authored output yet; citation volume declined by 149, suggesting limited downstream impact of recent work so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('d9990935-42eb-474e-ace8-66e930aea122', 'f28b42b3-1fde-4046-a5e2-a18a0c8d993f', 'nsclc', 'Jason J. Luke is a rising Lung Cancer investigator at the University of Chicago whose publication output doubled, from 5 papers (Aug 2016–Jul 2021) to 10 papers (Aug 2021–Jul 2026). The strongest signal is network expansion. His active collaborator count grew from 40 (Aug 2016–Jul 2021) to 51 (Aug 2021–Jul 2026), reflecting broadening cross-institutional engagement. Senior-author share held steady across both windows, indicating sustained scientific ownership rather than a shift toward junior supporting roles. A transition into multi-site trial leadership or guideline-committee participation would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:31.767624+00', 'Publication output doubled across consecutive five-year windows, alongside a collaborator network expanding from 40 to 51.', 'Engage around the expanding collaborator network of 51 to explore co-investigator or advisory opportunities early.', 'early', '{"Citation volume declined by 447 across the two windows, suggesting recent work has not yet accumulated broad field uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('db4eec15-4c85-4e6e-a553-d1277dfc1f50', '93f154f6-bc73-41de-9b89-9dd4e5784f1f', 'nsclc', 'Yung-Hung Luo is a Balanced Rising Star in NSCLC, ranked 18th globally with a composite Rising Star percentile of 99.0. Publication output increased five-fold, from 7 papers (2016–2020) to 35 papers (2021–2025), accompanied by a 90-point citation volume growth. The strongest signal is network momentum, which sits at the 95th percentile. Collaborator count expanded nearly six-fold, from 30 to 178 individuals across the same periods. A transition into consistent senior authorship—currently recorded at zero senior-author share—would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:52:34.100957+00', 'Collaborator network expanded nearly six-fold, from 30 to 178, placing network momentum at the 95th percentile.', 'Engage now around growing collaborative network; monitor closely for first senior-authored NSCLC publication as relationship anchor.', 'high', '{"Senior-author share remains at zero across both periods, limiting independent scientific ownership signals despite high output growth."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('dbff154f-333d-4aa7-bbfe-18958097fbc1', 'f9515b75-03bf-4226-8705-5159411219c1', 'nsclc', 'Priya Velu is an Emerging Leader in NSCLC at Cornell University, now nine years into her career. The strongest signal is network expansion. Her collaborator count grew from 25 in 2016–2020 to 42 in 2021–2025, a near-doubling in raw connections. Publication output moved modestly from 5 papers in 2016–2020 to 6 in 2021–2025, and all output to date has been in non-senior authorship roles. A transition into first senior-authored publication would represent the next meaningful milestone for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:29.843995+00', 'Collaborator network expanded from 25 to 42 individuals across the two most recent windows.', 'Engage now around her expanding collaborator network to establish early relationship before senior authorship emerges.', 'early', '{"No senior-authored output yet; publication volume remains low and citation growth is negative, limiting independent scientific visibility."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('dc31bce5-ceec-4a69-a2a2-bcbae2fcdd30', '36c22bf3-9165-4087-9c83-145e81659609', 'nsclc', 'Viola W. Zhu is an Emerging Leader in NSCLC at the University of California, Irvine, now in her tenth year of practice. Her collaborator network expanded from 195 to 206 individuals across the two study windows, reflecting a broadening scientific footprint. The defining feature of the profile is authorship evolution. She is moving toward senior authorship positions, a structural shift that signals growing scientific independence. A first senior-authored publication in NSCLC would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:55.747238+00', 'A growing collaborator network and a clear move toward senior authorship signal emerging scientific independence.', 'Initiate early relationship-building now, ahead of anticipated senior authorship, to establish credibility before influence solidifies.', 'early', '{"Publication output declined from 34 papers (2016-2020) to 20 (2021-2025), and citation volume also contracted, warranting close monitoring."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('dca22d60-d945-49cc-bfa3-0b5890632b14', '942942e0-3e07-4bf0-b32a-fb553d0f2b77', 'nsclc', 'Giorgia Guaitoli is an Emerging Leader in NSCLC based at the University of Modena and Reggio Emilia, with 8 years in the field and a Rising Star composite percentile of 68.9 (global rank 513). Publication output increased from 9 papers (2016–2020) to 22 papers (2021–2025), accompanied by a citation volume growth of +31. The strongest signal is network visibility, which sits at the 89th percentile. Her collaborator base expanded from 134 to 204 individuals across the two periods, reflecting broad and growing scientific connectivity. A transition into senior authorship, currently at zero across both periods, would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:09:38.790587+00', 'Network visibility at the 89th percentile, with collaborators expanding from 134 to 204.', 'Engage now around her expanding collaborator network; monitor closely for first senior-authorship publications.', 'early', '{"Senior-author share remains zero across both periods, indicating limited independent scientific leadership to date."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('dcfcb827-11fb-4806-80f0-a656f90184b6', '6648e326-c5e9-4fe3-a778-29decba1b669', 'nsclc', 'Alexandre Reuben is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center with 12 years of career experience. The strongest signal is publication output growth. He authored 13 publications from Aug 2016–Jul 2021, increasing to 15 from Aug 2021–Jul 2026, while his collaborator network expanded from 144 to 165 across the same respective windows. Notably, senior-authored output appears in the Aug 2021–Jul 2026 window but not in the Aug 2016–Jul 2021 window, marking a meaningful shift in his role within the research community. A sustained pattern of senior-authored publications in the next window would represent the next milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:41.416636+00', 'Senior-authored output emerged in Aug 2021–Jul 2026, absent from the prior five-year window.', 'Engage now around the emerging senior authorship signal to build an early relationship before influence broadens.', 'early', '{"Citation volume declined by 1,078 across the two windows, which may limit downstream influence of recent output."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('dd03d690-96b6-4d3c-9ceb-41995bb8c1ca', 'cb3b249e-743a-4484-b7ed-b4f305898e2b', 'nsclc', 'Maria Thor is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center whose research activity has grown measurably across two consecutive five-year windows. Publication output increased from 6 papers (Aug 2016–Jul 2021) to 8 papers (Aug 2021–Jul 2026), with a publication velocity delta of +1. The strongest signal is network expansion. Her collaborator count grew from 32 (Aug 2016–Jul 2021) to 47 (Aug 2021–Jul 2026), a gain of 15 colleagues. Notably, senior-authored output appears in the recent window (Aug 2021–Jul 2026) but was absent in the earlier window (Aug 2016–Jul 2021). A sustained pattern of senior-authored publications in the next review window would represent the next meaningful milestone in her scientific profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:13.429664+00', 'Senior-authored output emerged in Aug 2021–Jul 2026 after being absent in the prior five-year window.', 'Engage now around her expanding collaborator network to establish early relationships before senior authorship solidifies.', 'early', '{"Citation volume declined by 212 between the two windows, tempering the otherwise positive publication and network growth signals."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ddb86115-edf2-4f84-8d2d-a1ea9b817296', 'e7bd1375-b154-40b0-b36c-1d28c6d2b2dc', 'nsclc', 'Xabier Mielgo-Rubio is an Emerging Leader in NSCLC based at Hospital Universitario Fundación Alcorcón with 14 years of career experience and a Rising Star composite percentile of 83.6 (global rank 271). Publication output tripled, from 8 papers in 2016–2020 to 24 in 2021–2025, accompanied by a citation volume growth of +99, reflecting accelerating scientific productivity. His collaborator network expanded from 70 to 158 individuals across the same periods, supporting a Network Visibility percentile of 82. Senior-author share remains at zero across both periods, which tempers the overall profile. First evidence of a senior-authored publication would mark a meaningful inflection in his independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:45:51.339539+00', 'Publication output tripled to 24 papers and citation volume grew by 99 in 2021–2025.', 'Monitor for first senior-authored publication and engage proactively around his expanding 158-collaborator network.', 'early', '{"Senior-author share is zero across both periods, indicating no independent first-position scientific output to date."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('debee90f-ed56-4445-938e-e421f5e675d1', 'ec3a3b67-05d1-4631-bb09-e7ee1c374de2', 'nsclc', 'Jennifer L. Sauter is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center with 13 years of career experience. The strongest signal is her authorship trajectory. Between Aug 2021 – Jul 2026 she contributed 15 publications with a senior-author share that rose compared to the Aug 2016 – Jul 2021 window of 19 publications, indicating a shift toward independent scientific leadership. Her collaborator network narrowed from 292 (Aug 2016 – Jul 2021) to 112 (Aug 2021 – Jul 2026), suggesting a more focused research agenda. A transition into first or sole senior authorship on a high-impact Lung Cancer study would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:12.030501+00', 'Rising senior-author share across two windows signals a shift toward independent scientific leadership.', 'Early relationship-building now, ahead of anticipated senior-authored output in the current publication window.', 'early', '{"Citation volume declined by 6,565 between the two windows, warranting close monitoring of downstream scientific impact."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('df0418fc-08b5-430c-bf56-a98ca0ed4b18', '7b9fb23f-be1c-477f-ad28-75f6e77710c4', 'nsclc', 'Michael F. Gensheimer is an Emerging Leader in NSCLC at Stanford University, now 13 years into his career. The defining feature of the profile is network expansion. His collaborator base grew from 65 individuals in 2016–2020 to 90 in 2021–2025, a gain of 25 colleagues, while publication output shifted from 15 papers in 2016–2020 to 5 in 2021–2025. No senior-authored output has appeared yet, suggesting a profile still consolidating rather than directing independent lines of work. A first senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:00.713729+00', 'Collaborator network expanded from 65 to 90 individuals across consecutive five-year windows.', 'Early relationship-building now, monitoring for first senior-authored NSCLC output as the key activation signal.', 'early', '{"No senior-authored output has emerged yet, and publication volume declined by 10 papers across the two windows."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e4a5205d-09e7-4f87-a429-c026532eee74', '0fb7fb5e-cccb-4cfc-a89a-dd27a73d222c', 'nsclc', 'Hui Yu is an Emerging Leader in NSCLC based at the University of Colorado Anschutz Medical Campus, now 11 years into an active research career. The defining feature of the profile is the sustained collaborative network. That network spanned 105 distinct collaborators from 2016 to 2020 and remains broad at 91 collaborators from 2021 to 2025, indicating durable scientific connectivity even as publication output shifted from 16 papers to 9 papers across the same windows. No senior-authored output has yet appeared in the record. A first senior-authored publication would mark a meaningful inflection in this profile''s development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:41.951954+00', 'A broad collaborator network of 91 active connections signals sustained scientific engagement worth early MSL attention.', 'Prioritize early relationship-building now, monitoring specifically for a first senior-authored NSCLC publication as the key inflection signal.', 'early', '{"No senior-authored output has been recorded, and publication volume declined from 16 to 9 papers across the two windows."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e51c7edc-a085-43ec-9aad-e4d6e5eae670', '20c0988c-e4e3-4e62-9d1a-dda8020258aa', 'nsclc', 'Frank E. Mott is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center with 12 years of career experience. Publication output held steady at 5 papers in both the Aug 2016–Jul 2021 and Aug 2021–Jul 2026 windows, while the defining feature of the profile is the authorship shift: senior-authored work appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window. The strongest signal is this move into senior authorship, indicating growing independent scientific direction. Collaborator count narrowed from 78 (Aug 2016–Jul 2021) to 32 (Aug 2021–Jul 2026), suggesting a more focused research network. A sustained increase in senior-authored publications across a subsequent window would mark a meaningful inflection in his independent investigator profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:21.708838+00', 'Senior-authored output emerged in Aug 2021–Jul 2026 after being absent in the prior five-year window.', 'Engage now around senior-authored research themes to build early relationship before independent program fully consolidates.', 'early', '{"Collaborator count declined sharply from 78 to 32 across the two windows, and citation volume fell by 697, limiting current broader field visibility."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e55d8fa1-cabe-4f0c-b173-2a6a0a6a50e9', 'e5345557-f9cd-4aa2-a2b8-0affda9e70e8', 'nsclc', 'Linda S. Ahn is an Emerging Leader in NSCLC based at Memorial Sloan Kettering Cancer Center, now 10 years into her career. The strongest signal is publication output growth. She authored 5 papers from 2016–2020, rising to 7 papers from 2021–2025, while her collaborator network expanded modestly from 40 to 41 individuals across the same windows. No senior-authored output has appeared to date, and citation volume has not yet grown in step with added publications. A transition into senior authorship would represent the next meaningful milestone in her scientific development.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:22.221419+00', 'Publication output grew from 5 to 7 papers across consecutive five-year windows at a top-tier institution.', 'Early relationship-building now, with close monitoring for a first senior-authored publication as the key inflection point.', 'early', '{"No senior-authored output yet, and citation volume has declined by 182, suggesting limited downstream reach so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e5f56333-1ff5-4830-a129-e2cb08fe4d74', '8e9833c8-c76f-43a5-badd-b3389b1a9b21', 'nsclc', 'Atocha Romero is an Emerging Leader in NSCLC based at Hospital Universitario Puerta de Hierro Majadahonda, ranked 132nd globally with a Rising Star composite percentile of 92. Publication output increased 2.5-fold, from 12 papers (2016–2020) to 30 papers (2021–2025), accompanied by citation volume growth of +119. The strongest signal is network expansion. Collaborator count grew from 60 to 211 between the two periods, a 3.5-fold increase, reflected in a Network Momentum percentile of 74 and a Network Visibility percentile of 88. Senior-author share remains at zero across both periods, which contextualizes the output growth. A transition into a first senior-authored publication would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:07:07.991925+00', 'Collaborator network expanded 3.5-fold, from 60 to 211, driving a Network Visibility percentile of 88.', 'Engage around the expanding collaborator network and monitor closely for a first senior-authored NSCLC publication.', 'moderate', '{"Senior-author share is zero across both periods; output growth may reflect collaborative contribution rather than independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e66cb91a-2062-41c5-a9ec-2b90bd295143', 'fe132264-5f32-4163-bb1a-7b073418a143', 'nsclc', 'Francisco Sánchez-Vega is an Emerging Leader in NSCLC research based at Memorial Sloan Kettering Cancer Center, now 11 years into his career. Publication output held steady at 11 papers across both the 2016–2020 and 2021–2025 windows, reflecting consistent productivity. The strongest signal is network breadth. Collaborator count expanded from 165 to 166 across the two windows, indicating a wide and stable web of scientific relationships. No senior-authored output has appeared to date; a first senior-authored publication would mark a meaningful inflection in this profile''s independent scientific voice.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:07.208264+00', 'Sustained publication output across both five-year windows signals consistent NSCLC research engagement worth monitoring now.', 'Monitor for first senior-authored publication as the trigger for deeper MSL relationship-building and scientific dialogue.', 'early', '{"No senior-authored output has emerged across either window, limiting evidence of independent scientific leadership so far."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e6bf1d9f-3293-4638-8562-3cb44f921142', 'fc574fc2-b0dc-46f6-bb37-6991975057e2', 'nsclc', 'Estela Sánchez-Herrero is an Emerging Leader in NSCLC at Hospital Universitario Puerta de Hierro Majadahonda, with 7 years of career activity and a Rising Star composite percentile of 68.6. Publication output grew from 5 papers (2016–2020) to 9 (2021–2025), while citation volume increased by 323 citations across the same interval. The strongest signal is network momentum, which sits at the 80th percentile. Her collaborator base expanded from 35 to 61 individuals, a 74% increase in active connections. A transition into a senior-author role on any forthcoming NSCLC publication would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:10:38.207758+00', 'Collaborator network expanded from 35 to 61, placing network momentum at the 80th percentile.', 'Engage now around her expanding collaborator network while building early relationship ahead of any senior-authorship transition.', 'early', '{"Senior-author share remains at 0 across both periods, indicating contributions are currently non-independent."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e6cd4569-eeee-4a8f-943d-b420088b199c', 'e8876001-f73c-496b-af6c-4f95be6a3033', 'nsclc', 'Mark Kriegsmann is an Emerging Leader in NSCLC based at Heidelberg University, with 12 years of career experience and a Rising Star composite percentile of 79 (global rank 346). Publication output tripled, from 12 papers (2016–2020) to 36 papers (2021–2025), accompanied by citation volume growth of +363, reflecting meaningful scientific acceleration. The strongest signal is network visibility, which sits at the 87th percentile, supported by a collaborator base that more than doubled from 84 to 198 individuals across the same periods. Scientific momentum is more moderate at the 54th percentile, and senior-author share remains at zero across both periods, indicating Kriegsmann is still operating primarily in non-senior roles. A transition into a first senior-authored publication in NSCLC would represent the next meaningful milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:07:44.45139+00', 'Collaborator network more than doubled to 198, driving network visibility to the 87th percentile.', 'Monitor for first senior-authored NSCLC publication as a trigger for proactive relationship-building.', 'early', '{"Senior-author share is zero across both periods, suggesting limited independent scientific leadership to date."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e72694d3-b05e-410c-9881-8940bccaf05e', '7f5a7db3-3053-4155-9c1d-3cef45a7466c', 'nsclc', 'Sylvia M. Lee is a rising Lung Cancer investigator at the University of Washington whose research output has grown from 5 publications (Aug 2016 – Jul 2021) to 7 publications (Aug 2021 – Jul 2026). The strongest signal is authorship positioning. Senior-authored work appears in the recent window (Aug 2021 – Jul 2026) but was absent in the earlier window (Aug 2016 – Jul 2021), marking a meaningful shift in scientific independence. Her collaborator network has also expanded, from 34 colleagues (Aug 2016 – Jul 2021) to 44 (Aug 2021 – Jul 2026). A sustained pattern of senior-authored output across multiple publications would represent the next milestone in establishing her as an independent voice in the field.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:32.823737+00', 'Senior-authored output has emerged in the recent window after being absent in the prior window.', 'Engage now around her emerging senior-authored work to build an early relationship before her network broadens further.', 'early', '{"Citation volume declined by 700 between windows, suggesting limited downstream uptake of recent work so far."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e73a1b76-bad2-4760-8ef8-99524172879b', '07101917-d39c-4177-b351-2f74ae53a2cc', 'nsclc', 'Jessica Konen is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center, approximately ten years into her research career. The strongest signal is a shift in authorship position. Senior-authored output appears in the Aug 2021 – Jul 2026 window but was absent in the Aug 2016 – Jul 2021 window, indicating a meaningful change in scientific independence. Publication output held relatively stable, with 7 papers in Aug 2016 – Jul 2021 and 5 in Aug 2021 – Jul 2026, while her collaborator network narrowed from 51 to 25 across the same periods, suggesting a more focused research program. A first high-impact senior-authored publication in a top-tier Lung Cancer journal would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:49.499712+00', 'Senior-authored output emerged in Aug 2021 – Jul 2026 after being absent in the prior five-year window.', 'Early relationship-building now, ahead of anticipated senior-authored publications that could expand her visibility.', 'early', '{"Collaborator count dropped from 51 to 25 (Aug 2016 – Jul 2021 vs. Aug 2021 – Jul 2026), and citation volume declined, warranting close monitoring."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('e7b4611b-025b-413e-a08e-ae6996a302f8', 'b5ee1d52-6181-41a3-a91e-79aa92878327', 'nsclc', 'Dr. Carolyn J. Presley is a rising Lung Cancer investigator at The Ohio State University whose research output has grown markedly across two consecutive five-year windows. The strongest signal is publication volume. Output increased more than threefold, from 13 papers (Aug 2016–Jul 2021) to 40 papers (Aug 2021–Jul 2026), with a publication velocity delta of +2. Her collaborator network expanded from 65 to 191 individuals across those same windows, while citation volume grew by 395 citations. Senior-author share held steady across both windows, indicating sustained independent contribution. A transition into first or last authorship on a high-impact multicenter trial would represent the next meaningful milestone to monitor.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:07:35.359856+00', 'Publication output more than tripled, from 13 to 40 papers, between the two five-year windows.', 'Engage now around her expanding collaborator network to establish presence ahead of potential multicenter trial involvement.', 'moderate', '{"Collaborator count nearly tripled; network breadth should be monitored to confirm depth of scientific collaboration rather than peripheral co-authorship."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ebf7c08d-eb11-43f5-9955-8520adb25188', '556d1452-b79b-4916-8c50-67b635864903', 'nsclc', 'Martin Metzenmacher is an Emerging Leader in NSCLC based at Ruhrlandklinik, ranked 473rd globally with a Rising Star composite percentile of 71.2. Publication output increased nearly three-fold, from 10 papers (2016–2020) to 27 papers (2021–2025), while his collaborator network expanded from 59 to 152 individuals, a growth of more than 2.5-fold. The strongest signal is network momentum, which sits at the 75th percentile. Collaborator count grew from 59 to 152 across the two periods, indicating broad and accelerating scientific connectivity. First evidence of a transition into senior authorship would mark a meaningful inflection in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:00:39.598798+00', 'Collaborator network grew from 59 to 152, placing network momentum at the 75th percentile.', 'Engage around his expanding collaborator network to build early relationship before senior authorship emerges.', 'early', '{"Senior-author share remains at 0 across both periods, and citation volume growth is negative at -62."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ec5c3ada-0832-4f13-b3f0-79a7bdf9661c', '5f097c1f-7707-4d24-a17f-75aa74cf9613', 'nsclc', 'Virginia Calvo is a Scientific Accelerator in NSCLC at Hospital Universitario Puerta de Hierro Majadahonda, now 12 years into her career. Publication output nearly tripled, from 14 papers (2016–2020) to 40 papers (2021–2025), accompanied by a citation volume growth of +98, placing her at the 92nd percentile for scientific momentum. Her collaborator network has more than doubled, expanding from 103 to 224 co-authors across the same periods, reflecting broad and accelerating scientific connectivity. A transition into a consistent senior-author role would represent the next meaningful milestone to monitor in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:50:30.894886+00', 'Publication output nearly tripled to 40 papers (2021–2025) with citation volume growing +98.', 'Monitor closely for first senior-authored NSCLC publication as the primary trigger for deeper scientific engagement.', 'moderate', '{"Senior-author share remains at zero across both periods, indicating Calvo has not yet assumed independent scientific leadership on publications."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ec6ce08f-e0c8-44f5-b861-a8f395544018', '8f32b388-425d-4b13-b7ba-4a796dc38952', 'nsclc', 'Anna Wurtz is an Emerging Leader in NSCLC research based at Yale Cancer Center, with 10 years of career experience. She has maintained a consistent publication output of 6 papers in both the 2016–2020 and 2021–2025 windows, signaling steady engagement with the field. Her collaborator network remains broad and stable, spanning 73 collaborators in the earlier window and 70 in the current one. The strongest signal is citation volume, which has grown by 1,495 citations across the current window, reflecting meaningful uptake of her work by the broader scientific community. A transition into senior-authored output would represent the next milestone in her development as an independent voice in NSCLC.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:19:05.302119+00', 'Citation volume has grown by 1,495, reflecting meaningful and sustained uptake of her published work.', 'Prioritize early relationship-building now, monitoring closely for a first senior-authored NSCLC publication as a key inflection point.', 'early', '{"No senior-authored output has emerged yet, limiting evidence of independent scientific leadership within the NSCLC field."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ecd8ac50-2d6a-4657-8889-85efbe55fccc', 'b9f7cdd3-4faa-4608-8f19-acc56d1bbfc4', 'nsclc', 'Jun Lü is an established NSCLC researcher at Shanghai Jiao Tong University with approximately 15 years of active scientific contribution and a career publication record of 678 papers, reflecting sustained engagement with the field. Within the established expert cohort, publication volume and recent productivity sit near the median, indicating consistent output rather than a concentrated burst, while first and last authorship density falls at the 28th percentile, suggesting a collaborative contributor profile with meaningful but not dominant independent leadership. His cohort score of 88.0 places him firmly within the top-100 surfacing board for NSCLC, underscoring recognized influence within a competitive peer set.', 'v1.0', 'claude-sonnet-4-6', '2026-06-04 12:05:58.316954+00', 'As NSCLC treatment paradigms continue to evolve rapidly around biomarker-driven therapy and combination strategies, Lü''s sustained presence at a major Chinese academic medical center positions him as a relevant voice on how these advances translate into the Chinese patient population and clinical practice context.', 'Given his collaborative publication profile and institutional base, Lü is well-suited for scientific dialogue around real-world evidence generation, patient population characteristics, and the application of global trial data to Chinese clinical settings. His perspective on study design considerations and the interpretation of biomarker data in diverse populations could add meaningful depth to discussions on therapeutic positioning in NSCLC.', 'Signal is consolidated and reliable given his established cohort designation and consistent career output, though the lower first/last authorship and clinical trial activity percentiles suggest his influence is expressed more through collaborative science than independent trial leadership.', '{"Pharma engagement breadth is at the 0th percentile within the established cohort, indicating very limited prior industry interaction, which may require a foundational relationship-building approach before substantive scientific exchange."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ef417a61-c38e-4c8d-bf56-0bb3069b23d2', 'cb2f85df-d17e-4c9e-9478-90fd9a44592d', 'nsclc', 'Jonathan T. Yang is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center whose profile reflects steady network expansion alongside an emerging shift in authorship responsibility. His collaborator base grew from 44 (Aug 2016–Jul 2021) to 50 (Aug 2021–Jul 2026), adding six new research relationships in the recent window. The strongest signal is authorship direction: senior-authored output appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window, marking a meaningful change in his role within research teams. Publication volume held at 5 papers across both windows, with a publication velocity delta of +2 in the recent period. A first high-profile senior-authored publication in a major Lung Cancer journal would represent the next meaningful milestone for this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:08:03.821107+00', 'Senior-authored output emerged in Aug 2021–Jul 2026 after being absent in the prior five-year window.', 'Engage now around his emerging senior authorship to build an early relationship before his independent research voice solidifies.', 'early', '{"Citation volume declined by 818 between windows, and absolute publication count remains modest at 5 papers per window."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f0537ee1-f4cc-4550-8aba-77d6dce2b4ea', '3e522454-9057-4237-bfb0-8dcb49af2a65', 'nsclc', 'Deepa Rangachari is an Emerging Leader in NSCLC based at Beth Israel Deaconess Medical Center, with 11 years of career activity. She produced 26 publications from 2016 to 2020 and 15 from 2021 to 2025, with authorship moving toward senior positions across that span. The strongest signal is network consolidation. Her collaborator count narrowed from 89 to 60 between the two windows, suggesting a shift from broad early-career networking toward a more focused research identity. A first senior-authored publication in a high-impact NSCLC journal would represent the next meaningful milestone to monitor.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:39.24164+00', 'Authorship moving toward senior roles signals a maturing independent research identity in NSCLC.', 'Initiate early relationship-building now, ahead of anticipated transition into senior authorship in NSCLC.', 'early', '{"Citation volume declined by 1,041 across windows, and no confirmed senior-authored output yet limits independent influence assessment."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f1219458-650f-4143-89a3-ebc745d4cfbd', 'ad5fd815-0d94-4291-9e5c-843bf422c703', 'nsclc', 'Fabio Conforti is an Emerging Leader in NSCLC based at the European Institute of Oncology, with 13 years of career experience. Publication output doubled from 5 papers (2016–2020) to 10 papers (2021–2025), while his collaborator network expanded more than four-fold, from 21 to 92 co-authors across the same periods. The strongest signal is network momentum, which ranks at the 87th percentile globally. That expansion—from 21 to 92 collaborators—substantially outpaces his scientific output growth and anchors his composite Rising Star rank of 522 globally (68.3rd percentile). A transition into senior authorship, currently at zero senior-author share, would represent the next meaningful milestone in this profile.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:42:46.230065+00', 'Collaborator network grew four-fold, from 21 to 92, driving an 87th-percentile network momentum score.', 'Engage now around his expanding collaborator network; monitor closely for first senior-authorship transition as a relationship inflection point.', 'early', '{"Senior-author share remains zero across both periods, and citation volume declined by 958, limiting independent scientific visibility."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f193bb6b-7831-452c-9d7b-e6d694de0d59', '4ab83558-dd4d-470b-9579-4e544de590cd', 'nsclc', 'Conor Steuer is an Emerging Leader in NSCLC at Emory University, now 12 years into his career. He contributed 19 publications from 2016–2020 and 9 from 2021–2025, with a collaborator network of 69 in the earlier window narrowing to 60 in the more recent one. The defining feature of the profile is the citation pattern. Citation volume declined by 1,412 across windows, and no senior-authored output has appeared yet. A first senior-authored publication in NSCLC would mark a meaningful inflection point for this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:14.578934+00', 'Active publication output across both windows sustains visibility despite a contracting collaborator network.', 'Early relationship-building now positions the MSL ahead of a potential transition into senior authorship.', 'early', '{"No senior-authored output yet, declining citation volume, and a shrinking collaborator network warrant careful monitoring before deeper investment."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f2e62c40-2f9f-4a90-b280-cff526b11afa', 'f6ada284-68c4-4763-a571-49781f6ccb9f', 'nsclc', 'Michael Offin is a rising Lung Cancer investigator at Memorial Sloan Kettering Cancer Center whose research output has grown meaningfully across consecutive five-year windows. He authored 26 publications from Aug 2016–Jul 2021, increasing to 36 publications from Aug 2021–Jul 2026. The strongest signal is authorship positioning: senior-authored work appears in the Aug 2021–Jul 2026 window but was absent in the Aug 2016–Jul 2021 window, marking a clear shift in scientific independence. His collaborator network expanded from 194 to 273 individuals across the same periods. A first independent grant award or senior-authored publication in a high-impact journal would represent the next meaningful milestone.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:06:58.839936+00', 'Senior-authored output emerging in Aug 2021–Jul 2026 signals a clear shift toward scientific independence.', 'Engage now around emerging senior authorship and growing collaborator network before independent research agenda fully solidifies.', 'early', '{"Citation volume declined by 3,028 across the two windows, suggesting recent work has not yet accumulated broad field uptake."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f46df4da-164a-4f8a-9cc7-c78f36d819d0', 'ba7406a2-5a4b-4935-933e-72ebe16ab121', 'nsclc', 'R. Descourt is an Emerging Leader in NSCLC based at Centre Hospitalier Régional Universitaire de Brest, with 15 years of career experience. Publication output grew from 16 papers (2016–2020) to 25 papers (2021–2025), a 56% increase, supporting a Scientific Momentum percentile of 72. Network breadth expanded from 104 to 119 collaborators, underpinning a Network Visibility percentile of 79, the strongest component in this profile. The strongest signal is network visibility. It registers at the 79th percentile, reflecting meaningful reach across collaborating institutions. A transition into senior authorship, currently at zero senior-author share, would represent the next milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 02:07:58.565716+00', 'Network Visibility at the 79th percentile drives current Rising Star status, with collaborators growing to 119.', 'Monitor for first senior-authored NSCLC publication as a trigger for deeper scientific engagement.', 'early', '{"Senior-author share remains zero across both periods, and citation volume declined by 350, limiting independent scientific impact signals."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f63db81f-bf62-4fc3-97d1-3cdfc19bd5a0', 'f8c9697b-ac77-4c9d-b62e-c149a26a1b2e', 'nsclc', 'Lauren L. Ritterhouse is an Emerging Leader in NSCLC based at Massachusetts General Hospital, now 12 years into her career. The strongest signal is network expansion. Her collaborator count grew from 42 individuals in 2016–2020 to 108 in 2021–2025, a more than two-and-a-half-fold increase in raw reach. Publication output held steady, moving from 5 papers in 2016–2020 to 6 in 2021–2025, while citation volume declined by 1,069 over the same comparison. Senior-authored output has not yet appeared in the record. A first senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:52.709207+00', 'Collaborator network more than doubled, from 42 to 108, signaling rapidly expanding scientific reach.', 'Engage now around the expanding collaborator network ahead of an anticipated transition into senior authorship.', 'early', '{"No senior-authored output yet, and citation volume declined by 1,069; publication influence remains limited despite network growth."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f75b58a4-95d5-4fcc-8fcb-d34f3430fbfc', 'b00e7056-9ff1-4e88-a669-1fd11986ddca', 'nsclc', 'Anh T. Le is an Emerging Leader in NSCLC research based at the University of Colorado Anschutz Medical Campus, now 14 years into an active research career. The strongest signal is network expansion. Collaborator count grew from 75 individuals in 2016–2020 to 146 in 2021–2025, nearly doubling in raw terms. Publication output also increased, from 11 papers in 2016–2020 to 17 in 2021–2025, reflecting steady productive engagement with the field. Senior-authored output has not yet appeared in the record. A transition into senior or last authorship would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:18:50.352275+00', 'Collaborator network nearly doubled, from 75 to 146, signaling rapidly expanding scientific connectivity in NSCLC.', 'Engage now around the expanding collaborator network and monitor closely for first appearance of senior authorship.', 'early', '{"No senior-authored output yet; citation volume declined, and publication velocity delta is negative, tempering the network growth signal."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f8b39bce-a0fb-418d-9dc2-f44e5caa0062', '0e074fc9-6fa0-4d21-9d39-fd841a5d58a8', 'nsclc', 'Victor Olivas is an Emerging Leader in NSCLC based at the University of California, San Francisco, with 14 years of career experience. He contributed 8 publications from 2016–2020 and 5 from 2021–2025, reflecting a measured but sustained presence in the literature. The strongest signal is network expansion. His collaborator base grew from 78 individuals in 2016–2020 to 105 in 2021–2025, a gain of 27 colleagues that suggests deepening integration across research groups. Authorship has not yet extended to senior-authored output. A first senior-authored publication would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:49.462906+00', 'Collaborator network expanded from 78 to 105 individuals across the two most recent windows.', 'Engage now around his expanding collaborator network and monitor for a first senior-authored publication.', 'early', '{"No senior-authored output has emerged yet, and citation volume declined by 1,162 across the most recent window."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('f90439d9-1cf1-4f37-b2ac-00a226c0bcba', '3153f729-209b-4d33-9acb-833661ffa2c9', 'nsclc', 'Sehhoon Park is an Emerging Leader in NSCLC at Samsung Medical Center, with 8 years of career experience and a Rising Star composite percentile of 94.6 (global rank 90). Publication output increased more than four-fold, from 14 papers (2016–2020) to 60 papers (2021–2025), accompanied by citation volume growth of +775. The strongest signal is network expansion. Collaborator count grew from 36 to 206, a nearly six-fold increase, reflecting rapid integration into broader scientific communities. Scientific Visibility ranks at the 96th percentile, underscoring meaningful external recognition of this work. A transition into consistent senior authorship would represent the next milestone to monitor.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:54:16.816765+00', 'Publication output quadrupled to 60 papers and collaborators expanded six-fold to 206 in 2021–2025.', 'Monitor for first senior-authored publications as a trigger for deeper scientific exchange and advisory engagement.', 'moderate', '{"Senior-author share remains at 0 across both periods, indicating Park has not yet established independent scientific leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('fbc5e966-c61e-4f6e-a3fe-236e086a4b44', 'ff98dc41-7bae-4c8a-b6ec-d70f45ac218f', 'nsclc', 'Nikhil Sebastian is an Emerging Leader in NSCLC at Emory University, now eight years into his career. His publication output held steady, moving from 6 papers (2016–2020) to 7 papers (2021–2025), while his collaborator network expanded from 24 to 37 individuals across the same windows. The strongest signal is network growth. That expansion of 13 net new collaborators suggests broadening scientific engagement even as publication volume has remained relatively flat. No senior-authored output has appeared yet; a first senior-authored publication would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:17:00.054723+00', 'Collaborator network grew from 24 to 37, signaling broadening scientific engagement across recent years.', 'Early relationship-building now, with close monitoring for a first senior-authored NSCLC publication as the key milestone.', 'early', '{"No senior-authored output yet, and citation volume declined by 78, limiting evidence of independent scientific influence."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('fbd4838d-3398-4ef6-b3ca-b351f2b9aae7', '17456067-fa82-479a-b6ab-acb48ee98d5c', 'nsclc', 'Masanori Kawakami is a rising Lung Cancer investigator at The University of Texas MD Anderson Cancer Center with 13 years of career experience. The strongest signal is publication growth. Output increased from 6 papers (Aug 2016–Jul 2021) to 10 papers (Aug 2021–Jul 2026), while senior-authored work appears in the recent window but was absent in the early window, marking a meaningful shift in research independence. Collaborator count moved from 68 (Aug 2016–Jul 2021) to 62 (Aug 2021–Jul 2026), a modest contraction suggesting a more focused network. First evidence of sustained senior-authored output across consecutive publication cycles would mark a meaningful inflection in this profile.', 'rising_star_v4.1', 'claude-sonnet-4-6', '2026-08-17 08:09:00.469148+00', 'Publication output grew from 6 to 10 papers, with new senior-authored work emerging in the recent window.', 'Engage now around emerging senior authorship to build an early relationship before independent research agenda solidifies.', 'early', '{"Citation volume declined by 785 across the two windows, tempering the impact signal despite rising publication output."}'::text[], '17ded851-624e-47d0-9ae8-483f6827b227', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('fcd141a2-e6c0-416f-8444-ff0a1a74945a', '4e07b5da-c2f0-4d10-b698-473f114b3461', 'nsclc', 'Simon Heeke is an Emerging Leader in NSCLC based at The University of Texas MD Anderson Cancer Center, nine years into his career. The strongest signal is publication growth. Output increased more than twofold, from 15 papers (2016–2020) to 37 papers (2021–2025), while citation volume grew by 1,743 over the same period. Network expansion is equally striking: collaborator count grew more than fivefold, from 63 to 322 individuals across the two windows. Authorship to date has not yet included senior-authored output; a first senior-authored publication would represent the next meaningful milestone in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:15:36.652274+00', 'Citation volume grew by 1,743 alongside a fivefold expansion in collaborators, signaling rapid scientific integration.', 'Monitor for first senior-authored publication as a trigger for deeper scientific exchange and relationship-building.', 'moderate', '{"No senior-authored output has been recorded yet, limiting evidence of independent scientific leadership at this stage."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ff10fb6b-b0c3-4206-a22b-e23fd3e4eb7a', '6ab1135a-382a-48ce-bd51-fd10c00d7a1c', 'nsclc', 'Farjana Fattah is an Emerging Leader in NSCLC based at The University of Texas Southwestern Medical Center, with 12 years of career experience. Publication output held steady at 6 papers in both the 2016–2020 and 2021–2025 windows, indicating consistent, if not expanding, scholarly engagement. The defining feature of the profile is the contraction in collaborative network. Collaborator count declined from 46 in 2016–2020 to 39 in 2021–2025, suggesting a narrowing toward a more focused set of research relationships. No senior-authored output has yet appeared. First evidence of a senior-authored publication in NSCLC would mark a meaningful inflection in this profile.', 'rising_star_v4.0', 'claude-sonnet-4-6', '2026-08-05 17:16:36.331833+00', 'Sustained publication output across both windows signals continued active engagement in NSCLC research.', 'Early relationship-building now positions the MSL ahead of a potential transition into senior authorship and independent research leadership.', 'early', '{"No senior-authored output has emerged across 12 career years, and citation volume declined by 323, limiting current independent scientific visibility."}'::text[], '73b3ea82-fd5c-404f-b249-57d63ea10957', 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ff51957f-a43b-4261-931e-0fe56faa667f', '3f68613a-cb3f-4ed6-a5da-dc49004a48b6', 'nsclc', 'Daniel Kazdal is an Emerging Leader in NSCLC based at Heidelberg University, with 9 years of career experience and a Rising Star composite percentile of 78.7 (global rank 352). Publication output more than tripled, from 10 papers (2016–2020) to 34 papers (2021–2025), accompanied by a citation volume growth of +316. The strongest signal is network expansion. Collaborator count grew from 86 to 237 between the two periods, placing network momentum at the 75th percentile. Scientific visibility ranks at the 88th percentile, indicating that existing work is achieving meaningful reach. First evidence of a senior-authorship contribution would mark a meaningful inflection in Kazdal''s independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:56:57.154538+00', 'Scientific visibility at the 88th percentile, with citation volume growing by 316, signals rising field recognition now.', 'Monitor for transition into senior authorship as the primary trigger for deeper scientific engagement and relationship-building.', 'early', '{"Senior-author share remains at zero across both periods, indicating Kazdal has not yet established independent publication leadership."}'::text[], NULL, 'rising_star');
INSERT INTO public.hcp_narratives_v2 (id, hcp_id, therapeutic_area_slug, narrative_text, prompt_version, model_used, generated_at, why_now, engagement_angle, signal_strength, caution_flags, source_enrichment_run_id, cohort) VALUES ('ffdea4ef-7710-447c-8907-e6bbfee76804', '5939d338-9269-4d2b-aa44-6473fc6c0fe5', 'nsclc', 'Lele Zhang is an Emerging Leader in NSCLC at Tongji University, currently ranked 50th globally with a Rising Star composite percentile of 97.0. Publication output doubled from 13 papers (2016–2020) to 26 papers (2021–2025), while citation volume grew by 701, reflecting strong and sustained scientific momentum at the 95th percentile. The defining feature of the profile is network expansion. Collaborator count grew nearly fourfold, from 38 to 143, placing network momentum at the 84th percentile. Senior-author share remains at zero across both periods, which warrants monitoring. First evidence of a senior-authored publication would mark a meaningful inflection in Zhang''s independent scientific standing.', 'rising_star_v3.4', 'claude-sonnet-4-6', '2026-06-07 01:45:35.288825+00', 'Citation volume surged by 701 and collaborators nearly quadrupled to 143, driving a 97th-percentile Rising Star rank.', 'Monitor for first senior-authored publication as the trigger for deeper scientific engagement and relationship-building.', 'high', '{"Senior-author share is zero across both periods, suggesting Zhang has not yet established independent publication leadership."}'::text[], NULL, 'rising_star');
